-- Shipping Times: 테스트 기사 삭제 + 뉴스와이어 물류·해운 보도자료로 쓴 기사 81건 + 오피니언 10건 (바로 발행)
-- Supabase SQL 에디터에서 한 번 실행. 여러 번 실행해도 된다 (이미 있는 같은 제목 기사는 건너뛰고 없는 기사만 넣는다)
--   · 기사 날짜 = 보도자료 배포 시각, 보도자료 날짜마다 5건 이하
--   · 작성: Shipping Times 관리자 계정(없으면 편집장 → 총관리자), 기자명 '관리자', 기자 이메일 없음
--   · 오피니언은 보도자료에 나온 사실만 바탕으로 쓴 해설 칼럼 (사진 없음, 아침 7시 발행)
--   · 본문 끝 출처 문구 없음. 사진은 뉴스와이어 원본 사진 주소를 쓴다
--   · 보도자료함에 같은 보도자료가 있으면 '기사화됨'으로 연결된다

-- 1) 테스트 기사 삭제
delete from articles a using outlets o
where a.outlet_id = o.id and o.name = 'Shipping Times' and a.title like '[테스트]%';

-- 2) 기사 넣기 (발행) — 이미 올라간 같은 제목 기사는 그대로 두고 건너뛴다 (조회수·주소 유지)
with ctx as (
  select o.id as outlet_id, o.name as outlet_name,
         coalesce(
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'admin' order by p.created_at limit 1),
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'editor' order by p.created_at limit 1),
           (select p.id from profiles p where (to_jsonb(p) ->> 'is_super') = 'true' order by p.created_at limit 1),
           (select p.id from profiles p where p.role = 'admin' order by p.created_at limit 1)
         ) as author_id
  from outlets o
  where o.name = 'Shipping Times'
)
insert into articles (outlet_id, category_id, author_id, title, body, excerpt, thumbnail_url, status, published_at, tags, press_release_id)
select ctx.outlet_id, c.id, ctx.author_id, v.title,
       replace(v.body, '@@BYLINE@@', '[' || ctx.outlet_name || '=관리자 기자]'),
       v.excerpt, v.thumb, 'published', v.published_at, v.tags,
       (select r.id from press_releases r where r.guid = v.guid limit 1)
from ctx
cross join (values
  ('logistics', '미니창고 다락, AI 보관물품 관리 서비스 ‘디지털 인벤토리’ 출시', '<p>@@BYLINE@@&nbsp;셀프스토리지(공유창고) ‘미니창고 다락’을 운영하는 세컨신드롬(대표이사 홍우태)은 2일 인공지능(AI) 기반 보관 물품 관리 서비스 ‘디지털 인벤토리’를 출시했다고 밝혔다. 회사 측은 업계 최초의 AI 기반 보관 물품 관리 서비스라고 설명했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/10/2038608137_20261002110112_8921862410.png" alt="미니창고 다락 공식 앱 내 AI 기록·관리하는 ‘디지털 인벤토리’"><p><em>▲ 미니창고 다락 공식 앱 내 AI 기록·관리하는 ‘디지털 인벤토리’</em></p><p>디지털 인벤토리는 사용자가 보관 중인 물건을 사진으로 등록하고 관리할 수 있는 서비스다. 미니창고 다락 회원이면 유료 창고 서비스를 이용하지 않아도 사용할 수 있다. 회사 측은 셀프스토리지 이용 고객이 창고에 어떤 물건을 보관했는지 직접 기억하거나 별도로 기록해야 했던 불편을 덜 수 있다고 설명했다.</p><p>서비스의 핵심은 AI 이미지 인식 기술이다. 사용자가 공유창고나 보관박스, 집 안 수납공간 등을 촬영하면 AI가 사진 속 여러 물품을 자동으로 인식해 개별 이미지로 추출하고, 의류·전자기기·육아용품 등 카테고리별로 분류한다. AI 분석은 이미지 내 물품 수와 데이터 처리량에 따라 순차적으로 진행되며, 분석이 끝나면 앱 알림으로 결과를 안내한다.</p><p>사용자는 미니창고 다락 앱 홈 화면에서 ‘AI 물품 보관’을 선택해 사진을 촬영한 뒤 분석 결과를 확인하면 된다. AI가 잘못 인식한 물품은 삭제할 수 있고, 누락된 물품은 새로 촬영하거나 직접 추가할 수 있다. 저장된 물품은 이미지로 정리된 화면에서 모아볼 수 있으며, 드래그 앤 드롭 방식으로 카테고리를 바꿀 수 있다. 분류가 어려운 물품은 ‘기타’ 카테고리로 따로 관리된다.</p><p>창고뿐 아니라 집에서도 쓸 수 있다. 집 안의 물건을 촬영해 등록하면 ‘나만의 공간’에 기록돼 일상에서 사용하는 물품까지 함께 관리할 수 있다. 기업 고객은 창고에 보관 중인 기업 자산과 비품, 재고 현황 등을 기록하는 용도로 활용할 수 있다.</p><p>미니창고 다락은 지난 6월 AI 기반 지점·유닛 추천 기능을 선보인 데 이어 이번 디지털 인벤토리를 출시했다. 현재 전국 250개 매장을 운영하고 있으며, 누적 회원 수는 13만 명을 넘어섰다.</p><p>홍우태 세컨신드롬 대표는 “디지털 인벤토리는 고객의 소중한 물건을 보관하며 데이터와 운영 경험을 축적해온 다락이 새롭게 확장할 수 있는 영역”이라며 “다락 고객이 아니더라도 누구나 쉽고 편리하게 사용할 수 있는 서비스인 만큼, 일상에서 사용하는 대표 물품 관리 서비스로 키워 나가겠다”고 말했다.</p><p>세컨신드롬은 앞으로 등록한 물품을 집으로 배송받거나 판매·처분하는 기능을 추가해, 디지털 인벤토리를 물품의 보관부터 관리, 활용까지 지원하는 올인원 서비스로 확장할 계획이다.</p>', '사진 한 번으로 여러 물품을 자동 인식·분류해 등록하는 서비스로, 유료 창고 서비스를 이용하지 않는 회원도 쓸 수 있다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/10/2038608137_20261002110112_8921862410.png', '2026-10-02T04:10:00.000Z'::timestamptz, array['세컨신드롬', '미니창고 다락', '셀프스토리지', 'AI']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1043887'),
  ('shipbuilding', 'HD현대중공업, 차세대 이지스구축함 3번함 ‘대호김종서함’ 진수', '<p>@@BYLINE@@&nbsp;HD현대중공업은 30일 울산조선소에서 8200톤급 차세대 이지스구축함 3번함 ‘대호김종서함’의 진수식을 가졌다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260930154505_7635919307.png" alt="HD현대중공업이 건조해 진수한 8,200톤급 차세대 이지스구축함 3번함 ‘대호김종서함’의 모습"><p><em>▲ HD현대중공업이 건조해 진수한 8,200톤급 차세대 이지스구축함 3번함 ‘대호김종서함’의 모습</em></p><p>진수식에는 이재명 대통령과 부인 김혜경 여사, 강신철 국방부장관, 김경률 해군참모총장, 이용철 방위사업청장, 진성준 국회 국방위원회 위원장을 비롯한 국방위 소속 국회의원, 김태선·윤종오 울산 지역 국회의원, 정기선 HD현대 회장과 이상균 HD현대중공업 부회장, 주원호 HD현대중공업 사장 등 정부 및 군, 회사 관계자 350여 명이 참석했다.</p><p>대호김종서함은 조선 초 북방 개척을 이끌었던 김종서 장군의 호(號)와 이름을 따 명명됐다. 시운전을 거쳐 내년 12월 해군에 인도된다.</p><p>대호김종서함은 길이 170m, 폭 21m, 경하톤수 약 8200톤 규모로, 최대 30노트(약 55㎞/h)의 속도로 항해할 수 있다. 국내 기술로 개발한 첨단 통합 소나 체계와 탄도미사일 시스템이 탑재됐으며, 기존 세종대왕급 이지스구축함에는 없었던 요격 임무까지 수행할 수 있다고 회사 측은 설명했다.</p><p>내년 12월 전력화가 이뤄지면 해군은 세종대왕급 이지스구축함(KDX-Ⅲ Batch-Ⅰ) 3척과 정조대왕급 이지스구축함(KDX-Ⅲ Batch-Ⅱ) 3척 등 총 6척의 이지스구축함을 보유하게 된다.</p><p>HD현대중공업은 2008년과 2012년 세종대왕급 이지스구축함 1번함 ‘세종대왕함’과 3번함 ‘서애류성룡함’을 설계·건조했다. 이후 2024년 정조대왕급 이지스구축함 1번함 ‘정조대왕함’을 시작으로 2번함 ‘다산정약용함’, 3번함 ‘대호김종서함’까지 설계·건조하며 해군이 운용하게 될 이지스구축함 6척 가운데 5척을 건조했다.</p><p>이재명 대통령은 “세계 1위 기술력을 자랑하는 우리 조선산업은 우리의 자부심이자, 해양강국 대한민국을 만든 원동력”이라며 “우리 조선산업이 초격차를 유지하며 한 단계 더 올라설 수 있도록 적극 지원할 것”이라고 말했다.</p><p>정기선 HD현대 회장은 “올해가 HD현대중공업이 대한민국 최초의 국산 전투함인 ‘울산함’ 개발에 나선 지 50년이 되는 해인 만큼, 이번 진수식이 더욱 뜻깊게 다가온다”며 “세계의 바다를 지키는 함정을 우리가 만든다는 사명감을 갖고 대한민국 경제와 안보를 굳건히 수호해 나가도록 하겠다”고 말했다.</p>', '8200톤급 정조대왕급 이지스구축함 3번함으로, 내년 12월 인도되면 해군은 이지스구축함 6척을 보유하게 된다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260930154505_7635919307.png', '2026-09-30T06:48:36.000Z'::timestamptz, array['HD현대중공업', '이지스구축함', '대호김종서함', '진수']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1043698'),
  ('logistics', '현대무벡스, 금호타이어 함평 신공장 물류 자동화 720억원 수주', '<p>@@BYLINE@@&nbsp;현대무벡스는 30일 금호타이어와 720억원 규모의 물류 자동화 시스템 공급 계약을 체결했다고 밝혔다. 현대무벡스는 전남 함평 빛그린국가산업단지에 건설되는 금호타이어 신공장에 2028년 10월까지 지능형 물류 솔루션을 제공할 계획이다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260930104452_9879969583.jpg" alt="현대무벡스는 30일 720억원 규모의 금호타이어 함평 신공장 스마트 물류 구축 사업 수주에 성공해 2028년 10월까지 지능형 물류 솔루션을 구축할 계획이라고 밝혔다. 사진은 금호타이어 함평 신공장 조감도(제공: 금호타이어)"><p><em>▲ 현대무벡스는 30일 720억원 규모의 금호타이어 함평 신공장 스마트 물류 구축 사업 수주에 성공해 2028년 10월까지 지능형 물류 솔루션을 구축할 계획이라고 밝혔다. 사진은 금호타이어 함평 신공장 조감도(제공: 금호타이어)</em></p><p>금호타이어 함평 신공장은 약 50만㎡ 부지에 연간 530만 본의 생산능력을 갖춘 타이어 생산기지로 조성된다.</p><p>현대무벡스는 이번 프로젝트에서 원자재부터 반제품·완제품까지 신공장 제조공정 전반의 물류를 연계·제어하는 통합 자동화 시스템을 구현한다. 자동입출고시스템(AS/RS)을 비롯해 AGV·AMR·RGV(무인이송로봇), 컨베이어 등 자동화 설비와 WMS·WCS(창고제어시스템) 등 운영·제어 SW를 연계하는 방식이다.</p><p>여기에 공정 간 연속 무인 이송, 실시간 물류 추적·관리, AI 기반 물동량 예측, 최적 경로 제어 등의 기술을 접목해 물류 효율을 높이고 공정 소요 시간을 단축한다는 목표다. 설계부터 제작·설치, 유지보수까지 전 과정을 원스톱으로 수행하며, 현대무벡스는 30여 년간 축적한 타이어 특화 엔지니어링 역량을 바탕으로 토털 스마트 물류 솔루션을 제공할 계획이다.</p><p>현대무벡스는 현재 한국타이어앤테크놀로지 미국 테네시 공장 증설 프로젝트에서 약 1000억원 규모의 스마트 물류 구축 사업을 수행하고 있으며, 주요 국내외 타이어 기업의 유럽·중국·동남아 생산 거점에도 자동화 솔루션을 공급하고 있다. 올해는 타이어를 비롯해 2차전지·가전·유통·물류·의약 등 여러 산업에서 수주를 이어가고 있으며, 9월 현재 수주 잔고는 4000억원을 웃돈다.</p><p>현대무벡스는 금호타이어 함평 신공장은 미래 제조 경쟁력을 이끌 핵심 생산기지라며, 다년간 쌓은 타이어 스마트 물류 역량에 AI·로봇 등 첨단 지능화 기술을 접목해 생산성과 품질 경쟁력을 높이는 데 기여할 것이라고 밝혔다.</p><p>회사는 이번 수주를 계기로 고객 기반을 다변화하는 한편 금호타이어 해외 거점을 비롯한 글로벌 스마트 물류 시장 공략에도 속도를 낼 방침이다. 현대무벡스는 현대엘리베이터와 함께 현정은 회장이 이끄는 현대그룹 핵심 계열사로 물류 자동화, IT 서비스, PSD(승강장 안전문) 등의 사업을 하고 있다.</p>', '2028년 10월까지 원자재부터 완제품까지 제조공정 전반의 물류를 잇는 통합 자동화 시스템을 설계부터 유지보수까지 원스톱으로 구축한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260930104452_9879969583.jpg', '2026-09-30T01:47:04.000Z'::timestamptz, array['현대무벡스', '금호타이어', '물류 자동화', '스마트 물류']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1043640'),
  ('logistics', 'Asendia, 인천 거점 크로스보더 이커머스 물류 역량 확대', '<p>@@BYLINE@@&nbsp;글로벌 이커머스·물류 기업 Asendia는 고도화된 아웃바운드 라우팅 솔루션과 확대된 전 세계 배송 네트워크를 통해 국내 크로스보더 이커머스 물류 역량을 확대한다고 밝혔다. 인천국제공항 인근에 위치한 현지 물류센터와 글로벌 네트워크를 통해 한국에서 출발하는 소포를 월 최대 300만 건까지 처리할 수 있다는 설명이다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/1890140449_20260923193327_8045799374.png" alt="Asendia 로고"><p><em>▲ Asendia 로고</em></p><p>Asendia는 Mordor Intelligence 자료를 인용해 2030년까지 국내 크로스보더 수출 규모가 210억달러(약 31조3000억원)로 3배 가까이 늘어날 것으로 전망된다며, 물류 파트너에 대한 수요가 높아지고 있다고 밝혔다.</p><p>유럽 시장 대응책도 제시했다. 유럽연합(EU)은 2026년 7월 1일부로 150유로(약 24만3000원) 미만 소액 수입품에 대한 면세 혜택을 폐지하고, 기존 부가가치세(VAT) 납부 의무와 함께 HS 코드당 3유로의 고정 수수료를 새로 도입했다. Asendia는 신규 물류센터 서비스와 통합형 DDP(Delivered Duty Paid, 관세지급인도조건) 배송 모델을 통해 국내 브랜드가 판매 시점에 관세와 세금을 미리 처리할 수 있어, 유럽 현지 고객이 상품 수령 시 예상치 못한 추가 비용을 내거나 통관 지연을 겪는 상황을 막을 수 있다고 설명했다.</p><p>소비자가 주문 결제 단계 외에 온라인에서 관세와 세금을 납부할 수 있는 Duty PrePaid 옵션도 제공한다. 배송 라인업으로는 e-PAQ Home Delivery, e-PAQ Out-of-Home Delivery, e-PAQ Returns 등을 갖췄다. 국내 브랜드와 온라인 판매자는 Asendia의 통합 디지털 플랫폼과 글로벌 배송 네트워크를 통해 상품 픽업부터 최종 배송까지 물류 과정을 관리할 수 있다.</p><p>신희정 Asendia 한국 비즈니스 개발 매니저는 “해외 진출을 모색하는 기업들에게 수요 확보는 더 이상 주요 장벽이 아니다. 핵심 과제는 배송 기준부터 가격 책정, 컴플라이언스에 이르기까지 다양한 시장에서 발생하는 복잡성을 관리하는 것”이라며 “Asendia는 이 과정을 보다 단순하고 예측 가능하게 만들어 국내 기업들이 안정적으로 비즈니스를 확장할 수 있도록 지원하는 데 집중하고 있다”고 말했다.</p><p>Joshua Mclarin Asendia 북아시아 CEO는 “최근 자사의 Beyond Borders 연구 결과에 따르면, 한국의 유통 기업들은 물류 운영 역량을 더욱 중요시하고 있으며 유연성, 배송 속도, 배송 추적의 가시성을 핵심 과제로 꼽고 있다”며 “이는 신뢰할 수 있을 뿐만 아니라 변화하는 시장 상황에 유연하게 적응할 수 있는 물류 솔루션의 필요성을 더욱 강조하는 것”이라고 설명했다. Beyond Borders 조사는 2026년 초 글로벌 이커머스 전문가 1000명 이상을 대상으로 진행된 설문조사다.</p><p>Asendia는 2012년 La Poste(프랑스)와 Swiss Post(스위스)의 합작 투자로 설립됐으며, 북미, 영국, 유럽, 아태 지역 17개국에서 1200명 이상의 인력이 근무하고 전 세계 200개 이상의 목적지로 배송 서비스를 제공한다.</p>', '인천국제공항 인근 물류센터와 글로벌 네트워크로 한국발 소포를 월 최대 300만 건 처리하고, EU 소액 수입품 면세 폐지에 맞춰 DDP 배송 모델을 제공한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/1890140449_20260923193327_8045799374.png', '2026-09-29T00:00:00.000Z'::timestamptz, array['Asendia', '크로스보더 이커머스', 'DDP', '인천']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1043344'),
  ('shipbuilding', 'H2SITE, 에노바서 340만유로 확보…선박용 암모니아 발전 상용화', '<p>@@BYLINE@@&nbsp;H2SITE는 상업 규모의 선박용 암모니아 발전 시스템을 개발·검증하는 프로젝트 ‘하이드라노르드 파워(HydraNord Power)’를 위해 에노바(Enova)로부터 340만유로(3910만노르웨이크로네)의 자금을 확보했다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/1028147215_20260923125359_8651764297.jpg" alt="H2SITE가 상업용 해양 선박의 암모니아 발전 기술 확장 위해 에노바로부터 340만유로를 확보했다"><p><em>▲ H2SITE가 상업용 해양 선박의 암모니아 발전 기술 확장 위해 에노바로부터 340만유로를 확보했다</em></p><p>에노바는 노르웨이 정부가 국가 차원의 기후 및 에너지 전환을 가속하기 위해 설립한 기관으로, 노르웨이 정부를 대신해 기후 에너지 기금을 관리한다. H2SITE는 이번 지원으로 해양 시연 성과를 글로벌 해운 산업 전반에 적용할 수 있는 상업용 솔루션으로 확장할 수 있게 됐다고 설명했다.</p><p>하이드라노르드 파워 프로젝트는 선상에서 암모니아를 고순도 수소로 직접 변환한다. 이 시스템은 하루 최대 1톤의 수소를 생산해 해양 연료전지에 공급하며, 이를 통해 700kW의 순전력을 제공한다. 이미 가동 중인 유닛을 포함한 여러 소규모 해양 암모니아-수소 프로젝트를 기반으로, 선박 탑재 상업용 보조 전력 요건을 충족하는 출력을 갖추는 것이 특징이다.</p><p>H2SITE의 멤브레인 반응기는 암모니아 분해와 수소 분리를 단일 공정에 통합해 연료전지를 암모니아 오염으로부터 보호하면서 연료전지급 수소를 생산한다. 콤팩트한 모듈형 구조로 신조선(newbuild)과 개조(retrofit) 선박, 연료전지 전용 및 하이브리드 전력 시스템에 모두 적용할 수 있도록 설계됐으며, 여러 모듈을 병렬로 배치해 더 큰 전력 수요에 대응할 수 있다.</p><p>안드레스 갈나레스(Andrés Galnares) H2SITE 최고경영자는 “하이드라노르드 파워는 암모니아 발전을 성공적인 소규모 배치에서 상업적으로 관련 있는 전력 범위로 끌어올린다”며 “700kW 순 출력으로 우리는 복제 적용이 가능하고 대규모 설비로 확장할 수 있는 표준화된 시스템을 통해 실제 선상 전력 요건을 충족하고 있다. 에노바의 지원을 통해 대표적인 작동 조건에서 이를 시연할 수 있으며 직접 전기화가 실행 불가능한 해양 부문에서 상당한 시장 기회를 열어준다”고 말했다.</p><p>프로젝트에는 H2SITE를 비롯해 에퀴노르(Equinor), 회그 오토라이너스(Höegh Autoliners), 브리즈 십 디자인(Breeze Ship Design), 서스테이너블 카타풀트 센터(Sustainable Energy Catapult Centre), 올텍(Alltec), 마리타임 클린테크(Maritime CleanTech) 등이 참여한다. 파트너들은 선박 요구 사항, 시스템 설계, 연료전지, 현장 통합, 테스트 및 프로젝트 조율을 함께 맡는다.</p><p>완성된 시스템은 노르웨이 스토르드(Stord)에 위치한 에너지 하우스(Energy House)에 설치돼 상업 해양 운영 환경 조건을 반영한 테스트를 거친다. 개발 및 통합은 2027년에 진행되며 시운전은 2028년 초로 예정돼 있다. 하이드라노르드 파워는 초기에 심해 해운, 해양 운영, 기타 에너지 집약적 해양 부문의 보조 및 하이브리드 전력 용도를 겨냥한다.</p>', '선상에서 암모니아를 고순도 수소로 분해해 연료전지에 공급하는 ‘하이드라노르드 파워’ 프로젝트로, 700kW 순전력을 내는 시스템을 2028년 초 시운전할 예정이다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/1028147215_20260923125359_8651764297.jpg', '2026-09-23T04:30:00.000Z'::timestamptz, array['H2SITE', '암모니아', '수소 연료전지', '에노바']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1043295'),
  ('air-cargo', 'OAG ‘Megahubs 2026’…아태 공항, 상위 20곳 중 8곳', '<p>@@BYLINE@@&nbsp;OAG는 전 세계 공항의 연결성을 평가한 연례 순위 ‘Megahubs 2026’을 발표했다. 아시아태평양 지역은 글로벌 상위 20개 공항 가운데 8곳을 차지했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/3717472907_20260917013826_1751023663.jpg" alt="OAG가 전 세계 공항의 연결성을 평가한 연례 순위 ‘Megahubs 2026’ 리포트를 공개했다"><p><em>▲ OAG가 전 세계 공항의 연결성을 평가한 연례 순위 ‘Megahubs 2026’ 리포트를 공개했다</em></p><p>쿠알라룸푸르 국제공항(KUL)은 전 세계 4위이자 아시아 공항 가운데 1위를 기록했으며, 154개 목적지와 연결돼 있다. 쿠알라룸푸르 국제공항은 저비용항공사(LCC) Megahubs 순위에서도 1위에 올라 약 1만5000개의 저비용 항공편 연결 조합을 제공하는 것으로 나타났다. 에어아시아는 이 공항 전체 운항편의 34%를 차지한다.</p><p>인천국제공항(ICN)은 LCC 순위에서 2위에 올랐으며, 198개 목적지와 연결돼 있다. 싱가포르 창이공항(SIN)은 취항 목적지와 이용 가능한 저비용 항공편 연결 조합이 모두 늘면서 LCC 순위가 10위에서 5위로 올랐고, 일본 후쿠오카공항(FUK)도 LCC 순위에서 13위에서 8위로 상승했다.</p><p>중국 공항들의 회복세도 두드러졌다. 상하이 푸둥 국제공항(PVG)은 세계 19위에서 14위로, 광저우 바이윈 국제공항(CAN)은 36위에서 19위로 올랐다. 홍콩 국제공항(HKG)은 22위에서 20위로 올라서며 글로벌 상위 20위권에 다시 진입했다. 도쿄 하네다공항(HND)도 세계 9위에서 8위로 한 계단 상승했다.</p><p>아시아태평양 지역 상위 10개 공항에서 가장 높은 점유율을 차지하는 항공사의 평균 점유율은 33%로, 대부분의 다른 지역보다 낮았다. OAG는 이를 동남아시아와 동북아시아에서 서로 다른 여행객층을 대상으로 운항하는 대형 풀서비스 항공사와 저비용항공사들이 다양하게 공존하고 있음을 보여주는 것이라고 설명했다.</p><p>OAG 아시아태평양 총괄인 마유르 파텔(Mayur Patel)은 “올해 아시아태평양 지역의 수치는 두 가지 흐름을 보여준다”며 “첫 번째는 중국 항공산업이 코로나19 팬데믹 이후의 회복을 마무리했다는 것이다. 중국 공항들이 글로벌 상위 20위권에 다시 진입했으며 데이터가 이를 분명히 보여준다”고 말했다. 그는 이어 “두 번째는 저비용항공사들이 동남아시아의 항공 연결성을 어떻게 재편했는지를 보여준다는 점”이라며 “현재 이 지역 전체 좌석의 51%를 LCC가 공급하고 있으며, 이는 세계 평균을 크게 웃도는 수준”이라고 말했다.</p>', '쿠알라룸푸르 국제공항이 세계 4위·아시아 1위에 올랐고 인천국제공항은 LCC 순위 2위를 기록했으며, 중국 허브공항들은 순위를 끌어올렸다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/3717472907_20260917013826_1751023663.jpg', '2026-09-17T00:04:07.000Z'::timestamptz, array['OAG', 'Megahubs', '공항 연결성', '저비용항공사']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042781'),
  ('logistics', '맵퍼스 ‘아틀란트럭’, 상하차지팁 약 10만 건 분석 결과 공개', '<p>@@BYLINE@@&nbsp;전자지도 소프트웨어 기업 맵퍼스(대표 김명준)가 추석 연휴를 앞두고 화물차 전용 내비게이션 ‘아틀란트럭’에 축적된 약 10만 건의 상하차지팁을 분석해 화물운전자들의 현장 정보 공유 및 이용 행태를 공개했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/3696605768_20260916163716_1863766205.jpg" alt="물동량 몰리는 추석, 아틀란트럭으로 화물차 운행 효율 높인다"><p><em>▲ 물동량 몰리는 추석, 아틀란트럭으로 화물차 운행 효율 높인다</em></p><p>상하차지팁은 화물운전자들이 목적지의 진입로와 출입구, 대기시간, 실제 상하차 위치 등 지도만으로 파악하기 어려운 현장 정보를 직접 등록하고 공유하는 기능이다. 현재까지 축적된 활성 상하차지팁은 9만8000여 건으로, 전국 5만5000여 곳의 물류센터와 공장, 창고, 유통시설 등에 관한 현장 정보가 담겨 있다. 2026년 들어 9월 초까지 등록된 팁은 5만3149건으로, 2023년부터 2025년까지 3년간 등록된 4만4930건을 이미 넘어섰다.</p><p>분석 결과 가장 많이 등록된 정보는 ‘진입로·진입동선’으로 전체의 41.3%를 차지했다. 이어 ‘대기·소요시간’, ‘상하차 위치·방식’, ‘주차·대기공간’ 관련 정보가 많이 공유됐다. 화물운전자들은 진입로의 폭과 경사, 후진 진입 필요 여부, 정문·후문 및 게이트 위치 등을 활발하게 공유했다.</p><p>명절을 앞두고 등록이 늘어나는 경향도 나타났다. 2025년 추석 직전 1주간 평일 하루 평균 팁 등록량은 평시 평일보다 16% 많았다. 열람은 평일 오전에 집중돼 오전 7시부터 10시 사이에 하루 열람의 29%가 몰렸고, 오전 9시에 가장 높은 수치를 기록했다. 요일별로는 화요일부터 목요일까지의 이용이 가장 활발했다.</p><p>지역별로는 대형 물류시설과 산업단지가 밀집한 경기 지역에서 등록이 가장 많았다. 화성에서는 진입로와 주차공간, 이천에서는 위치 및 내비게이션 안내 정정, 평택과 창원에서는 입고시간과 서류 절차에 관한 정보가 상대적으로 많이 공유됐다. 차량별로는 대형 화물차 운전자가 진입·회차·주차 관련 정보를, 소형 화물차 운전자가 아파트와 유통 매장, 소규모 업체의 현장 정보를 상대적으로 자주 확인했다.</p><p>김명준 맵퍼스 대표는 “약 10만 건의 데이터를 통해 화물운전자들에게 진입로와 대기시간처럼 지도만으로 알기 어려운 현장 정보가 중요하다는 점을 확인할 수 있었다”며 “현장의 경험이 쌓일수록 처음 가는 목적지에서도 시행착오를 줄일 수 있는 만큼 상하차지팁이 화물운송의 실질적인 운행 정보로 자리잡도록 고도화해 나갈 것”이라고 말했다.</p><p>아틀란트럭은 화물차 전용 모바일 내비게이션으로, 누적 회원 수는 22만 명, 누적 길 안내는 4700만 건에 달한다.</p>', '화물운전자들이 가장 많이 공유한 현장 정보는 ‘진입로·진입동선’으로 41.3%를 차지했고, 올해 등록된 팁은 5만3149건으로 앞선 3년치를 넘어섰다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/3696605768_20260916163716_1863766205.jpg', '2026-09-17T00:00:00.000Z'::timestamptz, array['맵퍼스', '아틀란트럭', '화물운전자', '상하차지팁']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042762'),
  ('port', '어빌리티시스템즈, CTAC Asia 2026서 항만 자율주행 기술 소개', '<p>@@BYLINE@@&nbsp;어빌리티시스템즈가 지난 9월 8일부터 9일까지 태국 방콕에서 열린 ‘Container Terminal Automation Conference Asia 2026(CTAC Asia 2026)’에 참가해 자율주행 기반의 항만 물류 자동화 기술을 소개했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/2041016557_20260916140132_1737467800.jpg" alt="어빌리티시스템즈가 ‘CTAC Asia 2026’에 참가해 자율주행 기반 항만 물류 자동화 기술을 소개했다"><p><em>▲ 어빌리티시스템즈가 ‘CTAC Asia 2026’에 참가해 자율주행 기반 항만 물류 자동화 기술을 소개했다</em></p><p>CTAC Asia는 컨테이너 터미널의 자동화와 디지털 전환을 주제로 터미널 운영사와 항만 관계자, 글로벌 기술기업 등이 참여하는 전문 컨퍼런스다. 올해 행사에서는 항만 자동화와 AI, 디지털 기술 등을 활용한 차세대 터미널 운영 방향과 관련 기술이 공유됐다.</p><p>어빌리티시스템즈는 자율주행 야드트랙터 ‘ATA-Y(Autonomous Transport Ability-Yard Tractor)’와 자율주행 통합 플랫폼 ‘ADOS(Autonomous Drive-Tech Operation System)’를 중심으로 솔루션을 소개했다. ATA-Y는 컨테이너 터미널에서 컨테이너를 이송하는 기존 야드트랙터에 자율주행 시스템을 적용하는 Retrofit 방식의 솔루션으로, 터미널 운영 환경에 맞춰 컨테이너 이송 작업의 자동화를 지원한다.</p><p>ADOS는 항만 터미널 운영 시스템(TOS)의 작업계획을 차량 관제 시스템(FMS)이 작업오더와 주행 경로로 만들어 자율주행 야드트랙터에 전달하고, 차량이 작업을 수행한 뒤 운행 정보를 다시 FMS와 TOS로 전달하는 통합 자율주행 플랫폼이다.</p><p>회사는 행사 기간 부스를 운영하며 글로벌 컨테이너 터미널 운영사와 항만 자동화 분야 관계자들에게 ATA-Y와 ADOS의 기술과 적용 방안을 소개했다. 또 자율주행 야드트랙터 도입에 대한 의견을 공유하고, 실제 터미널 환경에서의 적용 가능성과 향후 발전 방향을 논의했다.</p><p>어빌리티시스템즈 자율주행물류사업 총괄 김철한 부사장은 “CTAC Asia 2026을 통해 글로벌 터미널 관계자들에게 ATA-Y와 ADOS를 소개하고, 실제 항만 운영 현장에서 필요로 하는 자율주행 기술과 자동화 방향에 대해 직접 의견을 나눌 수 있었다”며 “앞으로도 현장의 요구를 반영해 기술을 고도화하고, 국내에서 축적한 기술과 경험을 기반으로 글로벌 항만 물류 자동화 시장에서 사업 기회를 확대해 나갈 계획”이라고 말했다.</p><p>어빌리티시스템즈는 행사에서 논의된 의견과 현장 요구사항을 기술 개발에 반영하고, 해외 터미널 운영사 및 관련 기업과의 협력 가능성을 모색할 계획이다. 2004년 설립된 어빌리티시스템즈는 시스템 통합(SI), 유지 보수(SM), IT 인프라 구축, IoT, 보안 등 IT 서비스를 제공하는 기업으로, 최근에는 자율주행, 인공지능 등을 접목한 솔루션 개발에 주력하고 있다.</p>', '태국 방콕에서 열린 컨테이너 터미널 자동화 컨퍼런스에서 자율주행 야드트랙터 ‘ATA-Y’와 통합 플랫폼 ‘ADOS’를 선보였다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/2041016557_20260916140132_1737467800.jpg', '2026-09-16T07:05:00.000Z'::timestamptz, array['어빌리티시스템즈', 'CTAC Asia', '자율주행 야드트랙터', '항만 자동화']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042725'),
  ('logistics', '키넥시스, 10월 바르셀로나서 ‘키넥시온스 EMEA 2026’ 개최', '<p>@@BYLINE@@&nbsp;AI 기반 공급망 계획 및 오케스트레이션 기업 키넥시스(Kinaxis®, 토론토증권거래소 KXS)는 10월 26일부터 28일까지 그랜드 하얏트 바르셀로나(Grand Hyatt Barcelona)에서 ‘키넥시온스 EMEA 2026(Kinexions EMEA 2026)’을 개최한다고 밝혔다.</p><p>이번 콘퍼런스는 키넥시스가 올해 초 발표한 운영 오케스트레이션 비전을 바탕으로, 선도 조직들이 AI 혁신과 에이전틱 역량을 활용해 더 나은 결정을 내리고 사업 전반에서 행동을 조율하며 측정 가능한 성과를 창출하는 방식을 다룬다.</p><p>키넥시스는 AI 역량이 광범위하게 배포됐음에도 공급망 리더의 12%만이 스스로를 AI 선도기업으로 평가한다고 밝혔다. 라자트 가우라브(Razat Gaurav) 키넥시스 최고경영자와 파비엔 세트르(Fabienne Cêtre) 유럽·중동·아프리카(EMEA) 총괄부사장은 기조연설로 메인 무대를 열고, 글로벌 공급망을 재편하는 시장 동력과 운영 오케스트레이션이 사람, 프로세스, 데이터, AI를 연결해 이러한 격차를 해소하는 방식을 설명한다. 이 웰컴 세션은 전 세계에 라이브 스트리밍된다.</p><p>앤드루 벨(Andrew Bell) 최고제품책임자는 마에스트로(Maestro)의 진화를 포함한 키넥시스의 미래를 소개한다. 마닉 샤르마(Manik Sharma) 에이전틱 솔루션 책임자는 현장 전진 배치 엔지니어링(forward deployed engineering, FDE) 팀이 조직과 협력해 에이전틱 AI를 실제 기업 환경에 도입하고 가치를 창출하는 방식을 다룬다.</p><p>가우라브 최고경영자는 “공급망은 의사결정의 속도와 복잡성이 근본적으로 변화한 환경에서 운영되고 있다. AI는 공급망에 완전히 새로운 프런티어를 창출하고 있지만, 기술만으로는 비즈니스 가치를 창출하지 못한다. 북미에서 개최한 키넥시온스에서 우리는 의사결정에서 성과 도출에 이르는 과정을 더욱 긴밀하게 연결하는 운영 오케스트레이션 비전을 선보였다. 그 이후 우리는 그 비전을 전 세계 고객과 파트너를 위한 실질적인 역량으로 전환해 왔다. 이번 바르셀로나에서 우리는 참석자들에게 이러한 비전이 어떻게 현실화되고 있는지, 그리고 그것이 공급망의 미래에 무엇을 의미하는지를 보여줄 것이다”라고 말했다.</p><p>주요 기조연설자로는 인간 성과 과학자이자 작가인 제임스 휴잇(James Hewitt) 박사가 나서, AI가 더 큰 자율성을 갖게 됨에 따라 인간의 판단력과 신뢰가 왜 더 중요해지는지를 분석한다. 참석자들은 보쉬(Bosch), 캐스트롤(Castrol), 코카콜라 알 알리아 베버리지(Coca-Cola Al Ahlia Beverages), 모엣 헤네시(Moët Hennessy) 등이 복잡한 글로벌 공급망과 변동성, 변화하는 비즈니스 수요에 어떻게 대응하고 있는지 듣게 된다.</p><p>행사에서는 제품 쇼케이스, 전문가 주도 세션, 실습 부트캠프와 함께 리더십 포럼, ‘위민 인 서플라이 체인 조찬(Women in Supply Chain Breakfast)’ 포럼도 마련된다.</p>', '10월 26~28일 열리는 공급망 콘퍼런스에서 에이전틱 AI를 활용한 운영 오케스트레이션 비전과 글로벌 기업들의 공급망 운영 사례를 소개한다.', null, '2026-09-16T04:15:00.000Z'::timestamptz, array['키넥시스', '공급망', '에이전틱 AI', '키넥시온스 EMEA']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042711'),
  ('air-cargo', '대한항공, 보잉 항공기 103대·GE에어로스페이스 엔진 구매 최종 계약', '<p>@@BYLINE@@&nbsp;대한항공은 지난해 8월 미국 워싱턴DC에서 발표한 448억달러(약 60조원) 규모의 대미 구매 계획이 최종 계약으로 결실을 맺었다고 16일 밝혔다.</p><p>대한항공은 362억달러 상당의 미국 보잉(Boeing)사 차세대 고효율 항공기 103대 도입을 확정했다. 이와 함께 GE에어로스페이스(GE Aerospace)사 및 CFM인터내셔널(CFM International, 이하 CFM)사와 86억달러 가량의 항공기 예비 엔진(Spare Engine) 구매 및 엔진 정비 서비스 계약도 완료했다.</p><p>도입하는 보잉 항공기는 △777-9 20대 △787-10 25대 △737-10 50대 △777-8F 화물기 8대 등 총 103대다. 이와 함께 GE에어로스페이스 및 CFM으로부터 총 21대의 예비 엔진을 구매하고, GE에어로스페이스와 15년간 항공기 28대에 대한 엔진 정비서비스 계약도 체결했다.</p><p>대한항공은 이번 투자가 통합에 따른 중장기 성장에 대비하는 동시에 팬데믹 이후 지속되고 있는 글로벌 항공기 공급 지연에 선제적으로 대응하기 위한 것이라고 설명했다. 차세대 고효율 항공기를 도입해 기단을 현대화하고 운영 효율성을 높이는 한편, 수송력 확대와 고객 서비스 개선을 통해 경쟁력을 강화할 계획이다. 고효율 신기재 도입으로 연료 효율성을 높이고 탄소배출량을 줄인다는 방침이다.</p><p>대한항공은 지난 15일 오후 서울 영등포구 콘래드 서울 호텔에서 보잉과 공동 주최로 항공기 및 엔진 구매·서비스 양해각서(MOU)의 최종 계약 체결을 기념하는 행사를 열었다. 행사에는 조원태 한진그룹 회장과 스테파니 포프(Stephanie Pope) 보잉상용기 부문 사장 겸 최고 경영자, 가엘 메외스트(Gaël Méheust) CFM 사장 겸 최고경영자, 김정관 산업통상부 장관, 미셸 스틸(Michelle Steel) 주한미국대사, 제임스 김 주한미국상공회의소(암참) 회장 겸 대표이사, 황기연 한국수출입은행장 등이 참석했다.</p><p>조원태 회장은 “지난해 워싱턴에서 맺은 약속이 최종 계약으로 결실을 맺게 돼 매우 뜻깊게 생각한다”며 “이번 계약은 단순한 기업 간 거래를 넘어 한·미 양국의 굳건한 경제·기술 동맹을 더욱 강화하는 신뢰의 이정표”라고 말했다. 이어 “보잉이 대한항공의 날개라면 GE에어로스페이스는 우리 항공기 기단의 심장과 같은 역할을 해왔다”며 “대한항공은 보잉과 GE에어로스페이스, CFM과 함께 쌓아온 오랜 파트너십을 바탕으로 최고의 안전과 서비스를 제공하고, 양국의 교류와 경제 발전을 연결하는 역할을 충실히 해나가겠다”고 말했다.</p><p>대한항공에 따르면 한국 정부는 항공산업 경쟁력 강화를 위한 정책적 지원과 규제 개선에 힘을 보탰으며, 한국수출입은행 등 국책 금융기관도 이번 투자의 원활한 추진을 뒷받침하기 위한 금융 협력 의지를 밝혔다.</p>', '지난해 8월 발표한 448억달러 규모 대미 구매 계획이 최종 계약으로 마무리됐으며, 도입 기종에는 777-8F 화물기 8대가 포함됐다.', null, '2026-09-16T02:47:09.000Z'::timestamptz, array['대한항공', '보잉', 'GE에어로스페이스', '항공기 도입']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042712'),
  ('logistics', 'SCM FAIR·PNT FAIR 2026 폐막…사흘간 3881명 참관', '<p>@@BYLINE@@&nbsp;‘제6회 국제 운송·공급망관리 산업전(SCM FAIR 2026)’과 ‘제3회 특화망 기술 산업전(PNT FAIR 2026)’이 지난 9일부터 11일까지 사흘간 경기도 고양시 킨텍스 제1전시장 5홀에서 열린 일정을 마치고 막을 내렸다. 같은 장소·기간에 동시 개최된 두 전시회에는 3일간 총 3881명의 참관객이 찾았다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/1794294618_20260915143620_7215182434.jpg" alt="SCM Global Forum에서 Korea Air Cargo Day가 진행되고 있다"><p><em>▲ SCM Global Forum에서 Korea Air Cargo Day가 진행되고 있다</em></p><p>‘Rebuild the Supply Chain’을 슬로건으로 내건 SCM FAIR 2026은 화주 기업이 공급망 전략을 직접 수립하고 물류·운송 서비스 및 IT·자동화 시스템을 비교·구매할 수 있는 ‘화주 중심의 비즈니스 플랫폼’을 표방했다. 오우만오토메이션코리아·XYZ로보틱스코리아의 AGV·AMR 기반 물류 자동화 로봇, 딥파인의 스마트글라스 기반 AI 물류 솔루션, 위밋모빌리티의 AI 물류 최적화 솔루션 등 국내외 기업들이 참가했으며, 현장에서는 참가기업과 화주 기업 간 상담이 이어졌다.</p><p>전시 기간 사흘 내내 ‘SCM Global Forum’도 열렸다. 국제항공운송협회(IATA), 홍콩무역발전국(HKTDC), 롯데글로벌로지스 등이 참여한 항공물류·공급망 전략 세션과 ‘Korea Air Cargo Day’를 시작으로 오토스토어시스템·LG CNS·한국SCM학회의 물류 자동화·공급망 리스크 관리 전략 세션, 하이로보틱스·딥파인·테크타카·위밋모빌리티 등의 물류 로봇·AI 기반 물류 현장 혁신(AX) 세션까지 30여 명의 국내외 연사가 무대에 올랐다.</p><p>같은 장소에서 열린 PNT FAIR 2026은 ‘국내 유일의 5G 특화망(Private 5G) 기술 전문 전시회’를 내세웠다. 전시 첫날에는 과학기술정보통신부·한국방송통신전파진흥원(KCA)이 주최한 ‘AI 특화망 중소기업 스케일업 세미나’가 열려 특화망지원센터·한국전파진흥협회(RAPA)·한국로봇산업진흥원(KIRIA)·한국인터넷진흥원(KISA)이 5G 특화망 적용 사례와 정부 지원사업, 보안 동향을 공유했다.</p><p>두 전시회가 동시에 열리면서 참관객들은 물류·공급망 자동화 솔루션과 이를 뒷받침하는 통신 인프라 기술을 한자리에서 살펴볼 수 있었으며, 별도 등록 절차 없이 두 전시회를 오갈 수 있었다.</p><p>주최 측은 이번 SCM FAIR·PNT FAIR 2026이 공급망 혁신과 5G 특화망이라는 서로 다른 두 영역이 실제로는 얼마나 밀접하게 연결돼 있는지 확인할 수 있었던 자리였다며, 참가기업과 화주·수요기업 모두에게 실질적인 비즈니스 성과로 이어질 수 있도록 준비 과정부터 폐막까지 최선을 다했다고 밝혔다.</p><p>‘SCM FAIR 2027’과 ‘PNT FAIR 2027’은 2027년 10월 중 경기도 고양시 킨텍스에서 개최될 예정이다. 정확한 일정과 세부 프로그램은 추후 순차적으로 공개되며, 주최 측은 올해보다 확대된 규모로 참가기업과 참관객을 맞이할 계획이라고 밝혔다.</p>', '물류·공급망 산업전과 5G 특화망 기술 전시회가 킨텍스에서 동시에 열렸으며, 내년 행사는 2027년 10월 킨텍스에서 개최될 예정이다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/1794294618_20260915143620_7215182434.jpg', '2026-09-15T23:00:00.000Z'::timestamptz, array['SCM FAIR', 'PNT FAIR', '공급망', '5G 특화망']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042630'),
  ('shipbuilding', 'HD한국조선해양, 100MW급 부유식 발전설비 ABS 기본인증', '<p>@@BYLINE@@&nbsp;HD현대의 조선 부문 중간지주사인 HD한국조선해양은 최근 미국선급(ABS)으로부터 100MW급 부유식 발전설비(BMPP: Barge Mounted Power Plant)에 대한 기본 인증(AIP)을 획득했다고 15일 밝혔다.</p><p>이번 인증으로 HD한국조선해양은 부유식 발전설비의 기본 개념 설계, 전기 단선도, 복원성 검토 등의 핵심 기술을 확보하게 됐다.</p><p>‘바다 위 발전소’로 불리는 부유식 발전설비는 발전엔진을 활용해 해상에서 전력을 생산하고, 이를 육상 전력 인프라 구축이 어렵거나 대규모 전력 수요가 발생하는 데이터센터 및 산업단지 등에 공급하는 장치다. HD한국조선해양이 자체 개발한 부유식 발전설비는 중형 힘센(HiMSEN)엔진을 기반으로 최대 100MW 규모의 전력을 공급할 수 있다.</p><p>HD한국조선해양은 향후 상세 설계와 후속 인증 절차를 거쳐 부유식 발전설비 시장에 본격 진출할 방침이다.</p><p>최근 부유식 발전설비에 대한 시장의 관심은 확대되는 추세다. AI 기술의 확산과 데이터센터 증설로 글로벌 전력 수요가 빠르게 증가하는 가운데, 부지 확보 및 환경 규제 등의 영향으로 육상 발전소 건립에는 제약이 있기 때문이다.</p>', '중형 힘센엔진 기반의 ‘바다 위 발전소’ 핵심 기술을 확보했으며, 상세 설계와 후속 인증을 거쳐 시장에 본격 진출할 방침이다.', null, '2026-09-15T08:22:02.000Z'::timestamptz, array['HD한국조선해양', '부유식 발전설비', 'BMPP', 'ABS']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042645'),
  ('air-cargo', '대한항공, 통합 앞두고 아시아나 편명 전환…11월 2일부터', '<p>@@BYLINE@@&nbsp;대한항공은 11월 2일부터 12월 3일까지 아시아나항공 편명을 대한항공 편명으로 전환하는 ‘항공편명 변경(REAC, Re-accommodation)’을 실시한다고 14일 밝혔다. 대상은 통합 항공사 출범일인 12월 17일 이후 출발하는 기존 아시아나항공 예약 및 항공권 구매 고객이다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260914132906_3729882119.jpg" alt="대한항공 B747-8i 항공기"><p><em>▲ 대한항공 B747-8i 항공기</em></p><p>이번 조치는 오는 12월 17일 아시아나항공과의 통합 항공사 출범을 앞둔 사전 준비 차원이다. 대한항공은 통합 과정에서 기존 아시아나항공 운항편이 대한항공 운항편으로 전환됨에 따라 발생할 수 있는 고객 혼선을 최소화하고, 통합 이후에도 안정적이고 연속성 있는 서비스를 제공하기 위해 마련했다고 설명했다.</p><p>대한항공은 아시아나항공의 예약 및 항공권 정보를 사전에 이관해 고객이 변경된 예약 및 항공권 정보를 바탕으로 항공편을 이용할 수 있도록 할 계획이다. 이관은 시스템 안정성과 고객 편의를 고려해 순차적으로 진행한다.</p><p>항공편명 변경 대상 고객에게는 알림톡, 문자메시지, 이메일 등을 통해 변경 내용을 개별 안내해 출발 전 새로운 예약 및 항공권 정보를 확인할 수 있도록 한다. 또한 대한항공 홈페이지와 모바일 앱에서 아시아나항공 통합과 관련한 ‘자주 묻는 질문(FAQ)’을 제공해 고객이 통합에 따른 주요 변경 사항을 사전에 확인할 수 있도록 안내할 예정이다.</p>', '12월 17일 통합 항공사 출범 이후 출발하는 아시아나항공 예약 고객을 대상으로 예약·항공권 정보를 순차 이관한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260914132906_3729882119.jpg', '2026-09-14T04:31:58.000Z'::timestamptz, array['대한항공', '아시아나항공', '통합 항공사', '항공편명 변경']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042517'),
  ('trade', '더 록잇 컴퍼니, 다이내믹 독스 ATA 카르네 서비스 북미 확대', '<p>@@BYLINE@@&nbsp;더 록잇 컴퍼니(The Rock-It Company)는 ATA 카르네(ATA Carnet) 제공업체인 다이내믹 독스(Dynamic Dox)의 서비스 지역을 확대한다고 밝혔다. 이번 확대로 다이내믹 독스는 미국과 캐나다를 비롯해 북미 지역에 기반을 둔 파트너와 프로젝트에 ATA 카르네 서비스를 제공할 수 있게 됐다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/1028147215_20260911113905_3815188667.jpg" alt=""><p>2014년부터 영국 전역에서 서비스를 제공해 온 다이내믹 독스는 새로운 지역에서 시간 민감형 물류 프로젝트를 위한 전문 서류 준비 서비스와 국제 운송 및 긴급한 비즈니스 출장 수요를 위한 긴급 ATA 카르네 서비스를 제공한다. 다이내믹 독스는 고객에게 직접 서비스를 제공하며 24시간 지원을 운영하고 있다.</p><p>이번 발표는 다이내믹 독스가 최근 브랜드 개편을 통해 새로운 브랜드 아이덴티티를 도입하고 ‘다이내믹 독스 바이 록잇(Dynamic Dox By Rock-It)’이라는 이름으로 더 록잇 컴퍼니와의 연계성을 강화한 데 이어 나왔다. 서비스 확대는 더 록잇 컴퍼니의 글로벌 ATA 카르네 담당 부사장 아만다 바로(Amanda Barlow)가 주도하고 있다.</p><p>더 록잇 컴퍼니는 최근 캐나다, 미국 및 멕시코에서 개최된 FIFA 월드컵 2026의 공식 물류 제공업체로 참여했으며, 대회 기간 이번 확대를 통해 강화된 카르네 서비스를 활용했다. 다이내믹 독스는 앞으로도 전 세계 대규모 글로벌 이벤트에서 글로벌 팀을 지원할 예정이다.</p><p>회사 측에 따르면 더 록잇 컴퍼니와 다이내믹 독스의 경영진은 지난 1년 반 동안 세계상공회의소총회(The World Chambers Congress), 수출입업자협회(Association of Exporters and Importers, AAEI), 에어카고 콘퍼런스(AirCargo Conference), 런던상공회의소(London Chamber of Commerce and Industry, LCCI) 행사에서 연사로 참여해 통관, ATA 카르네 및 글로벌 운송에 관한 인사이트와 전략을 공유했다.</p><p>더 록잇 컴퍼니는 록잇 카고(Rock-It Cargo), 카스 바이 록잇(CARS By Rock-It), 디틀 바이 록잇(DIETL By Rock-It)을 비롯해 라이브 이벤트 및 럭셔리 상품 분야의 전문 사업부를 아우르는 글로벌 특수 물류 솔루션 플랫폼이다. 다이내믹 독스는 이제 미국과 캐나다 전역에서 이 포트폴리오 전반에 카르네 서비스를 제공한다.</p>', '영국에서 서비스를 제공해 온 다이내믹 독스가 미국·캐나다 등 북미 지역 파트너와 프로젝트에 ATA 카르네 서비스를 제공한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/1028147215_20260911113905_3815188667.jpg', '2026-09-11T04:45:00.000Z'::timestamptz, array['더 록잇 컴퍼니', '다이내믹 독스', 'ATA 카르네', '통관']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042381'),
  ('logistics', '콜드체인관리사 양성과정 12기 개강…12월 5일까지 13회 교육', '<p>@@BYLINE@@&nbsp;한국콜드체인협회(회장 서병륜)는 ‘제12기 콜드체인 전문가(콜드체인관리사) 양성과정’을 개강했다고 밝혔다. 이 과정은 콜드체인관리사 자격 과정으로, 협회는 콜드체인 전문가 양성을 목표로 개설한 국내 유일의 콜드체인 교육 프로그램이라고 설명했다. 교육은 매년 상반기(3월)와 하반기(9월) 연 2회 실시된다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/2083599902_20260908151908_6638883693.jpg" alt="‘제12기 콜드체인 전문가 양성과정’ 개강식 모습"><p><em>▲ ‘제12기 콜드체인 전문가 양성과정’ 개강식 모습</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/2083599902_20260908151929_1685163360.jpg" alt="지난 9월 5일 개강한 ‘제12기 콜드체인 전문가 양성과정’ 교육 참가자들이 단체사진을 촬영하고 있다"><p><em>▲ 지난 9월 5일 개강한 ‘제12기 콜드체인 전문가 양성과정’ 교육 참가자들이 단체사진을 촬영하고 있다</em></p><p>이번 과정은 9월 5일부터 12월 5일까지 13회에 걸쳐 진행되며 △콜드체인 산업 △식품 콜드체인관리 △의약품 콜드체인 △콜드체인 세미나·전시회 참가 및 참관 △현장견학·해외연수(싱가포르) △콜드체인 운송 △콜드체인 물류시설 △콜드체인 설비 △콜드체인 패키징 △콜드체인 관련 법규 △콜드체인 사례연구로 구성됐다.</p><p>교육은 이론 강의·과제연구와 함께 콜드체인 현장방문, 전시회 참관, 세미나 참가, 해외연수(싱가포르 콜드체인 연수)를 결합한 현장지향형 과정으로, 오프라인으로 진행된다. 장거리일 경우에는 조건부로 온라인 ZOOM 강의도 가능하다.</p><p>협회는 콜드체인 관련 여러 분야에 종사하는 교육 참가자 간 네트워크 형성과 학계·업계·정부·연구 분야 전문가와의 교류·협력을 통해 기업의 문제점 개선 및 솔루션 도출 능력을 높이고, 콜드체인 비즈니스를 통한 기업 성장에 중점을 두고 있다고 밝혔다.</p><p>이번 제12기에는 KCTC, LX판토스, 농협물류, 댄포스코리아, 세계김치연구소, 윌로그, 조양국제종합물류, 한국로지스풀, 한국컨테이너풀, 한국파렛트풀, 한국풀운영 등의 임직원이 전국 각지에서 참여했다.</p><p>교육 기간 중에는 11월 17일부터 21일까지 싱가포르 콜드체인 연수가 진행된다. 이 연수는 콜드체인에 관심이 있는 사람은 누구나 신청할 수 있다.</p><p>한국콜드체인협회는 2014년 5월 20일 농림축산식품부로부터 설립 허가를 받아 출범했으며, 현재 70여 개의 법인회원 외 개인회원, 전문위원으로 구성돼 있다.</p>', '한국콜드체인협회가 이론 강의와 현장견학, 싱가포르 해외연수를 결합한 제12기 콜드체인 전문가 양성과정을 운영한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/2083599902_20260908151908_6638883693.jpg', '2026-09-09T06:40:00.000Z'::timestamptz, array['한국콜드체인협회', '콜드체인관리사', '콜드체인', '교육']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042184'),
  ('shipbuilding', 'KRISO·해군·ADD, 해양 무인체계 발전 위한 업무협약 체결', '<p>@@BYLINE@@&nbsp;선박해양플랜트연구소(소장 정종진, KRISO)는 해군, 국방과학연구소(ADD)와 ‘해양 무인체계 발전을 위한 업무협약(MOU)’을 체결했다고 9일 밝혔다. 협약식은 지난 8일 KAIST 문지캠퍼스에서 개최된 ‘2026 Navy Sea GHOST 발전 컨퍼런스’에서 진행됐다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/3422205633_20260909085942_4363718319.jpg" alt="선박해양플랜트연구소(KRISO)는 해군, 국방과학연구소(ADD)가 ‘해양 무인체계 발전을 위한 업무협약’을 체결했다"><p><em>▲ 선박해양플랜트연구소(KRISO)는 해군, 국방과학연구소(ADD)가 ‘해양 무인체계 발전을 위한 업무협약’을 체결했다</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260909091104_5320494789.jpg" alt="‘2026 Navy Sea GHOST 발전 컨퍼런스’ 주요 참석자들이 기념촬영을 하고 있다"><p><em>▲ ‘2026 Navy Sea GHOST 발전 컨퍼런스’ 주요 참석자들이 기념촬영을 하고 있다</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/3422205633_20260909090015_5789517350.jpg" alt="KRISO 김시문 책임연구원이 ‘2026 Navy Sea GHOST 발전 컨퍼런스’에서 좌장을 맡아 세션을 진행하고 있다"><p><em>▲ KRISO 김시문 책임연구원이 ‘2026 Navy Sea GHOST 발전 컨퍼런스’에서 좌장을 맡아 세션을 진행하고 있다</em></p><p>해양 무인체계는 사람이 직접 탑승하지 않고 원격 조종이나 자동·자율 방식으로 움직이는 무인수상정, 무인잠수정, 해양로봇 등을 아우른다. 사람이 직접 수행하기 어렵거나 위험한 해양 환경에서 임무를 수행할 수 있어 해양탐사, 수색·구조, 해양 안보 등 다양한 분야에서 활용되고 있다.</p><p>세 기관은 협약에 따라 △해양 무인체계 핵심기술 공동연구 및 기술 교류 △해양 무인체계 시험장 운용 및 시험 평가·실증 협력 △해양 무인체계 전문 인력 양성 등에서 힘을 모으기로 했다. KRISO는 해양 무인체계가 개별 플랫폼의 성능뿐 아니라 통신·제어, 체계 간 연계 등 다양한 기술이 결합돼야 하는 만큼 시험·실증을 통해 완성도와 운용 신뢰성을 확보하는 것이 중요하다며, 세 기관이 각자의 전문성과 경험을 바탕으로 협력해 나갈 계획이라고 설명했다.</p><p>‘Navy Sea GHOST 발전 컨퍼런스’는 미래 해군 전력 관련 기술을 공유하고 발전 방향을 논의하는 자리로, KRISO는 2023년부터 관계기관과 함께 매년 행사를 개최해 왔다. Navy Sea GHOST는 해군이 추진하는 유·무인 복합전투체계 개념이다. 올해는 ‘AI 대전환 시대, Navy Sea GHOST의 새로운 도약’을 주제로 해군, KRISO, KAIST, ADD가 공동으로 개최했으며, 산·학·연·군의 AI·무인체계 관계자 470여 명이 참석했다.</p><p>행사에서는 △해양 무인체계 정책 발전 및 핵심기술 개발 △Navy Sea GHOST 미래전력 발전 등 2개 세션에서 전문가 발표가 이어졌다. KRISO 전봉환 해양공공디지털연구본부장은 제1세션에서 ‘무인수상정-자율무인잠수정 통합운용 구현방안’을 주제로 발표했으며, 김시문 책임연구원은 제2세션의 좌장을 맡았다.</p><p>KRISO 정종진 소장은 “기술이 빠르게 변화할수록 미래를 내다보고 나아갈 방향을 함께 그리는 것이 중요하다”며 “이번 컨퍼런스는 산·학·연·군이 지혜를 모아 해양 무인체계 기술의 발전 방향을 모색했다는 점에서 의미가 있다”고 말했다. 이어 “KRISO는 관계기관과의 협력을 지속해 해양 안보 등 다양한 분야에서 활용할 수 있는 해양 무인체계 핵심기술을 확보하고, 우리나라의 기술 경쟁력을 높이는 데 기여할 것”이라고 덧붙였다.</p>', '세 기관은 핵심기술 공동연구, 시험장 운용 및 시험 평가·실증, 전문 인력 양성 등에서 협력하기로 했다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/3422205633_20260909085942_4363718319.jpg', '2026-09-09T01:25:00.000Z'::timestamptz, array['KRISO', '해군', '국방과학연구소', '해양 무인체계']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042142'),
  ('shipbuilding', '쓰리디팩토리, 5m급 선박 프로펠러 적층제조 한·미 R&D 착수', '<p>@@BYLINE@@&nbsp;울산 소재 로봇 기반 대형 적층제조 기업 쓰리디팩토리(대표 최홍관)는 지난 9월 3일 울산 본사에서 산업통상부와 한국산업기술기획평가원(KEIT)이 지원하는 한·미 국제공동 R&amp;D 과제 ‘금속 적층제조 특화설계 기술 기반 5m급 선박 핵심 기자재 제작 기술개발 및 검증’ 사업의 킥오프 회의를 개최했다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260908163026_8547869864.jpg" alt="쓰리디팩토리가 울산에서 조선 분야 한·미 국제공동 연구개발 국책사업의 킥오프 회의를 개최하고 사업의 본격적인 출발을 알렸다. 사진은 킥오프 회의 참석자들이 기념사진을 촬영하고 있는 모습(제공=쓰리디팩토리)"><p><em>▲ 쓰리디팩토리가 울산에서 조선 분야 한·미 국제공동 연구개발 국책사업의 킥오프 회의를 개최하고 사업의 본격적인 출발을 알렸다. 사진은 킥오프 회의 참석자들이 기념사진을 촬영하고 있는 모습(제공=쓰리디팩토리)</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260908163029_2502122285.jpg" alt="쓰리디팩토리가 HD현대중공업, 신라금속, HD한국조선해양, 삼성중공업, 한화오션, 중소조선연구원, 한국생산기술연구원, 유니스트 등 산·학·연 전문가들이 참석한 가운데 조선 분야 한·미 국제공동 연구개발 국책사업의 킥오프 회의를 개최하고 사업의 본격적인 출발을 알렸다(제공=쓰리디팩토리)"><p><em>▲ 쓰리디팩토리가 HD현대중공업, 신라금속, HD한국조선해양, 삼성중공업, 한화오션, 중소조선연구원, 한국생산기술연구원, 유니스트 등 산·학·연 전문가들이 참석한 가운데 조선 분야 한·미 국제공동 연구개발 국책사업의 킥오프 회의를 개최하고 사업의 본격적인 출발을 알렸다(제공=쓰리디팩토리)</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260908163031_7015674900.jpg" alt="울산광역시 AI혁신산업실 박순철 실장이 참여 연구진에 대한 격려사를 하고 있는 모습(제공=쓰리디팩토리)"><p><em>▲ 울산광역시 AI혁신산업실 박순철 실장이 참여 연구진에 대한 격려사를 하고 있는 모습(제공=쓰리디팩토리)</em></p><p>이번 회의는 총괄 주관기관인 쓰리디팩토리를 비롯해 울산광역시, 국내 조선·기자재 기업, 산·학·연 관계자들이 대형 선박 프로펠러 제조 패러다임 전환과 글로벌 시장 진출 전략을 공유하기 위해 마련됐다. 울산광역시 박순철 AI혁신산업실장과 유니스트(UNIST) 연구부총장이 참석해 지자체 차원의 정책적 지원과 학계의 첨단 연구 역량을 집중 투입하겠다고 약속했다.</p><p>선박용 프로펠러 제작 기업인 HD현대중공업과 신라금속의 경영진도 참석했으며, HD한국조선해양, 삼성중공업, 한화오션, 중소조선연구원, 한국생산기술연구원, 유니스트 등 산·학·연 전문가들이 함께했다.</p><p>이번 과제는 대형 선박용 프로펠러의 경량화 설계부터 와이어 아크 금속 적층제조(WAAM), 정밀 가공 및 후처리, 선급 인증에 이르는 전 주기를 아우른다. 쓰리디팩토리는 이 과제가 한·미 양국의 조선업 협력 구상인 ‘마스가(MASGA, Make American Shipbuilding Great Again)’와 울산시가 역점 추진 중인 ‘제조 AX(AI 전환)’ 전략을 잇는 사업이라고 설명했다.</p><p>쓰리디팩토리는 프로펠러 제조 기업들의 현장 노하우에 공동 연구개발 기관의 AI 역량 등을 결합해 지능형 생산체계를 구축할 계획이다. 적층 경로와 열변형, 용접 공정 데이터를 실시간 분석·제어해 제작 기간과 비용을 단축하고, MRO(유지·보수·정비) 시장에 대응하는 ‘마스가’ 공급망 진입을 가속화한다는 구상이다.</p><p>회사는 이번에 확보하는 금속 적층제조 기술을 바탕으로 향후 북극항로 운항 선박용 고강도·내빙 특수 프로펠러 제조 분야까지 적용 범위를 넓힐 방침이다. 극한의 저온과 해빙 충격을 견뎌야 하는 내빙 프로펠러에 적층제조 특화설계(DfAM) 기술을 접목해 미래 친환경·극지 운송 기자재 시장을 선점하겠다는 전략이다.</p><p>최홍관 쓰리디팩토리 대표는 “울산시와 유니스트의 전폭적인 격려와 지원, 그리고 대한민국 선박 프로펠러 제조를 대표하는 최고의 기업들이 한자리에 모여 든든한 첫발을 내디뎠다”며 “유기적인 산·학·연·관 협력을 바탕으로 제조 AX 실현과 마스가 공급망 진출을 이루고, 다가오는 북극항로 시대에 대응할 수 있는 차세대 특수 프로펠러 제조 기술까지 선도적으로 확보해 나가겠다”고 밝혔다.</p>', '산업통상부·KEIT가 지원하는 한·미 국제공동 R&D 과제의 킥오프 회의를 열고 대형 선박 프로펠러 금속 적층제조 기술 개발에 나섰다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260908163026_8547869864.jpg', '2026-09-08T23:30:00.000Z'::timestamptz, array['쓰리디팩토리', '적층제조', '선박 프로펠러', '마스가']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042118'),
  ('shipping', 'HMM, 발레와 세 번째 장기운송계약…총 4.7조원 규모', '<p>@@BYLINE@@&nbsp;HMM(대표이사 사장 최원혁)이 브라질 최대 광산업체 발레(Vale)와 총 4.7조원 규모의 장기운송계약을 체결했다고 8일 밝혔다.</p><p>이번 계약은 지난해 5월과 9월 두 차례에 걸쳐 발레와 체결한 10년의 장기운송계약(총액 약 1조 665억원 규모)에 이은 세 번째 대규모 수주다. 계약 기간은 2030년부터 척당 25년간이다.</p><p>HMM은 이번 계약에 투입하기 위해 지난 6월 벌크선 8척을 신규 발주한다고 공시한 바 있다. 오는 2030년부터 순차적으로 인도받을 예정인 이 선박들은 ‘뉴캐슬막스(Newcastlemax)’급 벌크선으로, 메탄올·에탄올·중유를 모두 사용할 수 있는 3중 연료(Tri-fuel) 추진 엔진이 장착된다. HMM은 이 엔진이 세계 최초라고 설명했다.</p><p>해당 선박들은 향후 LNG나 암모니아 추진선으로 개조가 가능한 ‘LNG·암모니아 레디(Ready)형’으로 제작된다. 바람의 힘을 이용해 추진력을 얻는 풍력보조추진장치 ‘로터 세일(Rotor Sail)’ 등 친환경 설비도 탑재돼 연료 효율을 높이고 탄소 배출을 줄일 수 있다고 HMM은 밝혔다.</p>', '2030년부터 척당 25년간 이어지는 계약으로, HMM은 이를 위해 3중 연료 추진 엔진을 단 뉴캐슬막스급 벌크선 8척을 발주했다.', null, '2026-09-08T06:25:27.000Z'::timestamptz, array['HMM', '발레', '장기운송계약', '벌크선']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042111'),
  ('shipbuilding', 'HD현대, 필리핀 국방장관과 해군 현대화·조선 협력 확대 논의', '<p>@@BYLINE@@&nbsp;HD현대는 정기선 회장이 지난 7일 길베르토 테오도로 주니어(Gilberto C. Teodoro Jr.) 필리핀 국방장관과 서울에서 만나 조선·방산 분야 협력 확대 방안을 논의했다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260908152656_4072411873.jpg" alt="지난 7일(월) 오른쪽부터 HD현대 정기선 회장과 길베르토 테오도로 주니어 필리핀 국방장관이 만나 기념 촬영을 하고 있다"><p><em>▲ 지난 7일(월) 오른쪽부터 HD현대 정기선 회장과 길베르토 테오도로 주니어 필리핀 국방장관이 만나 기념 촬영을 하고 있다</em></p><p>양측은 이날 HD현대와 필리핀이 지난 10년간 구축해 온 방산 협력의 성과를 평가하고, 이를 바탕으로 필리핀 해군 현대화와 현지 조선산업 경쟁력 강화까지 협력 범위를 확대해 나갈 필요성에 공감했다. HD현대와 필리핀의 함정사업 협력은 2016년 필리핀 해군의 첫 호위함 계약을 계기로 본격화됐으며, 이후 신규 함정 건조와 후속 사업 등으로 확대돼 왔다.</p><p>면담에서는 지난해 수빅(Subic)의 HD현대필리핀 가동이 양측 산업협력의 중요한 전환점으로 언급됐다. HD현대는 이곳에서 건조한 첫 선박을 최근 진수했으며, 내년 선주사에 인도할 예정이다. 향후 현지 운영 상황에 맞춰 생산 역량도 점진적으로 강화해 나갈 계획이다.</p><p>테오도로 장관은 HD현대와의 협력이 필리핀의 해군 현대화와 조선산업 활성화 측면에서 전략적으로 중요하다는 점을 강조하고, HD현대가 필리핀 내 사업 기반을 확대하는 데 대해 환영의 뜻을 나타냈다. 또한 양측에 실질적인 도움이 되는 상호 호혜적 협력 방안을 지속적으로 모색해 나가자는 뜻을 밝혔다.</p><p>정기선 회장은 “필리핀 정부 및 해군의 일관된 정책과 협력을 바탕으로 필리핀 해군의 역량을 한 단계 신장시키는데 크게 기여하고 HD현대도 안정적으로 사업을 수행할 수 있었다”고 말했다. 이어 “상호 신뢰에 기반해 지난 10년간 사업의 성공과 확장을 가져온 경험을 바탕으로, 앞으로 상선과 함정 건조를 넘어 보다 다양한 분야에서 장기적인 산업 협력의 기회를 모색해 나갈 것”이라고 밝혔다.</p><p>HD현대는 지금까지 필리핀으로부터 12척의 함정을 수주해 6척을 인도했으며, 후속 호위함 사업 등에서도 협력을 이어 나갈 방침이다.</p>', '정기선 회장이 길베르토 테오도로 주니어 필리핀 국방장관과 만나 지난 10년간의 방산 협력 성과를 평가하고 협력 범위 확대에 공감했다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/31017998_20260908152656_4072411873.jpg', '2026-09-08T06:28:37.000Z'::timestamptz, array['HD현대', '필리핀', '함정', '방산']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1042113'),
  ('shipbuilding', '서울대 공대·삼성중공업, 미래선박기술 연구센터 설립 협약', '<p>@@BYLINE@@&nbsp;서울대학교 공과대학과 삼성중공업은 9월 2일 서울대학교 관악캠퍼스에서 ‘미래선박기술 글로벌협력 연구센터’ 설립을 위한 협약을 체결했다. 협약식에는 김영오 서울대 공과대학장과 최성안 삼성중공업 대표이사(부회장)를 비롯해 양 기관의 조선해양 분야 관계자들이 참석했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/09/3542930462_20260902172226_4042483768.jpg" alt="최성안 삼성중공업 대표이사(부회장, 왼쪽)와 김영오 서울대 공과대학장이 ‘미래선박기술 글로벌협력 연구센터’ 설립을 위한 협약 체결 후 기념사진을 촬영하고 있다"><p><em>▲ 최성안 삼성중공업 대표이사(부회장, 왼쪽)와 김영오 서울대 공과대학장이 ‘미래선박기술 글로벌협력 연구센터’ 설립을 위한 협약 체결 후 기념사진을 촬영하고 있다</em></p><p>이번 협약은 양 기관이 2016년부터 운영해 온 ‘SHI-SNU 프로그램’을 기반으로 조선해양 분야의 공동연구와 인적 교류를 확대하기 위해 마련됐다. 양 기관은 연구센터 설립을 계기로 기존 협력체계를 중장기 연구개발(R&amp;D)과 글로벌 인재 양성 중심으로 발전시킬 계획이다.</p><p>미래선박기술 글로벌협력 연구센터(센터장 김용환)는 조선해양 기술과 에너지 기술을 융합한 중장기 연구과제를 수행하고, 글로벌 연구 네트워크 구축과 산학협력 교육을 통한 연구인력 양성에 나선다. 특히 조선해양 원천기술과 에너지 기술을 연계해 친환경·차세대 연료 기술과 미래선박 분야의 연구과제를 수행하며, 이를 통해 미래 조선해양 시장을 선도할 핵심 기술을 확보하고 관련 분야의 연구역량과 전문인력 양성 기반을 강화할 방침이다.</p><p>김영오 서울대 공과대학장은 “이번 연구센터 설립은 양 기관이 산학협력의 강도를 전략적으로 한 단계 높이는 의미가 있다”며 “연구센터가 조선해양 기술 분야의 글로벌 선도자로 자리매김하기를 기대한다”고 말했다.</p><p>최성안 삼성중공업 대표이사는 “서울대학교의 우수한 연구역량과 인재가 삼성중공업의 발전은 물론 한국 조선해양산업의 경쟁력 강화에 큰 기여를 해왔다”며 “앞으로도 지속적인 협력을 이어나가 산학협력의 성공적인 모델이 될 것”이라고 밝혔다.</p>', '2016년부터 운영해 온 ‘SHI-SNU 프로그램’을 바탕으로 협력체계를 중장기 R&D와 글로벌 인재 양성 중심으로 발전시킨다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/09/3542930462_20260902172226_4042483768.jpg', '2026-09-02T23:55:00.000Z'::timestamptz, array['서울대', '삼성중공업', '미래선박', '산학협력']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1041727'),
  ('shipping', 'KRISO, WMU·KMI와 스웨덴 말뫼서 해사 국제컨퍼런스 공동 개최', '<p>@@BYLINE@@&nbsp;선박해양플랜트연구소(KRISO, 소장 정종진)는 세계해사대학(World Maritime University, 이하 WMU), 한국해양수산개발원(KMI)과 함께 8월 26일부터 28일까지 3일간 스웨덴 말뫼 WMU에서 ‘WMU Maritime Affairs Conference 2026’을 개최했다고 31일 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/3422205633_20260828105313_6946922215.jpg" alt="WMU Maritime Affairs Conference 2026 단체 사진"><p><em>▲ WMU Maritime Affairs Conference 2026 단체 사진</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/3422205633_20260828105320_4128153498.jpg" alt="WMU Maritime Affairs Conference 2026 주요 참석자 및 연사 단체 사진"><p><em>▲ WMU Maritime Affairs Conference 2026 주요 참석자 및 연사 단체 사진</em></p><p>WMU Maritime Affairs Conference는 세계 각국의 산업계, 학계, 정부 및 국제기구 등의 해사 전문가들이 모여 견해를 공유하고 미래 해사산업의 발전 방향을 모색하는 국제 컨퍼런스로, 이번 행사에는 약 180명이 참석했다.</p><p>올해 행사는 ‘해운산업의 실질적 전환(Transforming Shipping in Practice)’을 주제로 탈탄소화, 디지털화, 북극항해의 세 가지 축에서 전문가 발표와 패널토론이 진행됐다. 대체연료 도입, 선상 탄소포집 기술, 자율운항선박·AI 관련 안전·규제, 북극항해를 둘러싼 지정학·거버넌스 등이 논의됐으며, 지난해와 달리 북극항해가 새로운 핵심 의제로 추가됐다.</p><p>정종진 KRISO 소장은 개회식에서 공동주최 기관장으로서 영상 메시지를 전하며 기술혁신을 실제 산업의 변화로 이어가기 위한 실증·검증과 국제 협력의 필요성을 강조했다. 강희진 KRISO 친환경해양개발연구본부장은 첫날 기조연설자로 나서 친환경·디지털 전환 과정에서 신기술의 안전성을 확보하기 위해서는 시험평가와 해상실증이 중요하다고 설명했다.</p><p>이 밖에도 KRISO 연구진들이 분야별 발표자로 참여했다. 이성엽 KRISO 국제해사기술센터장은 선상 탄소포집 기술을, 정성엽 책임연구원은 북극해운 관련 미래 기술개발 전망을 주제로 발표했다.</p><p>KRISO는 친환경·자율운항 등 첨단 해양모빌리티 분야의 한-유럽 기술 협력을 강화하기 위해 2024년 노르웨이 오슬로에 KRISO Europe Center를 설치하고 현지 연구 네트워크 구축과 국제 공동연구 발굴·지원 등을 추진해 왔다. KRISO는 앞으로도 KRISO Europe Center를 중심으로 유럽의 연구기관 및 산업계 등과 전략적 파트너십을 강화하고, 공동연구와 기술·정책 교류 등 협력을 이어 나갈 계획이다.</p><p>정종진 KRISO 소장은 “해사산업의 변화와 전환은 어느 한 분야나 국가의 노력만으로 이뤄낼 수 없으며, 다양한 주체가 서로의 지식과 경험을 모으는 것이 중요하다”며 “KRISO도 연구와 기술을 실제 산업에 적용할 수 있는 해법으로 발전시키고, 국제 협력을 통해 지속가능한 해사산업의 미래를 만들어가는 데 역할을 다하겠다”고 말했다.</p>', '‘해운산업의 실질적 전환’을 주제로 탈탄소화·디지털화·북극항해 논의…약 180명 참석', 'https://file.newswire.co.kr/data/datafile2/data/2026/08/3422205633_20260828105313_6946922215.jpg', '2026-08-30T23:30:00.000Z'::timestamptz, array['KRISO', 'WMU', '해사 컨퍼런스', '북극항해']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1041369'),
  ('shipping', 'Adbri·CSL, 배터리 구동 자가하역식 벌크선 남호주서 운항 개시', '<p>@@BYLINE@@&nbsp;호주 건설자재 기업 Adbri와 The CSL Group(CSL)은 배터리 구동 자가하역식 벌크선(self-unloading bulk carrier) ‘MV Yampu’의 운항 개시를 기념했다고 발표했다. 양사는 이 선박을 세계 최초의 배터리 구동 자가하역식 벌크선이라고 소개했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/3717472907_20260828025843_2879292959.jpg" alt="MV Yampu가 남호주 버컨헤드에서 첫 석회석 화물을 하역하고 있다"><p><em>▲ MV Yampu가 남호주 버컨헤드에서 첫 석회석 화물을 하역하고 있다</em></p><p>CSL이 특별 설계한 길이 125m의 MV Yampu는 남호주 요크 반도(Yorke Peninsula)의 Adbri 클라인 포인트(Klein Point) 채석장에서 석회석을 선적해 애들레이드 버컨헤드(Birkenhead)에 있는 Adbri 시멘트 제조 시설까지 운송한다. 이 석회석은 남호주와 빅토리아 전역의 주택, 학교, 병원, 도로 및 주요 사회기반시설 건설에 사용되는 현지 생산 시멘트의 핵심 원자재로, 클라인 포인트 석회석은 100년 이상 남호주의 시멘트 제조를 지탱해 왔다.</p><p>선박의 배터리는 버컨헤드 시설에 정박하는 동안 충전되며, MV Yampu는 이를 통해 전체 운항 시간의 약 40%를 배터리 전력만으로 운항할 수 있다. 선내 배터리 용량은 6758kWh다. 양사는 기존 선박인 MV Accolade II와 비교해 연간 디젤 사용량을 50만 리터 이상 줄이고, 스코프 1(Scope 1) 배출량은 약 40% 감축할 것으로 예상했다.</p><p>재화중량톤수(DWT) 1만1900톤의 적재 능력을 갖춘 이 선박은 연간 약 270만 톤의 석회석을 운송할 예정이며, 연간 석회석 운송 능력은 35% 확대된다. MV Yampu는 향후 100% 배터리 전력만으로 운항할 수 있도록 설계됐으며, CSL이 소유·운영하고 호주 선원들이 승선한다.</p><p>CSL의 루이스 마르텔(Louis Martel) 최고경영자(CEO)는 “MV Yampu는 우리의 탈탄소화 여정에서 중요한 진전을 의미하며, 실용적인 혁신이 상업 운항의 요구를 충족하면서도 실질적인 환경적 혜택을 창출할 수 있음을 보여준다”고 말했다. 이어 “궁극적으로 이 선박은 스마트한 설계가 어떻게 성능을 향상할 수 있는지를 보여준다”고 덧붙였다.</p><p>Adbri의 폴 헤드(Paul Headd) 최고경영자(CEO)는 “클라인 포인트와 버컨헤드에서 근무하는 직원들에게 이번 일은 단순히 새로운 선박 한 척이 운항을 시작하는 것 이상의 의미가 있다”며 “이는 직원들의 미래이자 남호주 제조업의 미래를 위한 투자”라고 말했다. 그는 “Yampu는 우리의 공급망을 강화하고 지역 일자리를 지원하는 동시에 배출량 감축과 탄탄한 호주 제조업 기반 유지가 함께 이뤄질 수 있음을 보여준다”고 덧붙였다.</p><p>선박명 ‘Yampu’는 Adbri 임직원을 대상으로 한 명칭 공모를 통해 선정됐으며, 남호주 지역의 나룽가(Narungga) 및 카우르나(Kaurna) 언어로 ‘돌고래’를 뜻한다.</p>', '남호주 석회석 운송에 투입…운항 시간의 약 40%를 배터리 전력으로 운항하고 연간 디젤 사용량 50만 리터 이상 절감 예상', 'https://file.newswire.co.kr/data/datafile2/data/2026/08/3717472907_20260828025843_2879292959.jpg', '2026-08-28T00:31:50.000Z'::timestamptz, array['CSL', 'Adbri', '배터리 선박', '자가하역식 벌크선']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1041343'),
  ('shipping', '씨벤티지, 9개 해상 초크포인트 리스크 ‘초크포인트 모니터’ 출시', '<p>@@BYLINE@@&nbsp;해양 물류 데이터 분석 및 가시화 솔루션 기업 씨벤티지(SeaVantage)가 전 세계 주요 해상 초크포인트의 위험도와 선박 통항 변화를 모니터링할 수 있는 ‘초크포인트 모니터’를 출시했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/2040964263_20260825135428_3553974840.png" alt="씨벤티지 초크포인트 모니터로 본 호르무즈 해협 상황"><p><em>▲ 씨벤티지 초크포인트 모니터로 본 호르무즈 해협 상황</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/2040964263_20260825135449_9355500876.png" alt="씨벤티지 초크포인트 모니터로 본 바브엘만데브 해협 상황"><p><em>▲ 씨벤티지 초크포인트 모니터로 본 바브엘만데브 해협 상황</em></p><p>씨벤티지는 초크포인트 리스크에 지정학적 이슈와 선박 통항량, 유가 등 여러 요인이 복합적으로 작용해 개별 뉴스나 단일 지표만으로는 현재 상황을 파악하기 어렵다며, 분산된 리스크 정보를 한곳에서 확인하고 물류 및 공급망 담당자가 주요 항로의 변화를 빠르게 파악할 수 있도록 이 서비스를 개발했다고 설명했다.</p><p>초크포인트 모니터는 호르무즈 해협, 바브엘만데브 해협 등 전 세계 9개 주요 초크포인트의 위험 수준과 통항 변화를 한 화면에서 비교할 수 있도록 구성됐다. 각 초크포인트의 위험 수준은 선박 통항량, 지정학적 상황, 유가, 금융 스트레스 등 리스크 요인을 종합한 위험 지수로 제공된다.</p><p>최근 24시간 통항량과 전주 및 평시 대비 증감률, 7일 평균 선종 구성 등도 제공되며, 선종에는 탱커, 벌크선, 컨테이너선, LNG·LPG선 등이 포함된다. 30일·60일·90일 기준 통항 추이와 Brent·WTI 유가 변화, 기상·사고·혼잡·인프라 장애 등 비지정학적 리스크 요인, 안전·운영 이슈와 해운 영향, 향후 전망도 함께 확인할 수 있다.</p><p>씨벤티지에 따르면 초크포인트 모니터에서 호르무즈 해협은 현재 9개 초크포인트 가운데 가장 높은 위험 수준을 보이고 있으며, 8월 24일 기준 통항량도 평시보다 80% 이상 낮은 수준으로 나타났다. 씨벤티지는 이란의 선박별 통항 통제가 이어지면서 통항이 일부 재개됐더라도 항로 정상화를 판단하기 어려운 상황이라고 설명했다.</p><p>씨벤티지는 또 Reuters 보도를 인용해 중국 국영 선사 COSCO Shipping Energy Transportation과 China Merchants Energy Shipping이 7월 말 이후 푸자이라와 오만 인근에서 STS(Ship-to-Ship) 방식으로 원유를 인수하는 등 페르시아만 외부를 활용하는 운송 전략을 확대하고 있다고 전했다.</p><p>씨벤티지는 특정 해협의 통항 재개 소식만으로 실제 운항 상황이 정상화됐다고 판단하기는 어렵다며, 초크포인트 모니터를 통해 위험 수준과 평시 대비 통항 변화, 선종별 통항 추이 등 여러 지표를 함께 확인함으로써 물류 및 공급망 담당자가 항로 리스크를 보다 객관적으로 판단할 수 있도록 지원하겠다고 밝혔다.</p>', '위험 지수·통항량·선종 구성·유가 등을 한 화면에서 제공…호르무즈 해협, 9개 초크포인트 중 위험 수준 가장 높아', 'https://file.newswire.co.kr/data/datafile2/data/2026/08/2040964263_20260825135428_3553974840.png', '2026-08-25T06:20:00.000Z'::timestamptz, array['씨벤티지', '초크포인트', '호르무즈 해협', '해상 리스크']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1041088'),
  ('shipbuilding', 'KRISO, 덴마크 DTU와 첫 해사 워크숍…친환경 해운·해양로봇 논의', '<p>@@BYLINE@@&nbsp;선박해양플랜트연구소(소장 정종진, 이하 KRISO)는 덴마크공과대학교(Technical University of Denmark, 이하 DTU)와 현지 시각 8월 21일 덴마크 DTU에서 ‘KRISO-DTU 해사 워크숍’을 개최했다고 24일 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/3422205633_20260824095216_3940808514.jpg" alt="워크숍 참석자들이 단체 기념 촬영을 하고 있다"><p><em>▲ 워크숍 참석자들이 단체 기념 촬영을 하고 있다</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/3422205633_20260824095220_1446815856.jpeg" alt="워크숍 발표 전경"><p><em>▲ 워크숍 발표 전경</em></p><p>이번 워크숍은 지난해 11월 KRISO와 DTU가 체결한 업무협약(MOU)을 바탕으로 양 기관 간 연구 교류를 구체화하고 향후 연구 협력 가능성을 모색하기 위해 마련됐다. 당시 양 기관은 해양 탄소중립·디지털 전환·에너지 기술 분야 연구개발, 전문가 교류 활성화, 연 1회 정례 기술 교류회 개최, 국제 공동 프로젝트·프로그램 참여 기회 발굴 등에 협력하기로 했다.</p><p>첫 워크숍에서는 친환경 해운과 해양로봇을 주요 주제로 다뤘다. 친환경 해운 분야에서는 선상 탄소포집·저장(OCCS), 전기추진시스템 등의 기술과 연구 방향을 공유했고, 해양로봇 분야에서는 피지컬 AI 기반 해양로봇 기술, 다중 센서 기반 수중-수상 매핑 기술 등을 중심으로 연구개발 현황을 소개했다. 발표에 이어 진행된 토론에서는 질의응답과 의견 교환을 통해 향후 협력 방안을 논의했다.</p><p>KRISO와 DTU는 앞으로도 정례적인 워크숍을 통해 연구 성과와 기술을 공유하며 협력을 확대해 나갈 예정이다. 서로 다른 해양환경에서 축적한 연구·실증 경험과 전문성을 접목해 공동 연구 주제를 발굴하고, 호라이즌 유럽(Horizon Europe) 등 국제 연구개발 프로그램에 함께 참여하는 기회도 모색할 계획이다.</p><p>KRISO 정종진 소장은 “DTU와의 이번 워크숍은 양 기관의 연구 역량과 전문성을 바탕으로 새로운 시너지를 만들어가는 첫 자리였다”며 “KRISO는 앞으로도 이러한 교류를 지속해 실질적인 연구 협력으로 이어가는 한편, 글로벌 연구기관과의 네트워크를 확대해 우리나라 조선해양 기술의 국제 경쟁력을 한층 높여 나가겠다”고 말했다.</p>', '지난해 11월 업무협약 후속 조치…정례 워크숍으로 협력 확대하고 호라이즌 유럽 등 국제 공동연구 참여 모색', 'https://file.newswire.co.kr/data/datafile2/data/2026/08/3422205633_20260824095216_3940808514.jpg', '2026-08-24T02:55:00.000Z'::timestamptz, array['KRISO', 'DTU', '해사 워크숍', '국제협력']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1040966'),
  ('shipbuilding', 'HD현대중공업, 페루 시마조선소서 상륙지원함 ‘침보테함’ 진수', '<p>@@BYLINE@@&nbsp;HD현대중공업은 최근 페루 시마(SIMA)조선소에서 페루 해군의 신형 상륙지원함 1번함 ‘침보테(Chimbote)함’의 진수식을 실시했다고 19일 밝혔다. HD현대중공업은 이번 진수가 해외 현지에서 함정을 공동건조한 첫 성과라고 설명했다.</p><p>진수식은 케이코 후지모리(Keiko Fujimori) 페루 대통령이 참석해 직접 주관했으며, 라파엘 벨라운데(Rafael Belaunde) 페루 국방장관, 페데리코 하비에르 브라보 데 루에다(Federico Javier Bravo de Rueda Delgado) 페루 해군총사령관, 최종욱 주페루 대한민국 대사, 주원호 HD현대중공업 사장 등 양국 정부 및 관계자들이 참석했다.</p><p>침보테함은 HD현대중공업과 시마조선소가 공동 건조한 신형 상륙지원함 2척 중 1번함이다. HD현대중공업은 2024년 4월 페루 해군으로부터 호위함, 원해경비함, 상륙지원함 등 총 4척의 함정을 수주했으며, 이 중 상륙지원함 2척을 동시 건조해 왔다. 2번함 ‘탈라라(Talara)함’도 이달 초 육상에서의 건조 공정을 모두 완료했다.</p><p>두 함정은 다목적 상륙지원함으로 인력 및 물자 수송을 비롯해 군수지원, 재난·재해 대응 등의 임무를 수행할 예정이며, 모두 페루의 주요 항구도시 이름을 따 명명됐다.</p><p>이번 사업은 HD현대중공업이 설계 및 기술지원을 제공하고 시마조선소가 현지 생산시설을 활용해 블록 생산 및 조립, 의장, 시험·시운전 등에 참여하는 방식으로 진행됐다. HD현대중공업은 이를 통해 함정 수출의 개념을 ‘국내 건조 후 완제품 인도’에서 ‘기술협력을 통한 현지 공동생산’으로 바꿨다고 설명했다. 국방부와 방위사업청은 페루 정부와의 협력을 추진하며 함정 수출을 지원했고, 주페루 한국대사관과 코트라도 페루 정부와의 소통 및 현지 네트워크를 활용해 지원했다.</p><p>케이코 후지모리 페루 대통령은 “우리는 단순히 함정 한 척을 건조하는 것이 아니라 미래를 위한 역량을 구축하고 있다”며 “이번 프로젝트가 일자리 창출, 인적자원 개발 및 조선산업 관련 공급망 확대에도 기여하고 있다”고 말했다. 주원호 HD현대중공업 사장은 “이번 침보테함의 진수는 민·관이 하나돼 이뤄낸 팀코리아의 성과라 할 수 있다”며 “K-함정의 경쟁력을 높여 수출 시장을 다변화해 나갈 것”이라고 밝혔다.</p><p>한편 HD현대중공업은 현재 페루 해군의 1500톤급 차세대 잠수함 기본설계를 진행하고 있으며, 설계 완료 후 즉시 선도함 건조에 착수하기 위해 페루 정부와 협력을 이어가고 있다.</p>', '페루 해군 신형 상륙지원함 2척 중 1번함…HD현대중공업이 설계·기술지원하고 시마조선소가 현지 생산', null, '2026-08-19T08:18:30.000Z'::timestamptz, array['HD현대중공업', '페루 해군', '상륙지원함', '함정 수출']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1040780'),
  ('shipbuilding', 'HD현대·테라파워·현대건설 경영진 회동…미국 SMR 협력 논의', '<p>@@BYLINE@@&nbsp;HD현대는 정기선 회장과 빌 게이츠 테라파워 창업자 겸 회장, 크리스 르베크 테라파워 최고경영자, 이한우 현대건설 대표이사가 14일 서울에서 만났다고 밝혔다. 지난 5월 3사가 ‘차세대 나트륨 원자로 사업 협력을 위한 3자 업무협약’을 체결한 이후 각 사 최고경영진이 만난 첫 자리다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/1028147215_20260814153152_3812713903.jpg" alt="정기선 HD현대 회장이 빌 게이츠 테라파워 창업자 겸 회장과 2025년 8월 22일(금) 만나 SMR 사업 협력방안에 대해 논의하고 있다"><p><em>▲ 정기선 HD현대 회장이 빌 게이츠 테라파워 창업자 겸 회장과 2025년 8월 22일(금) 만나 SMR 사업 협력방안에 대해 논의하고 있다</em></p><p>이 자리에서 참석자들은 현재까지 진전된 사항을 바탕으로 육상 원자로의 상용화를 위한 협력 방안을 논의했다. 3사는 5월 협약을 통해 소듐냉각고속로(SFR) 기반의 차세대 SMR인 ‘나트륨 원자로’ 상용화에서 테라파워는 나트륨 기술 제공을, HD현대는 주기기 제조를, 현대건설은 EPC(설계·조달·시공)를 담당하는 협력체계를 구축한 바 있다.</p><p>정기선 회장은 “기술, 제조, EPC를 아우르는 협력체계를 기반으로 차세대 원자로의 상용화에 속도를 낼 수 있을 것으로 기대된다”며 “자체적인 기술 개발과 글로벌 기업들과의 협업을 통해 SMR 발전 수요 증가에 적극적으로 대응해 나가겠다”고 밝혔다.</p><p>HD현대는 그간 공급망 협력 범위를 구체화해 왔으며, 추후 원자로 용기를 연간 2~3기 공급하는 것을 목표로 상용화에 앞서 생산 설비 투자에 속도를 낼 예정이다.</p><p>HD현대는 2022년 테라파워에 대한 투자를 시작으로 2024년 12월에는 테라파워로부터 나트륨 원자로에 탑재되는 원통형 원자로 용기를 수주해 제작해왔다. 2025년 3월에는 테라파워와 ‘나트륨 원자로의 상업화를 위한 제조 공급망 확장 전략적 협약’을 체결하고 1년여간 나트륨 원자로의 제조 타당성, 가격 경쟁력, 인도 일정 등에 대한 연구를 수행했으며, 올해 5월에는 테라파워 나트륨 원자로 주기기의 핵심 설비를 제작 및 공급하는 우선 협상 대상자로 지정됐다.</p><p>HD현대에 따르면 미국은 약 95GW 규모의 세계 최대 원전 시장으로 전 세계 시장의 약 25%를 차지한다. 미국 내 원전 설비 상당수가 1970년대 가동을 시작해 노후 원전 교체 수요가 늘어날 것으로 예상되며, 최근 데이터센터 증가로 전력 수요가 급증하면서 원자력 발전에 대한 수요도 높아지고 있다.</p>', '5월 3자 업무협약 이후 첫 최고경영진 만남…HD현대, 원자로 용기 연간 2~3기 공급 목표로 생산 설비 투자 속도', 'https://file.newswire.co.kr/data/datafile2/data/2026/08/1028147215_20260814153152_3812713903.jpg', '2026-08-14T06:36:09.000Z'::timestamptz, array['HD현대', '테라파워', 'SMR', '나트륨 원자로']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1040601'),
  ('shipping', 'HMM, 9월 인도-동아프리카 컨테이너 서비스 ‘GIA’ 개설', '<p>@@BYLINE@@&nbsp;HMM(대표이사 사장 최원혁)이 9월부터 인도와 동아프리카를 연결하는 컨테이너 서비스 ‘GIA(Gulf - India - East Africa Service)’를 개설한다고 5일 밝혔다.</p><p>GIA 서비스는 최원혁 사장 부임 이후 추진 중인 컨테이너 부문 ‘허브 앤 스포크(Hub &amp; Spoke)’ 전략의 두 번째 아프리카 지선망으로, 인도 및 중앙아시아발 화물이 집결하는 나바셰바(Nhava Sheva)와 문드라(Mundra)를 중심으로 동아프리카를 연결한다.</p><p>첫 출항은 9월 넷째 주 나바셰바에서 시작되며, 2800TEU급 컨테이너선 5척이 투입된다. 기항지는 나바셰바(인도) - 문드라(인도) - 다르에스살람(Dar es Salaam, 탄자니아) - 몸바사(Mombasa, 케냐) 순이다. 중국 COSCO SHIPPING, 싱가포르 PIL, 대만 인터아시아라인(INTERASIA LINES) 등 4개사가 공동 운항하며, 향후 중동(Gulf) 지역까지 기항지를 확장할 계획이다.</p><p>HMM은 스페인 알헤시라스를 거점으로 한 북아프리카 및 서아프리카 노선(MA2)에 이어 이번 동아프리카 노선(GIA)을 개설함으로써 아프리카 전역에 걸친 중장기 네트워크 확장의 교두보를 마련했다고 설명했다. 신규 기항하는 케냐와 탄자니아는 항만 인프라와 내륙 물류 개발이 지속되고 있는 동아프리카의 대표 관문 항만이다.</p><p>HMM은 최근 글로벌 공급망 불확실성이 커지면서 화주들이 안정적인 스케줄과 다양한 목적지 연결성을 중시하는 경향이 커지고 있다며, 허브앤스포크 전략을 기반으로 초대형선이 기항하는 원양 글로벌 서비스와 지역 지선망을 결합한 네트워크를 구축해 시장 변화에 대응하고 고객 서비스 경쟁력을 높이겠다는 방침을 밝혔다.</p><p>이를 위해 HMM은 기존에 보유한 초대형선과 시너지를 낼 수 있는 피더선을 지속 확보하고 있다. HMM은 최근 공시를 통해 중장기 전략을 업그레이드하며 컨테이너 선대를 2030년까지 147만TEU, 166척으로 확대할 계획을 밝힌 바 있다.</p>', '2800TEU급 5척 투입해 나바셰바·문드라와 다르에스살람·몸바사 연결…‘허브 앤 스포크’ 전략의 두 번째 아프리카 지선망', null, '2026-08-05T01:25:38.000Z'::timestamptz, array['HMM', '동아프리카', 'GIA', '허브 앤 스포크']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039950'),
  ('shipbuilding', 'HD현대, 2분기 매출 22조4094억원·영업이익 4조1246억원', '<p>@@BYLINE@@&nbsp;HD현대(대표이사 정기선·조영철)는 31일 공시를 통해 2026년 2분기 연결기준 매출 22조4094억원, 영업이익 4조1246억원을 기록했다고 밝혔다.</p><p>전년 동기 대비 매출은 30.2%, 영업이익은 262.2% 증가했다. HD현대는 조선, 건설기계, 정유, 전력기기 등 주요 사업 전반에서 견조한 실적을 거둔 결과라고 설명했다. 상반기 누적 기준으로는 매출 42조113억원, 영업이익 6조9594억원을 기록했다.</p><p>조선·해양 부문의 HD한국조선해양은 생산성 향상과 고수익 선박 매출 확대 등의 영향으로 매출이 전년 동기 대비 20.2% 증가한 8조9270억원, 영업이익은 72.5% 증가한 1조6451억원을 기록했다. HD한국조선해양은 고부가가치 친환경 선박 시장에서의 우위를 이어가고, 선별 수주 전략을 바탕으로 수익성을 강화해 나갈 예정이다.</p><p>HD현대마린솔루션은 선박 부품 및 서비스 관련 AM 부문과 친환경 개조, 디지털 솔루션 등 핵심사업이 고루 성장하며 전년 동기 대비 24.1% 늘어난 5804억원의 매출을 기록했다. 영업이익은 17.6% 증가한 976억원이다. 회사는 AM 사업 경쟁력을 강화하고 데이터센터용 발전 엔진 시장과 부유식 데이터센터 개조 시장 공략에 박차를 가할 계획이다.</p><p>건설기계 부문의 HD현대사이트솔루션은 글로벌 업황 개선, 차세대 신모델 굴착기 판매 증가, 산업용·방산 엔진 매출 확대에 따라 매출과 영업이익이 전년 동기 대비 각각 17.9%, 79.6% 증가한 2조5235억원과 2720억원을 기록했다.</p><p>에너지 부문의 HD현대오일뱅크는 중동지역 지정학적 리스크 장기화에 따른 국제유가 변동성 확대와 수급 불안정 등 대외 환경 변화의 영향으로 매출 9조4774억원, 영업이익 1조8241억원을 기록했다. 윤활기유와 석유화학 사업의 수익성 개선이 실적에 긍정적으로 작용했다. HD현대오일뱅크는 하반기 국내 에너지 공급 안정을 위해 다양한 대체 원유 도입과 탄력적 원유 조달 방안 운용 등을 지속 추진할 방침이다.</p><p>HD현대일렉트릭은 배전 부문 매출 확대와 해외시장 수익성 향상 등으로 매출과 영업이익이 전년 동기 대비 각각 26%, 37.3% 증가한 1조1418억원과 2870억원을 기록했다. 회사는 기존 전력기기 사업과 함께 배전·회전기기 사업을 강화해 지속 가능한 성장 기반을 구축할 계획이다.</p>', '전년 동기 대비 매출 30.2%, 영업이익 262.2% 증가…조선·건설기계·정유·전력기기 등 주요 사업 전반 실적 견조', null, '2026-07-31T07:26:43.000Z'::timestamptz, array['HD현대', '2분기 실적', 'HD한국조선해양', 'HD현대오일뱅크']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039767'),
  ('people', 'KRISO 정종진 신임 소장 취임…임기 3년', '<p>@@BYLINE@@&nbsp;선박해양플랜트연구소(KRISO)는 정종진 소장이 7월 30일자로 취임하고 공식 임기를 시작했다고 밝혔다. 정 소장의 임기는 2026년 7월 30일부터 3년이다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/07/3422205633_20260730183654_2564644210.jpg" alt="정종진 선박해양플랜트연구소장"><p><em>▲ 정종진 선박해양플랜트연구소장</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/31017998_20260806095137_4332130602.jpg" alt="정종진 선박해양플랜트연구소장 이력"><p><em>▲ 정종진 선박해양플랜트연구소장 이력</em></p><p>정 소장은 1969년생으로 서울대학교에서 조선해양공학 학사(1992년), 석사(1994년), 박사(2002년) 학위를 취득했다. 2000년 HD현대중공업에 입사해 약 26년간 선박·해양플랜트 연구개발 분야에서 실장, 전문위원(상무) 등을 거쳤으며, 국내 최초 상업용 부유식 해상풍력 부유체 개발 프로젝트를 총괄했다. 2026년에는 HD현대중공업 자문역(상무)으로 위촉됐으며, 같은 해 울산대학교 글로컬 JA교수를 역임했다.</p><p>정 소장은 현장 경험을 바탕으로 KRISO를 국가와 산업의 미래 수요에 선제적으로 대응하고 조선·해양산업의 경쟁력을 높이는 핵심 연구 기관으로 발전시켜 나갈 계획이다. 이를 위해 해양기술 혁신을 이끄는 연구개발을 추진하고, 연구 성과가 정책과 산업, 국제표준으로 연결될 수 있도록 기관의 역량을 집중할 방침이다.</p><p>신임 소장 취임식은 8월 3일 KRISO 대전 본소에서 개최될 예정이다. KRISO는 1973년 설립된 선박해양플랜트 분야 연구기관이다.</p>', 'HD현대중공업에서 약 26년간 선박·해양플랜트 연구개발 경력…7월 30일자로 공식 임기 시작', 'https://file.newswire.co.kr/data/datafile2/data/2026/07/3422205633_20260730183654_2564644210.jpg', '2026-07-31T00:30:00.000Z'::timestamptz, array['KRISO', '정종진', '신임 소장']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039693'),
  ('shipbuilding', 'STX엔진, 머스크 1만9000TEU급 컨테이너선 엔진 공급 계약', '<p>@@BYLINE@@&nbsp;STX엔진은 중국 NTS조선소와 1만9000TEU급 초대형 컨테이너선 총 14척(확정 8척, 옵션 6척)에 탑재될 선박용 엔진 계약을 체결했다고 30일 밝혔다. 이번 계약은 덴마크 머스크(MAERSK)의 초대형 컨테이너선 프로젝트에 친환경 엔진을 공급하는 것이다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/07/31017998_20260729132313_9013244133.jpg" alt="왼쪽부터 NTS조선소 관계자와 STX엔진 글로벌사업본부장이 계약 체결 후 기념사진을 촬영하고 있다"><p><em>▲ 왼쪽부터 NTS조선소 관계자와 STX엔진 글로벌사업본부장이 계약 체결 후 기념사진을 촬영하고 있다</em></p><p>STX엔진은 선박 1척당 친환경 이중연료(DF, Dual Fuel) 엔진 2대와 디젤 엔진 2대를 교차 공급하는 ‘하이브리드 엔진 공급 전략’을 적용한다. 회사는 가스와 디젤오일을 함께 사용하는 이 방식이 국제해사기구(IMO)의 환경 규제를 충족하는 동시에 선박 건조 및 운항 비용을 낮출 수 있어 조선소와 선주 양측의 요구 조건을 만족시켰다고 설명했다.</p><p>STX엔진은 이번 수주가 해외 선박 엔진 시장에 직접 진출해 거둔 첫 대형 성과라고 밝혔다. 회사는 지난 50년간 선박용 엔진을 전문적으로 생산해 왔으며, 그동안 축적된 기술력과 국내 주요 조선소에 친환경 이중연료 엔진을 납품한 실적을 바탕으로 이번 수주전에서 기술력을 입증했다고 설명했다.</p><p>STX엔진은 이번 계약이 지난 반세기 동안 쌓아온 엔진 제조 노하우와 친환경 기술력이 글로벌 무대에서 인정받은 결과라며, 앞으로도 고효율·친환경 엔진 솔루션을 지속적으로 선보이며 해외 시장을 확장해 나가겠다고 밝혔다.</p><p>STX엔진은 1976년 12월 엔진 전문 생산 업체로 출범해 방위 산업용 엔진과 선박용 디젤 엔진, 육상용 플랜트 엔진, 가스 엔진, 철도 차량 엔진 등을 생산하고 있다.</p>', '중국 NTS조선소와 최대 14척(확정 8척·옵션 6척)분 계약…척당 이중연료 엔진 2대·디젤 엔진 2대 공급', 'https://file.newswire.co.kr/data/datafile2/data/2026/07/31017998_20260729132313_9013244133.jpg', '2026-07-29T23:30:00.000Z'::timestamptz, array['STX엔진', '머스크', '이중연료 엔진', '컨테이너선']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039553'),
  ('logistics', '콜로세움, 온라인수출 중소기업 물류 지원사업 2차 수행기관 선정', '<p>@@BYLINE@@&nbsp;콜로세움코퍼레이션(대표 박진수, 이하 콜로세움)이 중소벤처기업부와 중소벤처기업진흥공단이 추진하는 ‘2026 온라인수출 중소기업 물류 지원사업’의 2차 수행기관으로 선정됐다고 29일 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/07/3667402467_20260729102946_6280605387.png" alt="콜로세움은 2026년 8월 7일까지 고비즈코리아에서 해외 물류비 최대 3000만원 지원 대상자를 모집하고 있다"><p><em>▲ 콜로세움은 2026년 8월 7일까지 고비즈코리아에서 해외 물류비 최대 3000만원 지원 대상자를 모집하고 있다</em></p><p>이번 선정으로 미국, 일본, 동남아 등 해외 진출을 준비하거나 진행 중인 국내 중소기업은 콜로세움을 통해 해외 물류비의 최대 70%, 최대 3000만원을 정부 지원금으로 활용할 수 있게 됐다. 이 사업은 전자상거래 방식으로 수출 중이거나 수출을 희망하는 중소기업의 물류 부담 완화를 위해 마련됐으며, 지난 16일부터 올해 두 번째 참여기업 모집을 시작해 8월 7일까지 접수를 받는다.</p><p>신청 대상은 중소기업확인서를 보유한 법인 및 개인사업자로, 기업 규모와 수출 실적 구간에 따라 최소 1000만원부터 최대 3000만원까지 지원받는다. 지원 항목은 국내외 창고 보관, 풀필먼트(보관·포장·출고·배송·반품), 현지 물류 운영 등이며, 해외 수출과 함께 국내 풀필먼트를 이용하는 경우도 지원 대상에 포함된다.</p><p>콜로세움은 수행기관으로서 현지 창고 확보부터 통관, 풀필먼트, 배송에 이르는 해외 진출 기업의 공급망 구축 전 과정을 지원한다. 회사는 자체 창고를 소유하는 대신 국내외 물류센터와 택배사, 화물운송사를 연결하는 네트워크형 물류 모델을 기반으로 미국(LA), 일본(도쿄)을 포함해 65개 이상의 글로벌 물류 거점을 운영하고 있다고 설명했다.</p><p>콜로세움이 개발한 물류 운영 플랫폼 ‘Colo AI’는 아마존, 쇼피파이 등 글로벌 마켓플레이스를 포함해 300개 이상의 판매 채널과 연동된다. 회사 측은 클라우드 기반으로 평균 3일 이내 시스템 구축이 가능해 별도의 대규모 개발이나 초기 투자 없이도 해외 물류 운영 환경을 갖출 수 있다고 밝혔다.</p><p>콜로세움은 2025년부터 서울창업허브 글로벌 진출 프로그램에 참가해 해외 시장 진입 전략을 다졌으며, 이를 발판으로 65개 이상의 글로벌 물류 거점을 확보하고 네트워크형 물류 모델을 고도화해왔다고 밝혔다.</p><p>박진수 콜로세움 대표는 “해외 진출을 준비하는 중소기업들은 물류비뿐 아니라 현지 운영 경험과 통관, 파트너 확보 과정에서 많은 어려움을 겪는다”며 “정부 지원사업 수행기관으로서 기업들이 지원금을 활용해 안정적으로 해외 공급망을 구축하고 글로벌 시장에 진출할 수 있도록 돕겠다”고 말했다.</p><p>콜로세움코퍼레이션은 전 세계 65개 이상 물류센터 네트워크를 기반으로 AI 물류 SaaS ‘Colo AI’와 글로벌 물류 전문가 조직 FD(Fulfillment Director)를 운영하는 기업으로, 2025년 매출 1000억원을 달성했으며 2028년 IPO를 목표로 하고 있다.</p>', '해외 진출 중소기업은 콜로세움을 통해 해외 물류비의 최대 70%, 최대 3000만원을 정부 지원금으로 활용할 수 있다. 올해 두 번째 참여기업 접수는 8월 7일까지다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/07/3667402467_20260729102946_6280605387.png', '2026-07-29T02:50:00.000Z'::timestamptz, array['콜로세움코퍼레이션', '온라인수출 물류 지원사업', '풀필먼트', '중소기업 수출']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039534'),
  ('shipping', 'CSL, 시만두 철광석 프로젝트용 환적 셔틀선 첫 척 인도', '<p>@@BYLINE@@&nbsp;CSL 그룹(CSL Group, 이하 CSL)은 기니의 시만두(Simandou) 철광석 프로젝트에 투입될 환적 셔틀선(Transhipment Shuttle Vessel, TSV) 5척 가운데 첫 번째 선박인 ‘MV Wontanara’호를 인도했다고 발표했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/07/3717472907_20260729104308_4627912679.jpg" alt="MV Wontanara호의 인도는 CSL이 시만두(Simandou) 프로젝트를 위해 설계·개발한 전용 환적 셔틀선(TSV) 5척 가운데 첫 번째 선박의 취항을 의미한다. 이들 선박이 모두 운항을 시작하면 세계에서 가장 빠르고 효율적인 환적 선단을 구성하게 될 예정이다(사진=CSL 그룹)"><p><em>▲ MV Wontanara호의 인도는 CSL이 시만두(Simandou) 프로젝트를 위해 설계·개발한 전용 환적 셔틀선(TSV) 5척 가운데 첫 번째 선박의 취항을 의미한다. 이들 선박이 모두 운항을 시작하면 세계에서 가장 빠르고 효율적인 환적 선단을 구성하게 될 예정이다(사진=CSL 그룹)</em></p><p>이 TSV 선단은 CSL이 설계하고 중국선박공업그룹(CSSC) 산하 청시조선소(Chengxi Shipyard)에서 건조했다. 4만1800톤의 재화 중량톤수(DWT)에 시간당 최대 1만2000톤의 철광석을 이송할 수 있는 듀얼 붐 자가 하역 시스템을 갖췄으며, CSL은 이 선단이 세계에서 가장 빠르고 효율적인 환적 셔틀선으로 평가받는다고 밝혔다.</p><p>선박은 강변 터미널과 해상 벌크 운반선 사이에서 대량의 철광석을 운송하도록 특수 설계됐다. 하천 운항에 최적화된 흘수(吃水)가 낮은 선체와 기동성 및 조종 성능을 위한 5기의 아지무스 추진기(azimuth thrusters), 안전성과 운항 효율을 높이는 양방향 운항(bi-directional navigation) 기능이 적용됐다.</p><p>CSL은 개념 설계 단계부터 엔지니어링, 건조, 인도에 이르기까지 이번 환적 솔루션 개발 전 과정을 주도했다. 자가 하역선(Self-Unloading Vessel) 설계와 환적 운영 분야의 경험을 바탕으로 선단의 기술적 요구사항을 수립했으며, 엔지니어링 및 설계 과정을 총괄하고 건조 전 과정에 걸쳐 감독 역할을 수행했다.</p><p>루이 마르텔(Louis Martel) CSL 사장 겸 최고경영자(CEO)는 “이 선단의 첨단 설계와 화물 처리 역량은 복잡한 물류 과제를 실용적이고 고성능의 해상 운송 솔루션으로 전환해 온 CSL의 전문성을 보여준다”고 강조했다. 이어 “우리는 고객과 긴밀히 협력해 얕은 수심 환경에서도 대규모 철광석을 안전하고 효율적으로, 그리고 지속적으로 수출할 수 있는 통합 환적 시스템을 설계했다”고 덧붙였다.</p><p>MV Wontanara호는 시만두 철광석 프로젝트 지원을 위해 운항에 투입될 TSV 5척 가운데 첫 번째 선박이며, 나머지 선박들도 향후 수개월에 걸쳐 순차적으로 인도될 예정이다.</p><p>CSL 그룹은 캐나다 몬트리올에 본사를 둔 해상 운송 기업으로, 미주, 호주, 유럽, 아프리카 전역에서 사업을 운영하며 건설, 철강, 에너지, 농식품 산업 고객의 화물을 운송하고 있다. 회사는 자사를 세계 최대 규모의 자가 하역선 보유·운영사라고 소개했다.</p>', 'CSL 그룹이 기니 시만두 철광석 프로젝트에 투입될 환적 셔틀선(TSV) 5척 가운데 첫 번째 선박 ‘MV Wontanara’호를 인도했다. 나머지 선박은 향후 수개월에 걸쳐 순차 인도된다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/07/3717472907_20260729104308_4627912679.jpg', '2026-07-29T02:16:27.000Z'::timestamptz, array['CSL', '시만두', '환적 셔틀선', '철광석']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039539'),
  ('shipping', '씨벤티지, 해양산업 AI 전환 협의회서 해운 데이터 표준화 방안 발표', '<p>@@BYLINE@@&nbsp;해양·물류 데이터 기업 씨벤티지가 7월 22일 한국해양진흥공사가 개최한 ‘2026년 제2차 해양산업 AI 전환 실무협의회’에서 ‘표준화된 해양 데이터를 통한 선사 AX 기반 구축’을 주제로 해운 데이터 표준화와 AI 활용 기반 구축 방안을 발표했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/07/2040964263_20260728110344_9518909532.jpg" alt="정영배 씨벤티지 상무가 7월 22일 열린 ‘2026년 제2차 해양산업 AI 전환 실무협의회’에서 해운 데이터 표준화와 선사 AX 기반 구축 방안을 발표하고 있다"><p><em>▲ 정영배 씨벤티지 상무가 7월 22일 열린 ‘2026년 제2차 해양산업 AI 전환 실무협의회’에서 해운 데이터 표준화와 선사 AX 기반 구축 방안을 발표하고 있다</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/07/2040964263_20260728110353_2478800785.png" alt="씨벤티지가 ‘2026년 제2차 해양산업 AI 전환 실무협의회’에서 소개한 해양 데이터 연계 구조. 여러 소스에서 개별 수집하던 선박·항만 데이터를 표준화해 하나의 인터페이스로 기존 운영 시스템에 연계하는 방식을 보여준다(제공=씨벤티지)"><p><em>▲ 씨벤티지가 ‘2026년 제2차 해양산업 AI 전환 실무협의회’에서 소개한 해양 데이터 연계 구조. 여러 소스에서 개별 수집하던 선박·항만 데이터를 표준화해 하나의 인터페이스로 기존 운영 시스템에 연계하는 방식을 보여준다(제공=씨벤티지)</em></p><p>씨벤티지는 기업이 AI 개념 검증(PoC)을 실제 운영 환경으로 확대하는 과정에서 데이터 형식과 기준의 차이를 마주할 수 있다고 설명했다. 선박 위치와 실제 입출항 시간, 항만 체류시간, 선사별 운항 스케줄 등 데이터는 이미 존재하지만 출처와 관리 방식이 달라 분석에 앞서 확인하고 정리하는 과정이 필요하다는 것이다. 예를 들어 선박의 입항·접안·출항 시간은 출처에 따라 이벤트 판별 기준이나 기록 시점이 달라질 수 있다.</p><p>씨벤티지는 전산화와 업무 프로세스 자동화 이후 데이터를 통합·표준화하는 ‘데이터화’를 AX(AI 전환)에 필요한 단계로 제시하고, 주요 데이터화 영역으로 선박의 Actual Schedule과 포트콜 정보, 항만 체류 시간과 혼잡도, 선사별 운항 스케줄을 꼽았다. 기존 ERP나 운영 시스템을 교체하지 않고 필요한 데이터를 API로 단계적으로 연결하는 방식도 소개됐다.</p><p>선사 간 운항 스케줄의 표준화와 연계 방안으로는 씨벤티지가 구축을 주도하고 있는 ‘Schedule Data Hub’가 소개됐다. 선사별로 다른 스케줄 형식과 코드를 단일 스키마로 표준화하고 API와 웹훅을 통해 스케줄과 변경 정보를 공유하는 구조로, 이메일과 엑셀, PDF 등을 통한 수기 입력 과정에서 발생할 수 있는 업데이트 지연과 데이터 불일치를 줄이는 것이 목표다.</p><p>씨벤티지는 현재 국내 선사와 Schedule Data Hub의 초기 검증을 진행하고 있으며, 데이터 연계 및 참여 범위를 단계적으로 확대할 계획이다. 스케줄 데이터를 연동하는 참여 선사에는 통합 스케줄 데이터를 무료로 제공하고, 장기적으로 국내 기반의 네트워크를 글로벌 해운 데이터 네트워크로 확장한다는 방침이다.</p><p>이와 별도로 국내 선사의 Actual Schedule 데이터 연계 사례도 공유됐다. 약 94개 항구와 256개 터미널, 1000척 규모의 선박을 대상으로 실제 입항·접안·출항 정보를 표준화해 기존 운영 시스템에 전달한 사례로, 씨벤티지는 Actual Schedule과 ATA·ATB·ATD를 표준화해 새롭게 확인된 운항 이벤트를 API로 전달하고 일정 시간 동안 데이터가 수신되지 않는 선박은 운영자가 확인할 수 있도록 별도로 안내했다. 해당 선사는 자체 Actual Schedule 체계를 새로 구축하는 대신 표준 데이터 API를 기존 시스템에 연계했다.</p><p>정영배 씨벤티지 상무는 “AI를 실제 운영에 적용하려면 모델뿐 아니라 입력 데이터가 같은 기준으로 정리돼 있는지도 함께 살펴볼 필요가 있다”며 “이번 발표에서는 선박·항만·스케줄 데이터를 표준화하고 기존 시스템과 연결하는 방안과 함께 선사 간 데이터 연결을 확대하기 위한 Schedule Data Hub의 구축 방향을 소개했다”고 말했다.</p>', '씨벤티지가 한국해양진흥공사 주최 ‘2026년 제2차 해양산업 AI 전환 실무협의회’에서 선박·항만·스케줄 데이터 표준화 방안과 선사 간 스케줄 연계를 위한 ‘Schedule Data Hub’ 구축 방향을 소개했다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/07/2040964263_20260728110344_9518909532.jpg', '2026-07-28T04:50:00.000Z'::timestamptz, array['씨벤티지', '해운 데이터 표준화', 'AX', 'Schedule Data Hub']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039445'),
  ('shipbuilding', 'HD현대마린솔루션, 2분기 매출 24.1%·영업이익 17.6% 증가', '<p>@@BYLINE@@&nbsp;HD현대마린솔루션은 27일 공시를 통해 올해 2분기 매출 5804억원, 영업이익 976억원을 기록했다고 밝혔다. 전년 동기 대비 각각 24.1%, 17.6% 증가한 수치다.</p><p>회사는 선박 부품 및 서비스 관련 AM 부문과 친환경 개조, 디지털 솔루션 등 핵심사업이 전반적으로 성장한 가운데 벙커링 사업의 매출이 늘어난 데 따른 결과라고 설명했다. 3대 핵심사업의 매출은 전년 동기 대비 25.2% 증가한 3567억원, 벙커링 사업은 22.3% 늘어난 2237억원을 기록했다.</p><p>AM 부문은 신조 시장 호조로 서비스 대상 선박이 지속 증가하면서 2분기 실적 향상을 주도했다. 부품 출고량은 전년 평균 대비 약 27% 증가한 6만 건을 넘어 월간 최대 기록을 경신했으며, AM 서비스를 제공한 선박은 누적 기준 1만168척에 달했다. 여기에 육상 발전사업 및 에콰도르 정비계약 매출이 더해지며 AM 부문 매출은 전년 동기 대비 19.6% 증가한 2750억원을 기록했다.</p><p>친환경 솔루션 부문은 주요 선박 개조 프로젝트가 본격화되며 전년 동기 대비 38.1% 증가한 453억원의 매출을 올렸다. HD현대마린솔루션은 선박평형수처리장치 및 탈황설비 설치와 같은 1세대 개조사업을 종료하고, 친환경 연료 전환 및 탄소 저감을 위한 차세대 개조사업으로 영역을 확대해 글로벌 가스 선박 개조 수요를 선점한다는 방침이다.</p><p>디지털 솔루션 부문은 신조 물량 확대로 신규 솔루션 장착 선박이 늘어난 가운데 선박에서 전력을 생산하는 축 발전기 및 특수선용 제어시스템 매출이 증가해, 전년 동기보다 65.5% 늘어난 364억원의 매출을 기록했다.</p>', 'HD현대마린솔루션이 올해 2분기 매출 5804억원, 영업이익 976억원을 기록했다. AM·친환경 솔루션·디지털 솔루션 등 3대 핵심사업과 벙커링 사업 매출이 모두 늘었다.', null, '2026-07-27T07:30:03.000Z'::timestamptz, array['HD현대마린솔루션', '2분기 실적', 'AM 부문', '벙커링']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039387'),
  ('shipping', 'HMM, 스페인~서아프리카 신규 컨테이너 서비스 ‘MA2’ 개시', '<p>@@BYLINE@@&nbsp;HMM(대표이사 사장 최원혁)이 7일 스페인과 서아프리카를 연결하는 신규 컨테이너 서비스 ‘MA2(Mediterranean West Africa)’의 첫 항차를 시작한다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/07/1028147215_20260707105455_1332334616.jpg" alt="HMM이 유럽-아프리카 지역 허브 항만으로 활용하는 스페인 알헤시라스 항만의 자영터미널(TTIA)"><p><em>▲ HMM이 유럽-아프리카 지역 허브 항만으로 활용하는 스페인 알헤시라스 항만의 자영터미널(TTIA)</em></p><p>MA2 서비스는 최원혁 사장 부임 이후 컨테이너 부문 전략으로 수립한 ‘허브 앤 스포크(Hub &amp; Spoke)’ 전략의 첫 번째 노선으로, 유럽-아프리카 지역에 적용한 지선망이다. 원양 항로인 FIM(극동-인도-지중해) 노선의 주요 기항지이자 HMM 자영 터미널이 있는 스페인 알헤시라스를 중심으로 서아프리카 주요 항만을 연결한다.</p><p>MA2 서비스에는 총 5척의 피더선이 투입돼 왕복 35일이 소요되며, 기항지는 알헤시라스 - 탕헤르(모로코) - 다카르(세네갈) - 테마(가나) - 레키(나이지리아) - 아비장(코트디부아르) 순이다.</p><p>‘허브 앤 스포크’ 전략은 대형선이 원양 항로 거점(Hub)을 맡고 중소형 피더선(Feeder Ship)이 지선망(Spoke)을 연결해 서비스를 강화하는 전략이다. HMM은 다양한 출발지와 목적지가 연결돼 화주들에게 유연한 운송 경로를 제공할 수 있으며, MA2 서비스의 경우 혼잡도가 높은 서아프리카 항만 구간을 분리 운영함으로써 초대형선의 운항 정시성을 향상시키는 한편 지선망의 기항지를 유연하게 조정할 수 있다고 설명했다.</p><p>이번 네트워크 다변화는 3월 최원혁 사장 부임 이후 HMM이 추진해 온 컨테이너 부문 경쟁력 강화 방침에 따른 것이다. HMM은 원양과 근해 간 네트워크를 확대하고 자영 터미널 연계성을 높이는 등 질적 성장에 주력해 왔다고 밝혔다. 피더선 확보도 이어가 지난해부터 올해까지 22척의 신조 발주를 포함해 리세일, 중고선 매입 등 다양한 방식으로 총 27척의 피더선을 확보했으며, 이를 현재 보유한 초대형선단과 연계해 효율성 및 수익성을 극대화할 방침이다.</p><p>HMM은 글로벌 주요 항만을 중심으로 대형선과 피더선 연계 서비스를 지속적으로 확대할 계획이라며 선대 및 네트워크 확장, 친환경 선박 확보 등을 통해 글로벌 선사로의 도약을 이어가겠다고 밝혔다.</p>', 'HMM이 알헤시라스를 거점으로 서아프리카 주요 항만을 잇는 ‘MA2’ 서비스의 첫 항차를 시작한다. ‘허브 앤 스포크’ 전략의 첫 번째 노선으로, 피더선 5척이 투입된다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/07/1028147215_20260707105455_1332334616.jpg', '2026-07-07T02:05:52.000Z'::timestamptz, array['HMM', 'MA2', '서아프리카', '허브 앤 스포크']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1038071'),
  ('shipping', 'Veson Nautical, AI 기반 해운 통합 플랫폼 공식 출시', '<p>@@BYLINE@@&nbsp;Veson Nautical이 IMOS, CoCaptain, Mail 그리고 새롭게 출시된 Vessel Insights와 Bunker Insights를 하나의 환경으로 통합한 AI 기반 플랫폼 ‘Veson Platform’을 공식 발표했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/06/3717472907_20260630172545_3443483093.jpg" alt="‘Veson Platform’은 해운 업계 종사자들이 핵심 운영 시스템(System of Record)을 기반으로 고도화된 업무 프로세스, 협업 기능 그리고 신뢰할 수 있는 데이터에 통합적으로 접근할 수 있도록 지원한다"><p><em>▲ ‘Veson Platform’은 해운 업계 종사자들이 핵심 운영 시스템(System of Record)을 기반으로 고도화된 업무 프로세스, 협업 기능 그리고 신뢰할 수 있는 데이터에 통합적으로 접근할 수 있도록 지원한다</em></p><p>Veson Platform은 해운 업계 종사자들이 핵심 운영 시스템(System of Record)을 기반으로 업무 프로세스, 협업 기능, 데이터에 통합적으로 접근할 수 있도록 지원한다. 회사 측은 전 세계 선주, 선박 운영사, 용선사, 원자재 트레이더들이 사용하는 IMOS에 축적된 해운 계약과 업무 프로세스에 대한 전문 지식과 업무 맥락을 AI에 접목했다고 설명했다.</p><p>고객사는 Veson Platform을 통해 기존 IMOS 기능을 그대로 활용하면서 항차 관리 및 운항을 위한 신규 기능, 업무 맥락을 이해하는 AI, 데이터 인사이트를 이용할 수 있다. 초기에는 클레임 업무 지원을 위해 출시된 CoCaptain은 플랫폼 전반에 통합된 대화형 AI 기능으로 발전해, 업무 중 별도의 화면 전환 없이 항차 정보, 과거 입출항 이력, 거래 상대방 관련 정보를 확인하고 자연어 대화로 질문·분석하거나 데이터를 업데이트할 수 있다.</p><p>Veson은 Connect 솔루션을 AI 기반 이메일 기능까지 확장했다. Connect의 일부로 제공되는 Mail은 해운 관련 이메일과 커뮤니케이션을 자동으로 분류하고 태그를 부여해 정리하며, 중요한 정보를 Veson Platform으로 연결한다.</p><p>Veson Insights는 VesselsValue, Q88, Shipfix 등 다양한 소스의 데이터를 결합하고 데이터 사이언스를 활용해 Veson Platform 내에서 인텔리전스를 제공한다. Vessel Insights는 6만5000척 이상의 선박에 대해 300개 이상의 데이터 필드를 제공하고, Bunker Insights는 수십만 건의 벙커 거래 데이터를 학습한 머신러닝을 기반으로 전 세계 1300개 이상의 항구에서 일별 벙커 가격 예측을 제공한다.</p><p>Veson Nautical의 공동 창립자이자 CEO인 John Veson은 “기술은 사람의 판단을 대체하는 것이 아니라, 더 나은 판단을 내릴 수 있도록 도와야 한다”며 “시스템이 사용자의 업무 맥락을 이해하게 되면 필요한 정보를 미리 파악해 적절한 시점에 제공할 수 있다. 또한 우리는 이를 개방적이고 유연한 플랫폼 기반 위에 구축하고 있기 때문에, 실제 해운 업계의 업무 방식에 자연스럽게 적용될 수 있다”고 말했다.</p><p>Veson Platform은 현재 IMOS 고객을 대상으로 요청 시 제공된다. 회사는 이번 플랫폼이 통합 플랫폼 전략의 시작점이라며, 향후 몇 달에 걸쳐 CoCaptain의 기능을 고도화하고 고급 분석 기능과 새로운 데이터 제품을 순차적으로 선보일 계획이라고 밝혔다. 연말까지 예정된 후속 릴리스는 모두 동일한 플랫폼 기반 위에서 확장될 예정이다.</p><p>Veson은 현재 전 세계 100개국 이상, 2400여 개 기업에서 3만8000명 이상의 사용자를 지원하고 있다.</p>', 'Veson Nautical이 IMOS, CoCaptain, Mail과 신규 Vessel Insights·Bunker Insights를 하나로 통합한 AI 기반 해운 플랫폼 ‘Veson Platform’을 발표했다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/06/3717472907_20260630172545_3443483093.jpg', '2026-06-30T08:37:36.000Z'::timestamptz, array['Veson Nautical', 'Veson Platform', 'IMOS', '해운 AI']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1037671'),
  ('shipping', 'HMM, 에코바디스 ESG 평가 3년 연속 플래티넘 획득', '<p>@@BYLINE@@&nbsp;HMM(대표이사 사장 최원혁)이 프랑스 소재 글로벌 ESG 평가기관 ‘에코바디스(EcoVadis)’의 2026년 평가에서 최고 등급인 ‘플래티넘(Platinum)’ 메달을 3년 연속 획득하고, 미국 모닝스타(Morningstar)사의 ‘서스테이널리틱스(Sustainalytics)’ ESG 리스크 평가에서도 ‘Low Risk’ 등급을 유지했다고 24일 밝혔다.</p><p>에코바디스는 전 세계 10만 개 이상의 기업을 대상으로 △환경 △노동/인권 △윤리 △지속가능한 조달 등 4개 영역의 성과를 평가해 플래티넘(상위 1%), 골드(5%), 실버(15%), 브론즈(35%) 메달을 부여한다.</p><p>HMM은 올해 에코바디스 평가에서 종합점수 91점(100점 만점)을 기록해 전년(87점)보다 점수를 끌어올렸다. 환경분야에서 95점을 받았고, 부패방지경영시스템(ISO 37001) 인증을 취득하면서 윤리분야 점수가 향상되는 등 전 영역에서 상위 1% 이내의 점수를 받았다.</p><p>서스테이널리틱스는 기업별 지배구조, 온실가스, 윤리경영, 안전보건 등 7개 항목을 평가해 기업의 리스크를 5개 등급(Negligible, Low, Medium, High, Severe)으로 구분하며, 점수가 낮을수록 기업의 ESG 리스크가 적음을 의미한다. 글로벌 기관 투자자들의 투자 지표로 활용된다.</p><p>HMM은 올해 서스테이널리틱스 평가에서 12.7점을 기록해 전년(13.6점)보다 개선됐으며, 7개 평가 항목 대부분에서 Negligible/Low Risk 등급을 받았다. 이로써 3년 연속 글로벌 선사 중 1위를 유지했다고 HMM은 밝혔다.</p><p>HMM은 최근 글로벌 ESG 평가가 기업이 자체 제출한 자료뿐 아니라 지속가능경영보고서, 홈페이지 등 대외적으로 검증된 공개 데이터를 기반으로 공정성과 신뢰성을 검증하는 추세라며, 투명한 정보 공개를 바탕으로 전 영역에 걸쳐 고르게 성과를 거뒀다고 설명했다.</p>', 'HMM이 에코바디스 2026년 평가에서 종합점수 91점으로 3년 연속 플래티넘 메달을 받았다. 서스테이널리틱스 ESG 리스크 평가에서도 ‘Low Risk’ 등급을 유지했다.', null, '2026-06-26T01:41:57.000Z'::timestamptz, array['HMM', 'ESG', '에코바디스', '서스테이널리틱스']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1037426'),
  ('shipping', 'HMM, ‘브레이크벌크 유럽 2026’ 참가해 특수화물 수주 확대 나서', '<p>@@BYLINE@@&nbsp;HMM(대표이사 사장 최원혁)이 이달 16일부터 18일까지 네덜란드 로테르담에서 열리는 특수화물 전시회 ‘브레이크벌크 유럽 2026(Breakbulk Europe 2026)’에 참가해 단독 부스를 운영한다고 17일 밝혔다. 이번 전시회에는 전 세계 120여 개국에서 1만2000명 이상의 물류 전문가와 주요 선사, 화주들이 참여한다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/06/31017998_20260617100011_7770102780.jpg" alt="‘브레이크벌크 유럽 2026’에 마련된 HMM 부스에서 업계 주요 관계자들이 HMM의 특수화물 운송에 대해 설명을 듣고 있다"><p><em>▲ ‘브레이크벌크 유럽 2026’에 마련된 HMM 부스에서 업계 주요 관계자들이 HMM의 특수화물 운송에 대해 설명을 듣고 있다</em></p><p>특수화물은 대형 설비, 플랜트 기자재, 풍력 발전 부품 등 일반적인 컨테이너에 적재할 수 없는 크기의 화물을 뜻한다. 천장이나 벽이 없는 특수 컨테이너 등의 전용 장비가 필요하고 화물을 싣고 내릴 때도 별도 크레인을 사용하는 등 높은 수준의 운송 역량이 요구된다. 이 때문에 일반 화물보다 높은 운임을 받을 수 있어 고부가가치 화물로 분류된다.</p><p>HMM은 2007년부터 특수화물 전담 조직을 구축해 운송 노하우를 축적해 왔다. 회사 측은 글로벌 컨테이너 네트워크를 활용한 운송이 가능하고, 건화물선, 다목적선 등 다양한 벌크선을 활용해 초대형/초중량 화물도 처리할 수 있다고 설명했다.</p><p>HMM은 2012년부터 ‘브레이크벌크 유럽’에 참가해 왔다며, 이번 전시회에서 화물 운송 기술력과 화주의 다양한 요청에 대응하는 종합 물류 역량을 소개해 신규 고부가가치 화물 수주를 확대할 방침이라고 밝혔다.</p>', 'HMM이 16~18일 네덜란드 로테르담에서 열리는 특수화물 전시회 ‘브레이크벌크 유럽 2026’에서 단독 부스를 운영하며 특수화물 운송 역량을 소개한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/06/31017998_20260617100011_7770102780.jpg', '2026-06-17T01:21:35.000Z'::timestamptz, array['HMM', '브레이크벌크 유럽', '특수화물']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1036730'),
  ('shipbuilding', '서울대 에너지 이니셔티브 연구단, 23일 SMR 선박 상용화 세미나', '<p>@@BYLINE@@&nbsp;서울대학교 에너지 이니셔티브(SNU Energy Initiative, SNUEI) 연구단이 오는 6월 23일(화) 오후 1시 관악캠퍼스 전력연구소 국제회의실(130동 511호)에서 ‘SMR 선박 상용화를 위한 산업 전략’ 세미나를 개최한다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/06/3542930462_20260616112009_3519700383.jpg" alt="서울대 에너지 이니셔티브 연구단 ‘SMR 선박 상용화를 위한 산업 전략’ 세미나 일정"><p><em>▲ 서울대 에너지 이니셔티브 연구단 ‘SMR 선박 상용화를 위한 산업 전략’ 세미나 일정</em></p><p>이번 세미나는 소형모듈원자로(SMR) 기반 선박의 가능성과 실질적 발전 방향을 모색하고, 국내 SMR 선박 산업이 직면한 주요 과제를 점검하기 위해 마련됐다.</p><p>연구단은 SMR 선박이 연료 보급 없이 장기간 운항할 수 있고 온실가스 배출량을 크게 줄일 수 있다는 점에서 주목받고 있지만, 실제 상용화를 위해서는 기술 개발뿐 아니라 안전성 확보, 제도 정비, 국제 규제 대응 등 다양한 과제의 해결이 필요하다고 설명했다.</p><p>세미나에서는 국내외 SMR 선박 개발 동향과 시장 전망을 살펴보고, 우리나라의 글로벌 산업 경쟁력 확보를 위해 필요한 전략과 정책 과제를 논의할 예정이다. 조선, 해운, 원자력 분야의 산·학·연 전문가들이 SMR 선박의 기술적·산업적 가치와 상용화 전망을 공유하고, 산업계·학계·연구계 간 협력 방안과 글로벌 경쟁 환경 속 대응 전략도 함께 모색한다.</p><p>행사는 전문가들의 주제 발표, 참석 연사 전원이 참여하는 종합 패널 토의 순으로 진행된다.</p>', '서울대 에너지 이니셔티브(SNUEI) 연구단이 6월 23일 ‘SMR 선박 상용화를 위한 산업 전략’ 세미나를 열고 국내외 개발 동향과 산업 전략, 정책 과제를 논의한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/06/3542930462_20260616112009_3519700383.jpg', '2026-06-16T02:39:53.000Z'::timestamptz, array['서울대 에너지 이니셔티브', 'SMR 선박', '세미나']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1036639'),
  ('port', '동원그룹 DGT, 글로벌 6위 선사 ONE과 전략적 파트너십 체결', '<p>@@BYLINE@@&nbsp;동원그룹이 글로벌 6위 해운사인 오션 네트워크 익스프레스(Ocean Network Express, 이하 ONE)와 전략적 파트너십을 체결했다고 24일 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/03/31017998_20260324113718_1801888523.jpg" alt="경남 창원시 진해구 부산신항 동원글로벌터미널부산(DGT)에 접안 중인 ONE 컨테이너선과 터미널 전경"><p><em>▲ 경남 창원시 진해구 부산신항 동원글로벌터미널부산(DGT)에 접안 중인 ONE 컨테이너선과 터미널 전경</em></p><p>동원그룹 자회사 동원글로벌터미널부산(Dongwon Global Terminal Busan, 이하 DGT)은 2024년 부산신항에 개장한 스마트항만 터미널의 운영사다. 이번 파트너십으로 DGT는 안정적인 물동량을 확보하고, ONE은 부산신항을 동북아 핵심 허브로 활용할 수 있게 됐다.</p><p>DGT는 ONE과의 협업을 통해 기존의 2배 이상으로 물동량이 늘어날 것으로 기대하고 있다. 동원그룹은 DGT가 운영 중인 2-5단계 항만 외에 피더 부두와 2-6단계가 완공되면 현재 대비 3배 이상의 추가 물동량 확보도 가능할 것으로 내다봤다.</p><p>DGT는 컨테이너 하역부터 장치장에 옮겨 쌓는 이송, 적치에 이르는 전 과정을 100% 무인 자동화로 운영하고 있다. 인공지능(AI)·사물인터넷(IoT) 기반의 자동화터미널운영시스템(TOS)과 무인이송장비(AGV), 컨테이너크레인(STS) 등을 도입해 유인 항만 대비 생산성을 20% 이상 높였고 정시성과 안전성도 개선했다고 회사 측은 설명했다. 동원그룹은 세계 6위 컨테이너 선사인 ONE을 전략적 파트너사로 유치한 것이 DGT 항만 인프라의 우수성을 입증한 것이라고 밝혔다.</p><p>ONE은 260여 척의 선단으로 200만 TEU 이상의 선복량을 보유한 해운사로, 싱가포르에 본사를 두고 있다. ONE의 부산항 물동량은 지난해 기준 350만 TEU로 두 번째로 많다. 동원그룹은 ONE이 부산신항을 환적 화물의 핵심 거점으로 활용하면 중국으로의 물동량 이탈을 막고 추가 환적 물량을 유치해 항만 경쟁력 강화에 기여할 것으로 전망했다. 앞서 글로벌 1위 해운사 MSC가 2022년 부산신항 1부두 지분을 확보한 이후 처리 물량이 크게 늘면서 항만의 위상이 높아진 바 있다.</p><p>동원그룹은 이번 파트너십이 부산신항의 물동량 확대와 환적 허브로서의 위상 제고에 크게 기여할 것이라며, 국내 최초의 완전 자동화 터미널인 DGT의 사업성 확보와 조기 안정화도 기대된다고 전했다.</p>', '부산신항 자동화 터미널 DGT가 ONE을 전략적 파트너사로 유치해 안정적 물동량을 확보했다. DGT는 기존의 2배 이상 물동량 확대를 기대하고 있다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/03/31017998_20260324113718_1801888523.jpg', '2026-03-24T02:41:30.000Z'::timestamptz, array['동원그룹', 'DGT', 'ONE', '부산신항']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1030916'),
  ('port', 'HMM, 알헤시라스 TTIA 남측 부지 1단계 확장 추진', '<p>@@BYLINE@@&nbsp;HMM(대표이사 사장 최원혁)은 현재 운영하고 있는 스페인 알헤시라스 컨테이너 터미널(TTIA)을 확장 개발한다고 2일 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2025/07/1028147215_20250702084009_4655510270.jpeg" alt="스페인 알헤시라스 터미널(TTIA)에 기항하는 2만4000 TEU급 컨테이너선 ‘HMM 알헤시라스호’"><p><em>▲ 스페인 알헤시라스 터미널(TTIA)에 기항하는 2만4000 TEU급 컨테이너선 ‘HMM 알헤시라스호’</em></p><p>HMM은 TTIA를 통해 지난달 30일 스페인 알헤시라스 항만청에 TTIA 남측 부지 1단계 개발을 추진한다는 투자 의향서를 제출했다. 투자 금액은 1억5000만유로(한화 약 2400억원)이며, HMM은 이 가운데 3500만유로(약 560억원)를 투자할 계획이다. 나머지 금액은 2대 주주인 CMA CGM과 외부 차입을 통해 조달할 예정이다. 투자 금액은 의향서 제출을 위해 산출한 것으로 향후 변동될 수 있다.</p><p>TTIA는 총면적 30만㎡에 연간 처리량 160만 TEU 규모의 현대식 반자동화 터미널이다. HMM은 이번 1단계 확장 개발을 통해 2028년까지 총면적을 46만㎡로, 연간 처리량을 210만 TEU로 늘릴 계획이다. 향후 2단계 개발까지 완료되면 연간 280만 TEU를 처리할 수 있다. 원활한 개발을 위해 터미널 운영 기간은 기존 2043년에서 2065년까지 22년 연장한다.</p><p>HMM은 2017년 TTIA 지분 100%를 인수했으며, 2020년 전략적 제휴를 위해 프랑스 선사 CMA CGM에 지분 50%-1주를 매각했다.</p><p>HMM은 알헤시라스 터미널이 남유럽의 주요 환적 허브이자 스페인의 수출입 관문으로서 터미널 수익 창출은 물론 유럽 노선 경쟁력 강화에 큰 역할을 수행할 것이라며, 앞으로도 해외 터미널을 적극적으로 투자·개발할 계획이라고 밝혔다.</p>', 'HMM이 스페인 알헤시라스 항만청에 TTIA 확장 개발 투자 의향서를 제출했다. 2028년까지 연간 처리량을 210만 TEU로 늘리고 운영 기간을 2065년까지 연장한다.', 'https://file.newswire.co.kr/data/datafile2/data/2025/07/1028147215_20250702084009_4655510270.jpeg', '2025-07-01T23:48:35.000Z'::timestamptz, array['HMM', '알헤시라스', 'TTIA', '터미널 투자']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1014164'),
  ('port', 'HMM, 인도 JNPA와 바드반 항만 개발협력 MOU 체결', '<p>@@BYLINE@@&nbsp;HMM(대표이사 김경배)은 인도 JNPA(자와할랄 네루 항만청, Jawaharlal Nehru Port Authority)와 바드반(Vadhvan) 항만개발협력을 위한 양해각서(MOU)를 체결했다고 23일 밝혔다.</p><p>21일 인도 뭄바이에서 열린 협약식에는 정달중 HMM 인도법인장을 비롯해 사르바난다 소노월(Sarbananda Sonowal) 인도 항만해운수로부 장관, 운메쉬 샤라드 왁(Unmesh Sharad Wagh) JNPA 회장 등 관계자 30여명이 참석했다. 이번 MOU 체결로 HMM은 바드반 항만의 개발과 운영에 적극 협력하기로 했다.</p><p>바드반 항만은 인도의 주요 항인 나바쉐바(Nhava Sheva)항이 포화 상태에 이르면서 새로 개발을 추진하는 대형 사업이다. 인도 정부는 2040년까지 총 94억달러를 투자해 세계 10대 컨테이너항에 진입하는 것을 목표로 하고 있다.</p><p>바드반 항만은 2029년부터 순차적으로 개장하며, 총 9개 컨테이너 터미널에서 연간 약 2300만TEU의 컨테이너를 처리할 수 있다. 자연 수심이 20m로 HMM이 운영하는 2만4000TEU급 초대형 컨테이너선의 기항이 가능하고, 인도 내륙 철도(DFC)와 국가도로에 인접해 내륙 물류와의 연계성도 높은 편이다.</p><p>한편 HMM은 최근 성장률이 높은 인도 시장 공략을 위해 서비스 노선을 확대하고 있다. 올해 2월부터 새로 시작하는 INX(인도-북유럽) 노선을 비롯해 FIM(인도-지중해), IAX(인도-북미동안) 노선 등을 운영하고 있다.</p>', 'HMM이 인도 자와할랄 네루 항만청(JNPA)과 바드반 항만 개발·운영 협력을 위한 양해각서를 맺었다. 바드반 항만은 2029년부터 순차 개장한다.', null, '2025-01-23T00:05:56.000Z'::timestamptz, array['HMM', '인도', '바드반 항만', 'JNPA']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1004834'),
  ('port', 'AD 포츠 그룹, 칼리파항 CMA 터미널 개장…용량 약 1000만TEU', '<p>@@BYLINE@@&nbsp;아랍에미리트 아부다비의 AD 포츠 그룹(AD Ports Group)이 칼리파항 CMA 터미널(CMA Terminals Khalifa Port)의 개장을 발표했다. 이 터미널은 아부다비 왕세자이자 아부다비 집행이사회(Abu Dhabi Executive Council) 의장인 셰이크 칼리드 빈 모하메드 빈 자이드 알 나얀(Sheikh Khaled bin Mohamed bin Zayed Al Nahyan)이 31억 아랍에미리트디르함(AED)(약 8억4500만달러)을 투자해 추진한 컨테이너 터미널이다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2024/12/31017998_20241218100044_7963236106.jpg" alt="HH Sheikh Khaled bin Mohamed bin Zayed Al Nahyan, Crown Prince of Abu Dhabi and Chairman of the Abu Dhabi Executive Council, Rodolphe Saadè, Captain Mohamed Al Shamisi during the inauguration of CMA Terminals Khalifa Port (Photo: AETOSWire)"><p><em>▲ HH Sheikh Khaled bin Mohamed bin Zayed Al Nahyan, Crown Prince of Abu Dhabi and Chairman of the Abu Dhabi Executive Council, Rodolphe Saadè, Captain Mohamed Al Shamisi during the inauguration of CMA Terminals Khalifa Port (Photo: AETOSWire)</em></p><p>칼리파항 CMA 터미널은 CMA CGM 그룹의 자회사인 CMA 터미널스(CMA Terminals)(70%)와 AD 포츠 그룹(30%)의 조인트벤처가 운영한다. 이번 개장으로 CMA CGM의 신규 터미널 프로젝트 1단계가 완공됐으며, 800미터×18.5미터 깊이의 안벽과 8대의 STS 크레인이 가동을 시작하면서 칼리파항에 총 180만 TEU의 용량이 추가됐다. 이에 따라 칼리파항의 연간 컨테이너 용량은 23% 증가한 약 1000만TEU에 이르렀다.</p><p>새 터미널에는 8대의 STS 크레인(Ship to Shore cranes)과 20대의 전기 고무 타이어 갠트리(e-RTG) 크레인, 자동화 게이트와 통합 시스템 등이 갖춰졌다. 선박에 육상 전력을 공급해 배기가스 배출을 제한하고, 터미널 운영의 에너지 믹스에 기여하는 태양광 패널 구역도 여러 곳에 마련했다. 재생 에너지원으로 구동되는 탄소 넷제로 관리동은 2022년 MENA 그린 빌딩 어워드(MENA Green Building Awards)에서 ‘올해의 넷제로 빌딩 프로젝트상’을 받았다. 터미널은 철도 연결을 위한 준비도 마쳤다.</p><p>칼리파항은 2012년 12월 개장해 컨테이너, 로로선 및 다목적 항만 시설을 갖춘 항구로 성장했다. 현재 칼리파항의 면적은 6.3km2이며, 부두 크레인 41대와 야드 크레인 159대를 보유하고 있다. 안벽 길이는 11.7km, 방파제 길이는 3.8km다.</p><p>AD 포츠 그룹 회장인 모하메드 하산 알수와이디(Mohamed Hassan Alsuwaidi)는 “칼리파항 CMA 터미널의 개장은 UAE가 최고의 투자 대상지임을 강조하고 글로벌 플레이어의 핵심 파트너로서 그 입지를 공고히 한다. 새로운 터미널은 무역 흐름을 증가시키고 아부다비와 UAE의 장기적인 경제 성장을 촉진할 것이다”라고 말했다.</p><p>CMA CGM 그룹의 회장 겸 최고경영자인 로돌프 사데(Rodolphe Saadé)는 “새로운 컨테이너 터미널의 개장은 칼리파항 개발의 중요한 단계이며, 글로벌 무역 허브로서 아부다비의 입지를 더욱 공고히 할 것이다. 이 전략적 인프라는 지역 전반의 운송 및 물류 활동을 촉진할 것이다”라고 말했다.</p><p>AD 포츠 그룹 이사 겸 그룹 최고경영자인 캡틴 모하메드 주마 알 샤미시(Mohamed Juma Al Shamisi)는 “칼리파항 CMA 터미널은 아부다비의 연결성을 크게 촉진해 세계의 무역 지도에서 아부다비의 중대한 역할을 강화하고 리더십의 비전에 부합하는 지역 경제 다각화에 기여할 것이다”라고 말했다.</p>', 'AD 포츠 그룹과 CMA 터미널스의 합작 터미널이 문을 열면서 칼리파항에 180만 TEU 용량이 추가됐다. 칼리파항의 연간 컨테이너 용량은 23% 늘어난 약 1000만TEU가 됐다.', 'https://file.newswire.co.kr/data/datafile2/data/2024/12/31017998_20241218100044_7963236106.jpg', '2024-12-18T01:25:00.000Z'::timestamptz, array['AD 포츠 그룹', 'CMA CGM', '칼리파항', '컨테이너 터미널']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1003069'),
  ('port', 'KRISO, STS LNG 벙커링 동시작업 절차서 협회 표준 채택', '<p>@@BYLINE@@&nbsp;선박해양플랜트연구소(소장 홍기용, 이하 KRISO)는 자체 개발한 ‘STS(Ship-to-Ship) 방식의 LNG 벙커링 동시작업 절차서’ 2종이 한국LNG벙커링산업협회 표준으로 최종 채택됐다고 8일 밝혔다. KRISO는 이 절차서를 국내 최초로 개발했다고 설명했다.</p><p>글로벌 주요 항만에서는 선박의 항만 체류 시간을 최소화하기 위해 연료 공급(벙커링)과 화물 하역 등을 동시에 진행하는 ‘동시작업(Simultaneous Operations, SIMOPS)’이 필수적인 운영 체계로 자리 잡고 있다. 동시작업을 하면 별도로 벙커링 시간을 가질 때보다 약 1~3일가량 일정을 단축할 수 있다.</p><p>국내에 입항하는 LNG 추진 선박들은 하역 효율과 신속한 대량 급유를 위해 STS 벙커링 동시작업을 필수 조건으로 요구해 왔지만, 국내에는 이를 뒷받침할 표준 지침이나 기준이 없어 산업 활성화가 더뎠다. 특히 연료 공급선과 수급선이 나란히 접안하는 STS 방식은 안전거리 유지와 계류 하중 관리 등 검토할 사항이 많고, LNG 연료 고유 특성까지 고려한 위험 요소 식별이 전제돼야 해 그간 가이드라인 마련이 쉽지 않았다.</p><p>KRISO 연구진은 컨테이너선과 벌크선을 대상으로 △동시작업 상세 절차 △선종별 동시작업 절차 사례 △단계별 체크리스트 등을 구체화했다. 동시작업 시 발생할 수 있는 위험 요소를 식별하고 안전 확보를 위한 고려 사항을 체계적으로 담았다. 이번 절차서는 향후 정부의 ‘위험물하역 자체안전관리계획서 승인지침’에도 반영될 예정이다. KRISO는 지침에 반영되면 관계기관의 승인 과정에서 명확성과 예측 가능성이 확보돼 현장의 혼선을 방지하고 작업 안전성을 높일 수 있을 것으로 기대했다.</p><p>연구책임자인 KRISO 정동호 책임연구원은 “이번 절차서는 안전 확보는 물론 해운사가 요구하는 STS 벙커링 동시작업을 국내 항만에서 신속하게 이행할 수 있는 기반이 될 것”이라며 “향후 대형 여객선, 자동차운반선에 대한 동시작업 절차서를 추가 개발해 글로벌 선박의 국내 항만 이용을 확대함으로써 LNG 벙커링 산업의 저변을 넓혀가겠다”고 밝혔다.</p><p>KRISO 홍기용 소장은 “이번 성과는 연구개발 결과가 산업계 지원으로 이어지는 실질적인 사례가 될 것”이라며 “친환경 연료추진 선박으로 재편되는 해운 패러다임에 발맞춰 벙커링 안전 기술 등 운영 인프라에 대한 연구개발도 지속해 기술 경쟁력을 종합적으로 확보해 나가겠다”고 강조했다.</p><p>이번 성과는 해양수산부와 해양수산과학기술진흥원(KIMST)의 지원으로 수행 중인 ‘LNG 벙커링 동시작업 기술개발’ 연구사업을 통해 나왔다.</p>', 'KRISO가 개발한 컨테이너선·벌크선 대상 STS 방식 LNG 벙커링 동시작업 절차서 2종이 한국LNG벙커링산업협회 표준으로 채택됐다. 절차서는 정부 승인지침에도 반영될 예정이다.', null, '2026-04-08T02:05:00.000Z'::timestamptz, array['KRISO', 'LNG 벙커링', '동시작업', 'SIMOPS']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1031935'),
  ('port', '이구스, 이동식 쇼어 파워 시스템 ‘imspo’ 공개', '<p>@@BYLINE@@&nbsp;고성능 플라스틱 제조 및 모션 시스템 솔루션 기업 이구스(igus)가 이동식 쇼어 파워 시스템 ‘imspo(igus mobile shore power outlet)’를 발표했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2024/09/2039475088_20240927110159_9798945484.jpg" alt="이구스의 모바일 쇼어 파워 시스템으로 항구 어디에서나 육상 전력을 공급할 수 있다"><p><em>▲ 이구스의 모바일 쇼어 파워 시스템으로 항구 어디에서나 육상 전력을 공급할 수 있다</em></p><p>이구스에 따르면 그동안 항구에 정박한 선박이 쇼어 파워 시스템으로 전력을 공급받으려면 정확한 위치에 정박해야 했다. 이 때문에 선박의 크기와 정박 위치에 따른 제약이 있었고, 정박 위치가 맞지 않으면 추가 비용과 에너지를 들여 재정박해야 했다. 다양한 크기의 선박이 한꺼번에 정박할 때는 이런 문제가 더 컸다고 회사 측은 설명했다.</p><p>imspo는 이동식 전력 공급 시스템으로, 선박의 정박 위치와 상관없이 전력을 이동시켜 공급할 수 있다. 이구스는 이 시스템이 기존의 고정된 전력 공급 방식에서 벗어나 유연하고 효율적인 선박 전력 공급을 가능하게 하며, 항구 운영의 효율성을 높이고 환경에도 긍정적인 영향을 미칠 수 있다고 밝혔다.</p><p>한편 이구스는 10월 16일 개최되는 국제해양플랜트전 ‘OFFSHORE KOREA 2024’에 참가해 DNV GL 인증을 획득한 내해수성 케이블, 높은 충진 중량을 위한 E4.250 에너지 체인 등 해양산업용 솔루션을 선보일 예정이다.</p><p>이구스(igus GmbH)는 독일 쾰른에 본사를 둔 기업으로, 전 세계 36개 지사에서 4150명의 임직원이 일하고 있으며 e체인, 케이블, 베어링 등 모션 플라스틱을 주요 품목으로 생산한다.</p>', '이구스가 선박의 정박 위치와 관계없이 전력을 공급할 수 있는 이동식 쇼어 파워 시스템 ‘imspo’를 발표했다. 10월 ‘OFFSHORE KOREA 2024’에서는 해양산업용 솔루션을 선보인다.', 'https://file.newswire.co.kr/data/datafile2/data/2024/09/2039475088_20240927110159_9798945484.jpg', '2024-09-30T00:00:00.000Z'::timestamptz, array['이구스', '쇼어 파워', 'imspo', '항만 전력']::text[], 'https://www.newswire.co.kr/newsRead.php?no=997600'),
  ('port', '양지, 소파블록 ‘K-CONE’으로 KRC 신기술 인증 획득', '<p>@@BYLINE@@&nbsp;양지(대표 정혜정)는 자사의 ‘파랑유도가 가능한 소파블록(K-CONE)’이 한국농어촌공사가 시행하는 특허 공법 및 신기술 인증 ‘KRC 신기술’의 기타항만 및 해안시설 분야 인증을 획득했다고 21일 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2025/11/2040404273_20251120170933_9399528030.jpg" alt="‘파랑유도가 가능한 소파블록(K-CONE)’ 현장 거푸집 제작"><p><em>▲ ‘파랑유도가 가능한 소파블록(K-CONE)’ 현장 거푸집 제작</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2025/11/2040404273_20251120171011_1579153227.jpg" alt="‘파랑유도가 가능한 소파블록(K-CONE)’ 현장 거치"><p><em>▲ ‘파랑유도가 가능한 소파블록(K-CONE)’ 현장 거치</em></p><p>한국농어촌공사는 KRC 신기술 인증을 통해 중소기업의 우수 기술을 인증하고 수익 창출을 지원하는 한편, 기술의 현장 도입을 추진해 중소기업의 발전을 지원하고 있다.</p><p>양지 정혜정 대표이사는 “‘파랑유도가 가능한 소파블록(K-CONE)’은 한국농어촌공사에서 다양하게 추진하는 사업 중 호안보강공사 또는 지방어항·어촌에 적용 가능한 신기술”이라며 우수한 수리적 특징, 구조적 안정성, 거푸집 2조를 이용한 대량화 생산이 가능한 편리성, 경제성을 장점으로 꼽았다.</p><p>K-CONE은 2025년 7월 3일 중소벤처기업부로부터 시범구매제품확인서를 획득해 관급자재 납품이 가능하다.</p><p>양지는 한국농어촌공사 농업용 저수지뿐 아니라 도서연안 지역의 방파제 및 방호벽 구축, 갯벌 복원 및 생태계 보전으로 적용 범위를 확대하고, 강원도에서 중소기업으로서 입지를 굳혀 나갈 계획이다. 연안 및 해안, 항만 시설 공사를 주 사업으로 하는 양지는 K-CONE으로 해양수산부의 신기술 인증도 받은 바 있다.</p>', '양지의 ‘파랑유도가 가능한 소파블록(K-CONE)’이 한국농어촌공사 KRC 신기술 기타항만 및 해안시설 분야 인증을 받았다.', 'https://file.newswire.co.kr/data/datafile2/data/2025/11/2040404273_20251120170933_9399528030.jpg', '2025-11-21T01:45:00.000Z'::timestamptz, array['양지', 'K-CONE', '소파블록', 'KRC 신기술']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1023593'),
  ('air-cargo', '캐세이 카고, 홍콩 허브 기반 콜드체인 솔루션 강화', '<p>@@BYLINE@@&nbsp;캐세이 카고(Cathay Cargo)가 캐세이 프레시(Cathay Fresh)와 캐세이 파마(Cathay Pharma)를 전문 콜드체인 물류 솔루션으로 통합해 광둥·홍콩·마카오 대만구(GBA)와 글로벌 시장을 연결하는 항공 물류 허브로서의 역할을 강화한다. 캐세이 카고는 비행 5시간 이내에 전 세계 인구의 절반에 도달할 수 있는 홍콩의 지리적 이점을 기반으로 삼는다고 설명했다.</p><p>캐세이 카고는 홍콩공항관리국(Airport Authority Hong Kong)이 추진하는 에어-랜드 프레시 레인(Air-Land Fresh Lane, ALFL) 이니셔티브를 통해 수산물과 제철 과일 등 신선 화물을 GBA로 운송하는 복합 운송 콜드체인 연결망을 구축했다. 화물은 단일 항공화물 운송장으로 처리돼 해외에서 홍콩국제공항(HKIA)을 거쳐 GBA까지 직접 운송되며, 전 과정은 통합 콜드체인 물류 시스템에서 관리된다.</p><p>ALFL은 특수 환적 증명서를 활용해 중국 본토에서 복잡한 재등록 절차를 거치지 않고 주하이의 냉장 세관 시설로 화물을 바로 반입할 수 있도록 수입 절차를 간소화했다. 화물은 계류장에서 냉장 돌리(Cool Dollies)로 보호된 뒤 GPS 추적이 가능한 온도 조절 트럭으로 옮겨진다. 캐세이 카고는 이 같은 운영 방식으로 배송 시간을 단축해 소비자에게 더 신선하고 안전한 식품을 공급할 수 있다고 밝혔다.</p><p>캐세이 카고에 따르면 캐세이 파마는 홍콩국제공항에서 최대 규모의 전용 의약품 처리센터를 운영하며 네 가지 온도 구간(FRO, COL, CRT, ERT)을 지원한다. 6개 전략적 제휴사와 협력해 냉장 컨테이너 옵션도 제공한다. 화주는 실시간에 가까운 데이터 로깅 시스템인 울트라 트랙(Ultra Track)으로 화물 상태를 상세히 확인하고 선제적인 조치를 취할 수 있다. 캐세이 파마는 전 세계 70개 이상의 인증 의약품 처리 스테이션을 기반으로 백신과 바이오 의약품 등의 효능이 운송 전 과정에서 유지되도록 한다.</p><p>캐세이 카고는 신선 식품에는 국제항공운송협회 신선화물 항공 운송 품질인증(IATA CEIV Fresh) 기준을 적용하고, 바이오 제품에는 국제항공운송협회 의약품 항공 운송 품질인증(IATA CEIV Pharma) 요건을 충족하는 의약품 처리 시설을 활용한다고 밝혔다.</p><p>캐세이 카고는 캐세이 그룹(Cathay Group)의 항공화물 사업부로, 전 세계 40개 이상 목적지에 정기 화물기 서비스를 제공하고 캐세이 그룹 여객기의 벨리 카고 용량을 활용해 90개 이상 목적지로 화물을 운송한다. 화물기 기단은 보잉 747-8F 14대와 747-400ERF 6대로 구성돼 있다.</p>', '캐세이 카고가 캐세이 프레시와 캐세이 파마를 전문 콜드체인 물류 솔루션으로 통합해 광둥·홍콩·마카오 대만구(GBA)와 글로벌 시장을 잇는 항공 물류 허브 역할을 강화한다.', null, '2026-05-22T05:40:00.000Z'::timestamptz, array['캐세이 카고', '콜드체인', '홍콩국제공항', '의약품 물류']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1035084'),
  ('air-cargo', 'GTA Aerospace, 화물실 ‘PDU Roller’ 성능시험 완료', '<p>@@BYLINE@@&nbsp;GTA Aerospace(이하 GTA)는 현재 개발 중인 항공기 화물실용 부품 ‘PDU Roller(Power Drive Unit Roller)’의 성능시험을 완료했다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/06/235302127_20260601110513_3266590651.png" alt="GTA Aerospace가 개발 중인 항공기 화물실 ‘PDU Roller’"><p><em>▲ GTA Aerospace가 개발 중인 항공기 화물실 ‘PDU Roller’</em></p><p>PDU Roller는 항공기 화물실 내 화물 컨테이너(ULD)를 이동시키는 구성품으로, 항공 화물의 적재 및 하역 과정에서 이동과 위치 제어를 담당한다. 반복적인 하중과 충격에 노출되는 만큼 높은 내구성과 신뢰성이 요구되며, 항공기 화물 시스템의 운영 효율성과 안전성에 직접적인 영향을 미친다.</p><p>GTA는 이번 시험에서 직접 개발한 PDU Roller의 성능과 내구성을 검증했다. 회사 측에 따르면 시험 결과 개발품은 현재 항공업계에서 사용되고 있는 해외 OEM 부품과 비교해 우수한 성능과 내구성을 확보한 것으로 확인됐다.</p><p>GTA는 현재 국내 항공사에서 사용되는 다수의 화물 시스템 부품이 해외 제조사에 의존하고 있어 조달 비용 증가와 공급망 불안정 등의 문제가 있다며, 이번 개발로 국내 항공산업의 공급망 안정성과 유지보수 경쟁력 향상에 기여할 수 있을 것으로 기대했다.</p><p>GTA는 향후 부품등제작자증명(K-PMA, Korean Parts Manufacturer Approval) 인증을 추진해 국내 상용화를 본격화할 계획이다. K-PMA 인증 획득 이후에는 EASA-POA 인증을 추진해 국내 항공사뿐 아니라 해외 항공사로 공급을 확대할 예정이다.</p><p>GTA는 이번 성능시험 성공이 자사의 기술력과 개발 역량을 입증한 성과라며, 연구개발과 국제 인증 확보를 통해 국내 항공부품 산업의 경쟁력을 높이고 글로벌 시장에서 인정받는 항공부품 전문기업으로 성장해 나가겠다고 밝혔다. GTA는 민수용 항공기 부품 국산화 사업과 텐덤형 무인 수송 헬리콥터 연구개발을 수행하는 항공우주 연구개발 기업으로, 전주 본사에 이어 경남 진주로 사업장을 확장했다.</p>', 'GTA Aerospace가 개발 중인 항공기 화물실용 부품 ‘PDU Roller’의 성능과 내구성을 시험으로 검증했다. 회사는 K-PMA 인증을 추진해 상용화에 나설 계획이다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/06/235302127_20260601110513_3266590651.png', '2026-06-02T00:00:00.000Z'::timestamptz, array['GTA Aerospace', 'PDU Roller', '항공부품 국산화', 'K-PMA']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1035612'),
  ('air-cargo', '대한항공·아시아나항공 합병 승인…12월 17일 통합 출범', '<p>@@BYLINE@@&nbsp;대한항공과 아시아나항공은 13일 각각 정기 이사회를 열고 합병 계약 체결을 승인했다. 양사는 오는 14일 합병 계약을 체결하고 통합 항공사 출범 일자를 공식화할 예정이다. 대한항공은 아시아나항공을 품고 오는 12월 17일 ‘통합 대한항공’으로 출범한다.</p><p>이번 합병 계약 체결은 2020년 11월 17일 대한항공과 아시아나항공의 신주인수계약 체결 이후 5년 6개월여 만이다. 앞서 코로나19 팬데믹으로 글로벌 여객 수요가 급감해 아시아나항공의 재무구조와 경쟁력이 약화되자 정부와 채권단은 항공산업 안정화를 위해 총 3조6000억원 규모의 정책자금을 지원했다. 대한항공은 인수·합병 추진 과정에서 아시아나항공의 재무구조 개선과 경영정상화를 위해 노력했고, 지원받은 공적자금을 전액 상환했다.</p><p>합병 계약에 따라 대한항공은 아시아나항공의 자산, 부채, 권리 의무, 근로자 일체를 승계한다. 합병 비율은 자본시장법령에 의한 기준시가에 따라 대한항공 1 : 아시아나항공 0.2736432로 산정됐다. 이에 따라 대한항공의 자본금은 약 1017억원 증가할 것으로 예상된다.</p><p>대한항공은 14일 합병 계약 체결 직후 국토교통부에 합병 인가를 신청하고, 6월 중 통합에 따라 변경되는 항공 안전 관련 준수 조건 및 제한 사항을 담은 운영기준(OpSpecs) 변경 인가를 신청할 계획이다. 운영기준 변경은 존속하는 대한항공의 기존 운항증명(AOC)을 유지하면서 아시아나항공이 보유한 항공기와 안전 운항 시스템 전반을 대한항공의 운영체계로 통합하기 위한 절차다. 국내 인허가 절차가 완료되면 해외 항공당국을 대상으로도 필요한 절차를 순차적으로 진행한다.</p><p>아시아나항공은 오는 8월경 임시 주주총회를 열고 합병을 결의할 예정이다. 대한항공은 이번 합병이 소규모 합병 요건을 충족해 아시아나항공 주주총회와 같은 날 이사회 결의로 주주총회를 갈음할 계획이다.</p><p>대한항공은 법무부가 최근 발표한 ‘기업 조직개편 시 이사의 행위 규범 가이드라인’에서 권고하는 공정성 강화 조치를 이행했다고 밝혔다. 자사 ESG위원회가 특별위원회 기능을 맡아 합병 거래 조건의 공정성 등을 별도 심의했고, 독립적인 외부 전문가를 통해 합병 가액(비율)의 적정성과 산정 방식의 공정성을 검토했다. 증권신고서에도 공정성 강화 조치 수행 내역과 결과를 상세히 기재할 계획이다.</p><p>대한항공은 통합을 앞두고 중복 노선 재배치, 신규 노선 개발, 공항 라운지 리뉴얼, 기내식 개편, 공항 터미널 이전 등을 진행해왔다. 양사 마일리지 통합안은 공정거래위원회 등 관계당국과 협의 중이며 확정되는 대로 안내할 계획이다. 또 서울 강서구 본사 종합통제센터(OCC)와 객실훈련센터, 항공의료센터를 리모델링하고 양사 운항승무원 훈련 프로그램을 표준화했으며, 엔진 테스트 셀(ETC), 신 엔진 정비 공장, 인천국제공항 인근 정비 격납고 등 정비 시설을 확장하거나 새로 짓고 있다.</p><p>대한항공은 통합 항공사 출범으로 △국가 항공산업 경쟁력 보존 △인천국제공항 허브(Hub) 기능 강화 △글로벌 항공 네트워크 확대 등의 시너지를 낼 수 있을 것으로 기대하고 있다.</p>', '대한항공과 아시아나항공이 13일 이사회에서 합병 계약 체결을 승인했다. 합병 비율은 1대 0.2736432이며, 통합 대한항공은 12월 17일 출범한다.', null, '2026-05-13T08:30:19.000Z'::timestamptz, array['대한항공', '아시아나항공', '합병', '통합 항공사']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1034406'),
  ('air-cargo', 'OAG ‘2025년 가장 붐비는 공항’ 애틀랜타 1위…두바이 2위', '<p>@@BYLINE@@&nbsp;글로벌 여행 산업 데이터 플랫폼 OAG가 항공사 공급 좌석수를 기준으로 한 ‘2025년 세계에서 가장 붐비는 공항’ 순위를 발표했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/01/3717472907_20260117131908_3300074106.png" alt="미국 애틀랜타 하츠필드-잭슨 국제공항(ATL)은 국내선과 국제선을 합쳐 총 6310만 석의 좌석을 제공하며 세계에서 가장 붐비는 공항의 자리를 유지했다(이미지=ATL 웹페이지)"><p><em>▲ 미국 애틀랜타 하츠필드-잭슨 국제공항(ATL)은 국내선과 국제선을 합쳐 총 6310만 석의 좌석을 제공하며 세계에서 가장 붐비는 공항의 자리를 유지했다(이미지=ATL 웹페이지)</em></p><p>애틀랜타 하츠필드-잭슨 국제공항(ATL)은 국내선과 국제선을 합쳐 총 6310만 석을 제공하며 1위 자리를 유지했다. ATL의 수용 능력은 전년 대비 1% 증가했으며, 팬데믹 이전과 대체로 비슷한 수준을 회복했다.</p><p>두바이 국제공항(DXB)은 총 6240만 석으로 2위에 올라 2024년보다 애틀랜타와의 격차를 좁혔다. DXB의 수용 능력은 2024년 대비 4% 증가했으며, 2019년과 비교하면 16% 높은 수준이다. 도쿄 하네다 공항(HND)은 5540만 석으로 3위를 유지했으며, 팬데믹 이전보다 소폭 높은 수준을 이어갔다.</p><p>시카고 오헤어 국제공항(ORD)과 이스탄불 공항(IST)은 톱10 공항 가운데 가장 높은 전년 대비 성장률을 기록했다. 두 공항의 수용 능력은 각각 8%와 6% 증가했다. IST는 2019년 대비 수용 능력이 22% 늘었다.</p><p>OAG는 2025년 상위 10개 공항이 미국과 중국의 대규모 내수 항공시장 강세를 반영하는 한편, 중동 지역의 지속적인 성장과 2019년 이후 새롭게 부상한 허브 공항들의 등장을 함께 보여주고 있다고 밝혔다.</p><p>OAG 수석 애널리스트 존 그랜트(John Grant)는 “2025년 순위는 글로벌 항공 산업이 새로운 성장 국면에 접어들었음을 보여준다. 두바이의 지속적인 확장과 이스탄불의 글로벌 허브로서의 부상은 항공 네트워크가 어떻게 진화하고 있는지를 잘 보여주며, 동시에 대규모 국내 항공시장의 회복력이 여전히 전 세계 항공 수용 능력을 뒷받침하고 있다”고 밝혔다.</p>', 'OAG가 공급 좌석수 기준 2025년 공항 순위를 발표했다. 애틀랜타 국제공항이 6310만 석으로 1위를 지켰고, 두바이 국제공항이 6240만 석으로 격차를 좁혔다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/01/3717472907_20260117131908_3300074106.png', '2026-01-18T01:02:33.000Z'::timestamptz, array['OAG', '공항 순위', '애틀랜타', '두바이']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1027121'),
  ('air-cargo', '대한항공·델타항공, 위탁수하물 원격 검색 시애틀·LA 노선 확대', '<p>@@BYLINE@@&nbsp;대한항공과 델타항공은 ‘위탁수하물 원격 검색(IRBS·International Remote Baggage Screening)’을 서울(인천)발 시애틀 및 로스앤젤레스 노선으로 23일 확대 시행한다.</p><p>IRBS는 출발 공항에서 미국행 수하물 엑스레이(X-ray) 이미지를 미 관세국경보호청(CBP)에 원격으로 전송하고, CBP가 이 이미지를 사전 분석하는 시스템이다. 승객이 항공기로 이동하는 동안 미국 현지에서 미리 짐 검사를 실시해 착륙 후 입국 절차를 간소화하는 방식이다.</p><p>IRBS 실시 항공편을 이용하는 승객은 미국 공항 도착 시 수하물 임의 개봉 검색과 세관 검사를 면제받는다. 미국에서 환승하는 경우에는 미국 내 최초 기착지 공항에서의 수하물 재위탁 절차가 생략되고, 수하물이 최종 목적지 공항까지 자동으로 연결되는 ‘수하물 자동 연결(Seamless Baggage Transfer·SBT)’ 서비스가 적용된다. 이를 통해 환승 시간을 최대 20분까지 절감할 수 있다고 양사는 설명했다.</p><p>시애틀(Seattle-Tacoma International Airport·SEA)에서 환승할 경우 공항 도착, 수하물 수취, 입국 심사, 환승 항공편 수하물 재위탁 과정을 거쳐야 해 긴 시간이 소요되지만, IRBS 실시 항공편을 이용하면 환승객은 공항에서 바로 입국 심사를 받고 환승 항공편에 탑승할 수 있다. 인천국제공항 출발 승객은 물론 인천국제공항을 경유하는 타 국가·지역 출발 승객도 같은 혜택을 받으며, 경유 승객은 최초 출발 공항에서 수하물을 부친 뒤 최종 도착 공항에서 찾으면 된다.</p><p>이번 확대로 양사는 애틀랜타, 디트로이트, 미니애폴리스에 이어 시애틀과 로스앤젤레스까지 미국 주요 5개 거점 공항에서 끊김 없는 여정(Seamless Journey)을 지원할 수 있게 됐다. 양사는 한·미 정부가 협력하는 IRBS 프로젝트에 참여하는 항공사로, 2025년 8월 서울(인천)~애틀랜타 노선에서 해당 서비스를 시작했다. 양사에 따르면 IRBS 도입 이후 미국 공항 도착 후 세관 직원과의 접촉 절차가 65% 이상 줄었고, 기존 수하물 재위탁 절차로 연결편 탑승이 어려웠던 지연 도착 승객들도 상당수 연결편 탑승에 성공한 것으로 나타났다.</p><p>고광호 대한항공 여객사업본부장은 “대한항공은 델타항공과의 조인트벤처 협력을 기반으로 한국과 미국 간 연결성을 확대하고 있다”며 “인천국제공항 허브를 중심으로 고객에게 더욱 편리하고 일관된 프리미엄 여행 경험을 제공하기 위해 지속 노력할 것”이라고 말했다.</p><p>제프 무마우(Jeff Moomaw) 델타항공 아시아태평양 총괄 부사장은 “수하물 자동 연결(SBT) 서비스는 미국행 고객들의 환승 경험을 대폭 간소화 해준다”며 “시애틀과 로스앤젤레스로 서비스를 확대함으로써 고객들이 보다 효율적으로 이동하고 환승 대기 시간도 더욱 여유롭게 활용할 수 있을 것”이라고 설명했다.</p><p>양사는 향후 다른 해외 공항으로 서비스를 확대 적용하는 방안을 검토할 예정이다.</p>', '인천발 시애틀·로스앤젤레스 노선에 IRBS를 적용해 미국 도착 시 세관 검사를 면제하고, 미국 내 환승 시 수하물 재위탁 절차를 생략한다.', null, '2026-06-23T06:56:05.000Z'::timestamptz, array['대한항공', '델타항공', 'IRBS', '수하물']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1037187'),
  ('air-cargo', '대한항공·삼성E&A, SAF 협력 MOU…미국 생산 프로젝트 검토', '<p>@@BYLINE@@&nbsp;대한항공과 삼성E&amp;A는 ‘SAF 협력을 위한 양해각서(MOU)’를 체결했다고 21일 밝혔다. 서명식은 전날 오후 서울 강서구 대한항공 본사에서 우기홍 대한항공 부회장, 남궁홍 삼성E&amp;A 대표이사 사장 등 양사 주요 관계자들이 참석한 가운데 열렸다.</p><p>이번 MOU는 △해외 지속가능항공유(Sustainable Aviation Fuel·SAF) 생산 프로젝트 발굴 및 검토 △SAF 장기 구매(Offtake) 참여 검토 및 상호 지원 △SAF 관련 신기술·프로젝트 투자 검토 △대한항공의 삼성E&amp;A ‘SAF 기술 동맹(Technology Alliance)’ 파트너 참여 등을 골자로 한다. 양사는 보유한 전문성과 네트워크를 활용해 SAF 생산·공급망을 구축하고 관련 사업 기회를 발굴하는 데 협력하기로 했다.</p><p>양사는 첫 번째 협력 대상지로 미국 시장을 주목하고 현지 프로젝트 참여 방안을 검토할 예정이다. 대한항공은 미국이 SAF 생산에 필요한 원료가 풍부하고 기술과 인프라를 갖추고 있어 SAF 생산 시장에서 주목받는 국가라고 설명했다. 협력 구조는 삼성E&amp;A가 플랜트 구축 기술력을 제공하고 대한항공이 SAF 수요처 역할을 맡는 방식이다.</p><p>삼성E&amp;A는 EPC(설계·조달·시공) 분야 전문성을 바탕으로 미국 현지에서 추진되는 2세대 SAF 생산 플랜트 건설 프로젝트 참여를 검토 중이다. 목질계 폐기물을 고온에서 가스화한 뒤 다시 액체연료로 전환하는 ‘가스화-피셔 트롭시(FT·Fischer Tropsch)’ 기반 2세대 SAF 생산 기술을 적용할 계획이다. 이 기술은 폐식용유 등 제한된 원료만 사용 가능했던 1세대 SAF와 달리 폐목재와 같은 비식용 및 폐기성 바이오매스까지 원료 범위를 확장할 수 있다.</p><p>대한항공은 이곳에서 생산된 SAF를 구매하는 오프테이커(Offtaker)로 참여하는 방안을 검토 중이다. 오프테이커는 일정 기간 동안의 생산량을 고정적으로 사들여 신규 에너지 사업 기반을 안정화하는 역할을 한다. 해외에서는 델타항공, 에어프랑스, 유나이티드항공, 아메리칸항공, 사우스웨스트항공 등이 이 같은 방식으로 SAF 생산과 공급망 구축에 참여하고 있다.</p><p>대한항공은 이번 협력으로 글로벌 항공업계의 ‘탄소중립(넷 제로·Net Zero) 2050’ 목표 달성에 기여하고 SAF 사용 의무화 등 국제적 환경 규제에 대응할 수 있을 것이라며, 프로젝트 참여와 지속적인 협력으로 지속 가능한 비행과 ESG 경영을 실천해 나가겠다고 밝혔다.</p><p>한편 대한항공은 2017년 우리나라 국적 항공사 최초로 시카고-인천 노선을 SAF 혼합 항공유로 운항했다고 밝혔다. 2024년에는 인천국제공항에서 출발하는 일부 상용 운항 노선에 국산 SAF를 처음 혼합한 데 이어 김포국제공항으로 사용편을 확대했다.</p>', '해외 SAF 생산 프로젝트 발굴과 장기 구매 참여 등을 검토하며, 삼성E&A는 플랜트 건설을, 대한항공은 구매처 역할을 맡는다.', null, '2025-11-20T23:46:47.000Z'::timestamptz, array['대한항공', '삼성E&A', 'SAF', 'MOU']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1023608'),
  ('air-cargo', '대한항공, 인천국제공항공사와 1760억원 투입 정비격납고 신설 협약', '<p>@@BYLINE@@&nbsp;대한항공이 인천국제공항공사와 1760억원을 투입해 인천국제공항 첨단복합항공단지에 신규 정비격납고 신설을 추진한다.</p><p>대한항공은 24일 그랜드 하얏트 인천에서 인천국제공항공사와 ‘첨단복합항공단지 정비시설(H3) 개발사업 실시 협약’을 체결했다. 협약식에는 우기홍 대한항공 부회장과 이학재 인천국제공항공사 사장을 비롯한 정부·지자체·국회의원 및 관계자 90여 명이 참석했다.</p><p>이번 협약은 통합 대형 항공사(FSC)와 저비용 항공사(LCC) 출범 이후 300여 대 항공기의 안전을 책임지고 효율적인 정비 지원이 가능한 정비 시설을 구축하고자 마련됐다.</p><p>신규 정비격납고는 인천국제공항 첨단복합항공단지 내 6만9299㎡(약 2만1000평) 부지에 중대형 항공기 두 대와 소형 항공기 한 대를 동시에 주기 및 정비할 수 있는 시설로 건설된다. 2027년 착공해 2029년 말 가동을 목표로 한다. 격납고가 완공되면 대한항공의 숙련된 정비 인력을 포함해 300여 명이 상주하는 중정비 및 개조 중심 시설이 될 계획이다.</p><p>우기홍 부회장은 축사에서 “정비 격납고는 단순한 건물이 아닌 안전의 요람이며, 대한항공의 최우선 가치인 ‘절대적인 안전’을 지키기 위한 필수적인 기반시설”이라면서 “새로운 격납고가 가장 쾌적하고 안전한 정비 기지, 항공 안전의 산실로 자리매김할 수 있도록 설계 단계부터 세심하게 챙겨 나가겠다”고 말했다.</p><p>대한항공은 이를 통해 통합 항공사 출범 이후에도 정비 전문성과 사업성을 이어가고, 국가 항공 유지·보수·정비(MRO) 산업의 경쟁력을 높이는 ‘글로벌 MRO 허브’ 역할을 수행한다는 계획이다.</p>', '첨단복합항공단지 6만9299㎡ 부지에 2027년 착공해 2029년 말 가동을 목표로 하는 중정비·개조 중심 격납고를 짓는다.', null, '2025-11-24T05:58:12.000Z'::timestamptz, array['대한항공', '인천국제공항공사', '정비격납고', 'MRO']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1023781'),
  ('air-cargo', '대한항공, 에어버스 A320 날개 부품 샤크렛 누적 5000대 납품', '<p>@@BYLINE@@&nbsp;대한항공은 에어버스 A320 시리즈 항공기의 날개 부품인 ‘샤크렛(Sharklet)’ 납품량이 누적 5000대를 기록했다고 24일 밝혔다.</p><p>대한항공은 23일 오후 부산 강서구 대한항공 테크센터에서 ‘A320 샤크렛 5000호기 납품 기념식’을 열었다. 이날 행사에는 유종석 대한항공 안전보건 총괄 겸 오퍼레이션 부문 부사장과 브누아 슐츠(Benoit Schultz) 에어버스 최고 조달 책임자(CPO), 임진규 대한항공 항공우주사업본부장 등이 참석했다.</p><p>참석자들은 행사에 앞서 대한항공이 개발·제작한 항공기 구조물과 정비·제작 시설을 둘러봤다. 본 행사에서 대한항공은 에어버스를 비롯한 국내외 협력업체 15곳에 샤크렛 형태의 오브제를 전달했으며, 대한항공 및 협력업체 직원들을 대상으로 한 표창 수여식도 진행했다.</p><p>유종석 부사장은 축사에서 “오늘의 5000호기는 단순한 생산 실적을 넘어 대한항공이 글로벌 항공우주 산업의 핵심 파트너로서 역량을 입증한 자랑스러운 상징”이라며 “대한항공은 앞으로도 타협하지 않는 최고의 품질과 신뢰를 바탕으로 글로벌 항공우주 산업의 더 큰 미래를 열어가겠다”고 말했다.</p><p>샤크렛은 A320 항공기 날개 끝에 부착하는 ‘L’자형 구조물로, 와류(Vortex)를 방지해 공기 역학 성능을 향상시키는 윙 팁(Wing Tip)의 일종이다. 운항 시 공기 저항을 낮춰 연료 효율을 높이고 이산화탄소 배출을 줄이는 역할을 한다.</p><p>대한항공은 2010년 에어버스 A320 시리즈 성능 개선 사업 국제입찰에서 일본, 프랑스, 독일 기업을 제치고 샤크렛 제작사로 최종 선정됐다. 2012년 7월 첫 호기 생산을 마친 뒤 월간 50대 이상 생산 능력을 갖춘 오토 무빙 라인(Auto Moving Line) 시설을 마련해 누적 5000대 납품 실적에 이르렀다.</p>', '23일 부산 테크센터에서 5000호기 납품 기념식을 열었으며, 2012년 7월 첫 호기 생산 이후 누적 실적이다.', null, '2026-04-23T23:56:04.000Z'::timestamptz, array['대한항공', '에어버스', '샤크렛', '항공우주']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1033042'),
  ('trade', '에이셉익스프레스, 수출입 요건 확인 AI 서비스 ‘ASAP C’ 오픈', '<p>@@BYLINE@@&nbsp;글로벌 특수물류 및 무역 RegTech 기업 에이셉익스프레스(대표 안용진)가 제품과 국가 정보를 입력하면 수출입 요건 및 필수 서류를 확인할 수 있는 AI 기반 서비스 ‘ASAP C(Compliance AI)’를 오픈했다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/04/2049847438_20260407141640_3137155473.png" alt="ASAP C 서비스"><p><em>▲ ASAP C 서비스</em></p><p>ASAP C는 에이셉익스프레스가 글로벌 특수물류 솔루션 ‘ASAP’을 운영하며 축적한 현장 경험과 무역 실무 노하우를 바탕으로 개발됐다. 회사는 특수 산업 분야 품목을 다루면서 국가별 규제, 통관 절차, 인증 검토 등 수출입 과정에서 반복적으로 발생하는 문제를 기술적으로 구조화해 왔으며, 이를 서비스 형태로 구현했다고 설명했다.</p><p>ASAP C는 단건 품목 기준으로 사용할 수 있도록 설계됐다. 사용자가 제품 정보와 대상 국가를 입력하면 해당 품목의 수출입 과정에서 검토해야 할 주요 요건과 준비해야 할 서류를 확인할 수 있다. 회사는 국가별 규제와 품목별 요구사항을 일일이 확인해야 하는 과정을 정리해 실무자의 초기 검토 부담을 줄이는 데 초점을 맞췄다고 밝혔다.</p><p>에이셉익스프레스는 우선 주요 5개국 내 일부 산업군을 중심으로 서비스를 적용한 뒤 국가 및 품목 범위를 점진적으로 확대해 나갈 계획이다. 회사는 이를 통해 중소기업과 초기 수출기업도 무역 컴플라이언스 정보를 확인하고 실무 판단에 활용할 수 있을 것으로 기대하고 있다. 또 ASAP C를 사용하는 고객이 필요시 실제 물류 수행까지 이어갈 수 있도록 지원할 계획이라고 설명했다.</p><p>안용진 대표는 “무역 컴플라이언스는 정보의 양도 많고 국가별 편차도 커서, 실무자 입장에서는 어디서부터 확인해야 할지 막막한 경우가 많다”며 “ASAP C는 제품과 국가 정보만으로 필요한 요건을 빠르게 확인할 수 있도록 설계한 서비스로, 무역 실무의 진입 장벽을 낮추는 데 의미가 있다”고 말했다. 이어 “에이셉익스프레스는 ASAP C를 시작으로 물류와 무역 현장에서 발생하는 다양한 문제를 기술로 해결하며 서비스 고도화를 지속해 나갈 계획”이라고 덧붙였다.</p><p>에이셉익스프레스는 2022년 창업 이후 고속버스·KTX·항공 인프라를 기반으로 국내 긴급 전국 당일배송 서비스 ‘고쏙(GOSSOK)’과 글로벌 특수물류 서비스 ‘에이셉(ASAP)’을 운영해 왔다.</p>', '제품 정보와 대상 국가를 입력하면 수출입 과정에서 검토할 주요 요건과 필요 서류를 안내하며, 주요 5개국 일부 산업군부터 적용한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/04/2049847438_20260407141640_3137155473.png', '2026-04-07T06:40:00.000Z'::timestamptz, array['에이셉익스프레스', 'ASAP C', '무역 컴플라이언스', 'AI']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1031876'),
  ('trade', '코트라·무보·하나은행, 해외지사화사업 참여기업 수출금융 지원 협약', '<p>@@BYLINE@@&nbsp;대한무역투자진흥공사(코트라, 사장 강경성)는 한국무역보험공사(무보, 사장 장영진), 하나은행(은행장 이호성)과 5월 11일 코트라 본사에서 국내 기업의 해외시장 진출 지원 협력체계 구축을 위한 업무협약(MOU)을 체결했다.</p><p>3개 기관은 코트라 해외지사화사업 참여기업들을 대상으로 수출 단체보험과 수출 신용보증 등 ‘수출 지원 패키지 금융’을 제공할 계획이다. 해외지사화사업은 코트라 해외 무역관이 현지에 지사 설립 여력이 부족한 중소·중견기업을 대신해 해외시장 진출 및 수출을 맞춤형으로 지원하는 사업이다.</p><p>협약에 따라 무보와 하나은행은 해외지사화사업 참가 기업을 대상으로 △단기수출보험(단체보험) △신용보증 및 유동성 공급을 위한 대출 금융을 지원한다. 3개 기관은 수출대금 미회수 리스크와 유동자금 확보에 어려움을 겪는 수출 기업에 실질적인 지원이 될 것으로 기대했다.</p><p>무보는 기존 신용보증 한도를 최대 2배까지 우대하고, 하나은행은 참가 기업이 하나은행과 수출입 거래를 할 경우 수출 보험료 및 신용 보증료(1년간 최대 5000만원)를 100% 지원한다. 단기수출보험은 단체보험 방식을 채택해 개별 가입보다 절차가 간소하다.</p><p>코트라는 향후 해외지사화사업 참가 기업을 대상으로 ‘수출 패키지’ 금융 지원 수요 조사를 실시하고, 무보·하나은행과의 협의를 거쳐 지원 기업을 최종 선정할 계획이다.</p><p>강상엽 코트라 부사장 겸 중소중견기업본부장은 “글로벌 통상 환경이 급변하는 가운데 민관이 협업해 기업에 실질적인 도움을 제공할 수 있게 돼 뜻깊다”라며 “앞으로도 우리 기업들이 해외 확대에보다 안정적으로 도전할 수 있도록 유관 기관과의 협력체계를 강화하겠다”라고 말했다.</p>', '3개 기관이 5월 11일 업무협약을 맺고 해외지사화사업 참가 기업에 단기수출보험(단체보험)과 신용보증·대출 금융을 묶어 지원한다.', null, '2026-05-11T23:00:00.000Z'::timestamptz, array['코트라', '무역보험공사', '하나은행', '수출금융']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1034185'),
  ('trade', '포스코인터내셔널·LG CNS, 블록체인·AI 무역금융 기술 검증 완료', '<p>@@BYLINE@@&nbsp;포스코인터내셔널(대표이사 사장 이계인)이 23일 LG CNS와 함께 실제 글로벌 거래 환경에 블록체인·AI 기술을 적용하는 무역금융 인프라 기술 검증(PoC)을 완료했다.</p><p>포스코인터내셔널은 글로벌 사업 확대에 따라 증가하는 해외법인과의 거래·정산 업무를 효율적으로 관리하고 무역 현장의 디지털 전환을 가속화하기 위해 이번 PoC를 추진했다. △공동원장 기반 거래 상태 공유 △매출채권 실물연계자산(RWA) 토큰화 △AI Agent 기반 무역 업무 자동화 등 3개 영역에서 디지털 기술을 실증했다. 포스코인터내셔널은 글로벌 무역 네트워크와 실거래 데이터를 기반으로 실증 환경을 제공했으며, LG CNS는 시스템 구조 설계와 블록체인·AI 기술 검증을 담당했다.</p><p>먼저 본사와 해외법인, 거래 파트너 간 거래 정보를 블록체인 공동원장(Shared Ledger) 기반으로 실시간 공유하는 방식을 구현했다. 기존에는 국가·법인별로 거래 정보가 각각 관리돼 계약·정산 과정에서 반복적인 확인 작업이 필요했다. 공동원장 기반 구조에서는 거래 참여자가 동일한 거래 상태를 실시간으로 확인할 수 있어 정보 불일치로 인한 운영 리스크를 줄이고 계약·정산 업무의 효율성을 높일 수 있다.</p><p>매출채권 실물연계자산(RWA) 토큰화 영역에서는 실제 무역 거래에서 발생하는 매출채권을 디지털 자산 형태로 발행하고 이전·정산·거래·관리할 수 있는 구조를 검증했다. 검증에는 기업 금융 환경에 특화된 블록체인 네트워크인 인젝티브(Injective)가 활용됐다. 인젝티브 네트워크의 구조를 바탕으로 권한 기반 자산 관리와 고객확인(KYC)·자금세탁방지(AML), 투자자 적격성 심사, 자산 전송 제한 등 기업 금융에 필요한 통제 기능의 적용 가능성도 확인했다.</p><p>또 문서를 자동으로 읽고 오류를 검토하는 AI Agent를 신용장(LC)과 무역서류 검토 과정에 적용해, 담당자 숙련도 차이로 발생할 수 있는 검토 품질 편차와 휴먼에러를 줄일 수 있는지 실증했다. 글로벌 무역 업무는 국가·거래처·계약 조건별로 요구 서류와 절차가 달라 높은 숙련도를 요구하며, LC 오타나 조항 누락 같은 단순 오류도 대금 지급 지연이나 거절로 이어질 수 있다.</p><p>포스코인터내셔널은 AI Agent를 사전 검토 단계에 활용하면 관련 리스크를 조기에 식별하고 해외 법인 간 업무 품질 차이를 줄일 수 있다는 점을 확인했다.</p>', '공동원장 기반 거래 상태 공유, 매출채권 실물연계자산(RWA) 토큰화, AI Agent 기반 무역 업무 자동화 등 3개 영역을 실증했다.', null, '2026-07-27T01:20:57.000Z'::timestamptz, array['포스코인터내셔널', 'LG CNS', '블록체인', '무역금융']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039338'),
  ('trade', '프로스트 앤드 설리번, 지정학 갈등·무역 분절화 대응 공급망 전략 제시', '<p>@@BYLINE@@&nbsp;글로벌 시장조사 및 컨설팅 기업 프로스트 앤드 설리번(Frost &amp; Sullivan)은 지정학적 갈등과 무역 분절화가 심화되는 가운데 기업들이 공급망 리스크에 대응하고 성장을 이어가기 위해 고려해야 할 핵심 공급망 전략을 제시했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/07/31672899_20260728131851_1352780053.jpg" alt="프로스트 앤드 설리번이 공급망 리스크 관리 전략을 제시했다"><p><em>▲ 프로스트 앤드 설리번이 공급망 리스크 관리 전략을 제시했다</em></p><p>프로스트 앤드 설리번에 따르면 최근 중동 지역의 분쟁과 주요 해상 무역로의 혼란으로 일부 주요 항로의 운임은 기존 대비 2~5배까지 상승했으며, 전쟁 위험 보험료도 선박 가치의 0.15% 수준에서 최대 10%까지 높아졌다. 여기에 관세 정책과 보호무역 기조 확산, 국가 간 무역 규제 강화 등으로 공급망 재편이 가속화되면서 반도체, 자동차 및 전기차(EV), 제약 및 의료기기 등 주요 산업 전반에서 공급망 전략 재검토가 이뤄지고 있다.</p><p>프로스트 앤드 설리번은 기업들이 공급망 구조와 조달 전략, 물류 운영 방식을 재평가하는 한편 공급처 다변화와 지역별 생산 네트워크 구축을 추진하고 있다고 설명했다. 리쇼어링(Reshoring)과 프렌드쇼어링(Friendshoring)을 통한 생산 거점 확보, 예측 기반 디지털 기술과 통합 공급망 시스템을 활용한 공급망 가시성 강화도 중요한 전략으로 부상하고 있다고 분석했다.</p><p>공급망 재편 과정의 성장 기회로는 세 가지를 꼽았다. 인도, 베트남, 멕시코가 새로운 제조 허브로 부상하는 ‘제조 지역 확장’, AI 기반 공급망 솔루션이 재고 관리와 리스크 평가, 사업 연속성 관리 역량을 강화하는 ‘공급망 기술 도입’, 현지 통화 결제 체계가 제재 관련 리스크와 국경 간 금융 변동성에 대한 노출을 줄이는 ‘지역 통화 기반 무역 시스템’이다.</p><p>대응 전략으로는 △무역 협정과 규제 변화에 맞춘 조달 전략 최적화 △생산 거점을 여러 지역으로 분산하는 분산형 생산 네트워크 구축 △공급업체 생태계 및 지역 파트너십 강화 △예측 기반 기술과 디지털 통합 시스템을 활용한 디지털 기반 공급망 가시성 확보 등 4가지를 제시했다.</p><p>프로스트 앤드 설리번은 글로벌 공급망이 더 이상 비용 효율성만을 중심으로 운영되는 구조가 아니며, 비용 구조 변화와 무역 흐름 재편, 지정학적 리스크가 기업 운영 전반에 영향을 미치는 시대에 진입했다고 분석했다. 또 조달, 생산, 무역 전략을 이러한 구조적 변화에 맞춰 선제적으로 재정비하는 기업이 공급 안정성과 장기적인 경쟁력을 확보할 것으로 전망했다.</p><p>관련 내용은 프로스트 앤드 설리번의 보고서 ‘Global Supply Chain Transformations Emerging from Geopolitical Flashpoints and Trade Shifts, 2025-2027’에 담겼다.</p>', '일부 항로 운임이 2~5배 오르고 전쟁 위험 보험료가 최대 10%까지 높아진 가운데, 공급처 다변화와 디지털 기반 가시성 확보 등을 제시했다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/07/31672899_20260728131851_1352780053.jpg', '2026-07-29T00:00:00.000Z'::timestamptz, array['프로스트 앤드 설리번', '공급망', '지정학 리스크']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1039459'),
  ('trade', 'GS글로벌, 완도물산·하이랜드푸드와 김 수출 협력 3사 MOU', '<p>@@BYLINE@@&nbsp;GS글로벌(대표 김성원)은 8월 12일 서울 역삼동 GS타워 본사에서 김 전문 생산 기업 완도물산영어조합법인(완도물산), 육류 수입·유통 기업 하이랜드푸드그룹(하이랜드푸드)과 김 제품의 국내외 판매 확대 및 수출 협력을 위한 3사 간 업무협약(MOU)을 체결했다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/31017998_20260813115152_2850039443.jpg" alt="왼쪽부터 하이랜드 윤영미 회장, 완도물산 김천일, 최인녕 공동대표, GS글로벌 김성원 사장"><p><em>▲ 왼쪽부터 하이랜드 윤영미 회장, 완도물산 김천일, 최인녕 공동대표, GS글로벌 김성원 사장</em></p><p>이번 협약은 각 사의 핵심 역량을 결합해 김 제품의 생산, 국내외 유통, 브랜드 경쟁력 강화 등 전 과정에서 협력하고자 추진됐다. 완도물산은 김 원재료 소싱과 완제품 생산을 담당하고, GS글로벌과 하이랜드푸드는 국내외 유통 네트워크와 마케팅 역량을 활용한 신규 고객 발굴, 판매 채널 및 해외 수출 확대를 공동 추진한다.</p><p>1996년 설립된 완도물산은 2024년 기준 매출 약 460억 원, 수출액 약 173억 원을 기록한 김 전문 기업이다. 해양수산부 지정 ‘마른 김 명인’인 김천일 대표가 원초 수매부터 조미 가공까지 원스톱 생산체계를 관리한다. 가공공장 전체에 대한 FSSC22000 인증과 미국 FDA·USDA(유기농) 인증을 획득했으며, 대표 브랜드 ‘새우표 완도김’을 중심으로 중국, 일본, 미국 등에 수출하고 있다.</p><p>하이랜드푸드는 국내 수입육 시장 점유율 약 13%를 차지하는 육류 수입·유통 전문 기업으로, 1700여 개 고객사에 달하는 유통망과 물류·가공 인프라를 보유하고 있다. 최근 K-푸드 수요 확대에 맞춰 신규 사업으로 김 제품을 검토해 왔으며, 이번 협약을 통해 사업 확대를 추진한다.</p><p>GS글로벌은 2024년 닭고기 가공업체 전략적 지분 투자를 시작으로 식품 사업을 본격화했으며, 올해 식품사업팀을 신설해 김 제품 수출 및 신규 품목(녹차 등) 발굴을 추진 중이다. 현재 GS 구내식당에 완도물산 김을 시범 공급하고 있으며, 향후 자사의 글로벌 네트워크를 활용해 해외 판매 채널을 확장할 계획이다.</p><p>GS글로벌은 종합상사의 글로벌 네트워크와 공급망 관리 역량을 기반으로 식품 밸류체인을 연결하는 ‘Food Solution’ 사업을 신성장 동력으로 육성하고 있다며, 다양한 K-푸드를 글로벌 시장에 연결하는 종합 식품 플랫폼으로 도약하겠다고 밝혔다.</p>', '완도물산이 원재료 소싱과 생산을 맡고, GS글로벌과 하이랜드푸드가 국내외 유통과 해외 수출 확대를 공동 추진한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/08/31017998_20260813115152_2850039443.jpg', '2026-08-13T02:58:15.000Z'::timestamptz, array['GS글로벌', '완도물산', '하이랜드푸드', '김 수출']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1040498'),
  ('trade', '핑크패커, TIPS 선정…육류 무역 운영체제 ‘TradeOS’ 개발', '<p>@@BYLINE@@&nbsp;글로벌 축산물 무역 테크 스타트업 핑크패커(대표 정진)는 중소벤처기업부 주관 TIPS 일반트랙에 선정돼 향후 2년간 육류 무역 전용 운영체제 ‘TradeOS’ 개발을 진행한다고 밝혔다. 운영사는 국민대학교기술지주다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/05/3552807959_20260506145712_7346570575.png" alt="핑크패커가 중기부 TIPS에 선정됐다"><p><em>▲ 핑크패커가 중기부 TIPS에 선정됐다</em></p><p>핑크패커는 글로벌 육류 무역에서 무역 서류가 팩스와 PDF로 오가고, 국가마다 부위 이름과 규격이 달라 매칭에 시간이 걸린다고 설명했다. 콜드체인 운송 중 온도가 이탈해도 도착 전까지 알 수 없고, 분쟁이 생기면 대금 지급이 한 달 넘게 미뤄진다는 것이다. 핑크패커는 FAO 기준 전 세계에서 생산되는 육류의 20%가 이 같은 구조적 비효율 속에서 손실된다고 밝혔다.</p><p>TradeOS는 국가별 부위 표준 매핑, 무역 서류 자동 검증, IoT 기반 실시간 품질 추적을 API 하나로 묶는 운영체제다. 핑크패커는 Stripe가 결제 인프라를 표준화한 것처럼 육류 무역의 거래 리스크를 단일 레이어로 통합한다는 구상이다.</p><p>핑크패커는 지난해 UN 식량농업기구(FAO)가 주최한 글로벌 컨퍼런스에서 Top 10 스타트업으로 소개됐으며, 올해 1월에는 케냐 나이로비에서 도축장부터 주요 호텔 납품 경로까지 자체 IoT 센서 PinkTag로 현장 실증을 진행했다. 인프라 환경이 열악한 곳에서도 안정적으로 작동하는지를 먼저 검증한다는 취지다.</p><p>정진 대표는 “글로벌 육류 무역에서 풀리지 않은 것은 기술 문제가 아니라 거래 당사자들이 서로를 신뢰할 근거가 없어서 발생하는 구조적 낭비”라며 “TradeOS는 그 신뢰의 기반을 데이터로 만든다”고 말했다.</p><p>핑크패커는 현재 호주 시드니에 현지 법인을 운영 중이며, 베트남을 첫 실거래 시장으로 확장하고 있다. 다국가 운영 체계를 총괄하는 정백라 글로벌 통합 디렉터(Director, Global Integration)는 “여러 나라에 법인을 세우는 것보다 어려운 것은 그 법인들이 하나의 회사처럼 움직이게 하는 것”이라며 “글로벌 프로세스와 문화를 표준화해 어느 거점에서든 동일한 기준으로 일이 진행되게 만드는 것이 핑크패커가 글로벌에서 살아남는 방식”이라고 말했다.</p>', '향후 2년간 국가별 부위 표준 매핑과 무역 서류 자동 검증, IoT 기반 실시간 품질 추적을 하나로 묶는 운영체제를 개발한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/05/3552807959_20260506145712_7346570575.png', '2026-05-06T22:00:00.000Z'::timestamptz, array['핑크패커', 'TIPS', 'TradeOS', '육류 무역']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1033832'),
  ('trade', '사우디아라비아, 11월 리야드서 제2회 글로벌 물류 포럼 개최', '<p>@@BYLINE@@&nbsp;사우디아라비아 교통물류서비스부가 주최하는 제2회 ‘글로벌 물류 포럼(Global Logistics Forum)’이 오는 11월 29일부터 12월 1일까지 리야드 킹 압둘아지즈 국제컨퍼런스센터에서 개최된다. 포럼은 ‘두 성지의 수호자’ 살만 빈 압둘아지즈 알사우드 국왕이 후원한다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/3717472907_20260819021347_6715176510.jpg" alt="사우디아라비아 교통물류서비스부의 주최로 열리는 ‘글로벌 물류 포럼 2026(Global Logistics Forum 2026)’ 참가자들은 향후 10년간 물류 산업의 판도를 좌우할 무역 흐름과 기술, 금융 및 투자 관련 주요 의사결정을 집중적으로 논의할 예정이다"><p><em>▲ 사우디아라비아 교통물류서비스부의 주최로 열리는 ‘글로벌 물류 포럼 2026(Global Logistics Forum 2026)’ 참가자들은 향후 10년간 물류 산업의 판도를 좌우할 무역 흐름과 기술, 금융 및 투자 관련 주요 의사결정을 집중적으로 논의할 예정이다</em></p><p>이번 포럼은 같은 주 같은 장소에서 열리는 ‘2026 유엔무역개발회의(UN Trade and Development, UNCTAD) 글로벌 공급망 포럼(Global Supply Chain Forum 2026)’과 연계해 진행된다. 주최 측은 두 포럼에 전 세계 정책 입안자와 업계 경영진, 투자자들이 모일 예정이라고 밝혔다.</p><p>2024년 열린 제1회 포럼에는 30여 개국에서 1만3000명 이상이 참석했으며, 연사 140명과 전시업체 80곳이 참여했다. 제1회 포럼에서는 총 160억사우디리얄(SAR, 약 43억달러) 이상의 가치를 지닌 67건의 협력 계약 및 양해각서(MOU)가 체결됐다. 주최 측은 2026년 행사에서 이를 토대로 더 확대된 성과를 내는 것을 목표로 한다고 밝혔다.</p><p>이번 포럼은 사우디아라비아 정부의 ‘비전 2030(Vision 2030)’ 목표에 맞춰 대륙을 연결하는 글로벌 물류 허브로서 사우디아라비아의 위상을 강화하는 데 초점을 맞춘다. 주요 의제로는 물류 서비스 혁신, 통합된 글로벌 연결성, 공급망 지속가능성 등이 다뤄질 예정이며, 참가자들은 향후 10년간 물류 산업에 영향을 미칠 무역 흐름과 기술, 금융 및 투자 관련 주요 의사결정을 논의할 예정이다.</p><p>사우디아라비아 교통물류서비스부는 이번 포럼이 전략적 이니셔티브를 출범시키고 국제 파트너십을 구축하는 플랫폼 역할을 할 것이라고 밝혔다. 교통물류서비스부(Ministry of Transport and Logistic Services, MOTLS)는 육상·해상·항공·철도 전반에 걸쳐 사우디아라비아의 교통 및 물류 인프라를 계획·규제·개발하는 정부 기관으로, 살레 알자세르(Saleh Al-Jasser) 장관이 이끌고 있다.</p>', '11월 29일부터 12월 1일까지 킹 압둘아지즈 국제컨퍼런스센터에서 ‘2026 유엔무역개발회의 글로벌 공급망 포럼’과 연계해 열린다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/08/3717472907_20260819021347_6715176510.jpg', '2026-08-19T00:45:20.000Z'::timestamptz, array['글로벌 물류 포럼', '사우디아라비아', 'UNCTAD']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1040707'),
  ('logistics', 'LG CNS·LX판토스, 청라 물류센터에 휴머노이드 로봇 자동화 구축', '<p>@@BYLINE@@&nbsp;LG CNS(대표 현신균)가 종합 물류기업 LX판토스와 로봇 기반 ‘차세대 스마트물류 구축’을 위한 업무협약을 체결했다. 양사는 이번 협약에 따라 LX판토스의 메가와이즈 청라 물류센터에 휴머노이드 로봇과 셔틀 로봇을 연계한 물류 자동화 시스템을 구축한다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/06/31017998_20260611103232_5765231452.jpg" alt="LG CNS 본사에서 열린 ‘차세대 스마트물류 구축 업무협약식’에서 LG CNS 이준호 전무(오른쪽 다섯 번째), 박상균 전무(오른쪽 네 번째), LX판토스 어재혁 부사장(왼쪽 다섯 번째)을 비롯한 양사 임직원들이 기념 촬영을 하고 있다."><p><em>▲ LG CNS 본사에서 열린 ‘차세대 스마트물류 구축 업무협약식’에서 LG CNS 이준호 전무(오른쪽 다섯 번째), 박상균 전무(오른쪽 네 번째), LX판토스 어재혁 부사장(왼쪽 다섯 번째)을 비롯한 양사 임직원들이 기념 촬영을 하고 있다.</em></p><p>LG CNS는 휴머노이드와 셔틀 로봇을 연계해 LX판토스 물류센터 업무 전 공정의 자동화를 검증할 예정이다. 셔틀 로봇이 창고에서 출고 예정 물품을 반출하면 휴머노이드 로봇이 물품을 받아 자동 분류 설비 또는 로봇에 적재하고, 분류된 물품이 목적지별로 출고되는 과정을 구현하는 방식이다.</p><p>LG CNS는 LX판토스의 물류 현장 데이터를 기반으로 로봇을 학습시킨다. 학습에는 자체 로봇 학습 플랫폼 ‘피지컬웍스 포지(PhysicalWorks Forge)’를, 로봇 운영에는 통합 관제 플랫폼 ‘피지컬웍스 바통(PhysicalWorks Baton)’을 활용한다.</p><p>로봇 하드웨어로는 LG CNS가 지난 3월 투자한 미국 로봇 전문기업 덱스메이트(Dexmate)의 휠타입 휴머노이드 로봇과 LG CNS가 자체 개발한 물류 로봇 ‘모바일 셔틀’이 쓰인다. 모바일 셔틀은 물류창고 선반 내에서 초당 1.5m 속도로 이동하며, 1대당 최대 1500kg의 물품을 적재하고 운반할 수 있다.</p><p>LG CNS는 이번 협력을 통해 LX판토스 물류 현장의 반복 업무 부담을 줄이고 안정적인 작업 환경을 구현할 계획이다. 양사는 물류 자동화 프로세스를 시연하는 실증 공간 ‘TDL 랩(Tech Driven Logistics Lab)’을 올해 하반기 중 구축하고, 향후 외부 고객 대상 물류 로봇 사업화도 추진할 계획이다.</p><p>박상균 LG CNS 통신/유통/서비스사업부장(전무)은 “이번 업무협약은 다양한 로봇과 학습·운영 플랫폼을 활용한 물류 현장 적용 가능성 실증 프로젝트”라며 “LX판토스와 함께 물류 현장의 생산성과 운영 효율 향상에 기여해 나가겠다”고 밝혔다.</p><p>LX판토스는 전 세계 380여 개 물류 거점 네트워크를 기반으로 포워딩, 계약 물류, 라스트마일 배송, 이커머스 물류 등의 서비스와 함께 창고 및 재고 관리, 통관까지 엔드투엔드 통합 물류 서비스를 제공하고 있다.</p>', '양사가 업무협약을 맺고 휴머노이드·셔틀 로봇을 연계해 물류센터 전 공정 자동화를 검증한다. 올해 하반기 실증 공간 ‘TDL 랩’도 구축한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/06/31017998_20260611103232_5765231452.jpg', '2026-06-11T01:36:20.000Z'::timestamptz, array['LG CNS', 'LX판토스', '휴머노이드 로봇', '스마트물류']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1036311'),
  ('logistics', '비브로, 김포에 B2B 물류 특화 제2물류센터 개설', '<p>@@BYLINE@@&nbsp;비브로가 K-뷰티 브랜드의 글로벌 유통 확대에 대응하기 위해 경기도 김포시에 제2물류센터를 개설했다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/05/3717894431_20260529132629_9356300710.png" alt="경기도 김포시에 새롭게 개설된 비브로 제2물류센터 전경"><p><em>▲ 경기도 김포시에 새롭게 개설된 비브로 제2물류센터 전경</em></p><p>비브로는 유통, 물류, 이커머스 운영, 마케팅을 통합 제공하며 국내 K-뷰티 브랜드의 해외 시장 진출을 지원하는 기업이다. 그동안 일본 시장을 중심으로 국내 브랜드사의 해외 판매 채널 확대와 수출 물류 운영을 지원해 왔으며, 최근 고객사의 물동량 증가와 B2B 물류 수요 확대에 따라 제2물류센터 개설을 추진했다.</p><p>제2물류센터는 경기도 김포시 양촌읍 학운산단5로다길 27-4에 있으며, 브랜드사 및 파트너사의 대량 입출고, 보관, 검수, 라벨링, 출고 준비 등 B2B 물류 수요에 특화된 거점으로 운영될 예정이다. 비브로는 이를 통해 브랜드사가 대량 납품, 해외 출고, 유통 채널별 입고 준비 등의 물류 과정을 수행하고, 해외 판매 채널 확대 과정에서 발생하는 물류 부담을 줄일 수 있을 것이라고 설명했다.</p><p>비브로는 K-뷰티 브랜드의 해외 진출이 늘면서 판매 채널별 물류 기준 대응, 출고 전 검수, 라벨링, 대량 출고 준비, 재고 관리 등 브랜드사가 필요로 하는 물류 기능이 세분화되고 있으며, 특히 일본을 비롯한 해외 유통 채널은 상품별 관리 기준과 출고 조건이 다양하다고 설명했다.</p><p>기존 제1물류센터는 B2C와 B2B 물류를 함께 수행하며 입고, 보관, 검수, 출고 등 전반적인 물류 업무를 담당해 왔다. 앞으로 제1물류센터는 개별 주문 및 출고 중심의 B2C 풀필먼트 운영 효율성을 높이고, 제2물류센터는 대량 물류와 기업 간 거래 기반의 B2B 물류를 중심으로 운영된다. 비브로는 물류센터별 역할을 명확히 정립해 고객사별 물류 목적과 출고 형태에 맞춘 서비스를 제공할 계획이다.</p><p>하워드 토니 비브로 대표는 “비브로는 K-뷰티 브랜드가 해외 시장에서 안정적으로 성장할 수 있도록 유통, 물류, 이커머스 운영, 마케팅을 연결한 통합 서비스를 제공해 왔다”며 “이번 제2물류센터 개설은 고객사의 대량 물류와 글로벌 유통 확대 수요에 보다 전문적으로 대응하기 위한 중요한 기반”이라고 밝혔다.</p><p>이어 “해외 시장에 진출하는 브랜드사 입장에서는 판매 채널을 확보하는 것만큼이나 안정적인 재고 관리와 정확한 출고, 채널별 물류 기준 대응이 중요하다”며 “비브로는 제2물류센터를 통해 고객사가 복잡한 물류 과정에 대한 부담을 줄이고, 글로벌 시장에서 더욱 빠르고 안정적으로 성장할 수 있도록 지원하겠다”고 말했다.</p><p>비브로는 제2물류센터를 기반으로 보관 관리, 출고 전 검수, 라벨링, 채널별 출고 준비, 대량 물류 대응 역량을 고도화하고, 수출 물류 파트너로서 사업 기반을 확대해 나갈 계획이다.</p>', 'K-뷰티 브랜드의 대량 입출고·검수·라벨링 등 B2B 물류 거점으로 운영하고, 기존 제1물류센터는 B2C 풀필먼트 중심으로 역할을 나눈다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/05/3717894431_20260529132629_9356300710.png', '2026-05-29T04:59:21.000Z'::timestamptz, array['비브로', '물류센터', 'K-뷰티', 'B2B 물류']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1035517'),
  ('logistics', 'GS25 ‘내일택배’, 배송 지역 수도권에서 전국으로 확대', '<p>@@BYLINE@@&nbsp;편의점 GS25가 서울과 수도권 지역을 대상으로 운영하던 익일 도착 택배 서비스 ‘내일택배’를 전국 권역으로 확대한다.</p><p>GS리테일이 운영하는 GS25는 8월 24일부터 ‘내일택배’의 서비스 지역을 확대 운영한다. 접수처는 기존 대비 3배 이상 늘어난 수도권 9500여 개 GS25 점포이며, 배송 지역은 수도권에서 전국(제주 및 도서산간 등 일부 지역 제외)으로 넓어진다.</p><p>‘내일택배’는 지난해 12월 선보인 이후 올해 7월 기준 론칭 초기 대비 약 400% 신장했다. GS25는 고객 수요가 꾸준히 증가함에 따라 서비스 범위를 전국으로 확대하게 됐다고 설명했다. 평일 17시, 토요일 12시 이전 접수분에 한해 다음날 도착을 보장하며, 이용 가능 물품은 세 변 합 160cm 이내, 20kg 이하 상품이다.</p><p>GS25는 ‘내일택배’ 외에 ‘반값택배’, ‘방문택배’, ‘국제택배’ 등의 택배 서비스를 운영하고 있다. 점포에서 접수하고 점포에서 수령하는 방식의 ‘반값택배’는 월평균 100만 건 규모의 이용이 발생하고 있으며, 명절을 포함해 연중무휴로 운영된다.</p><p>‘방문택배’는 고객이 GS postbox 홈페이지(웹/모바일) 및 GS25 편의점 택배 APP의 방문 택배 페이지에 송/수하인 정보를 입력하고 방문 희망일을 지정해 접수하면, 택배기사(CJ대한통운)가 발송지를 직접 방문해 상품을 수거하고 배송지로 전달하는 방식이다.</p><p>이경한 GS리테일 서비스상품팀 MD는 “택배 시장의 다양한 서비스 중에서 GS25는 보다 신속한 배송을 원하는 고객을 위한 ‘내일택배’의 서비스 권역을 전국적으로 확대 운영하게 됐다”며 “서비스 프로세스를 세밀하게 다듬고, 틈새 수요에 대한 만족도 향상을 통해 대한민국 넘버 1 연결 플랫폼으로 자리 잡도록 노력하겠다”고 말했다.</p>', '8월 24일부터 수도권 9500여 개 점포에서 접수해 제주·도서산간 등 일부 지역을 제외한 전국으로 다음날 배송한다.', null, '2026-08-26T04:43:40.000Z'::timestamptz, array['GS25', '내일택배', '편의점 택배']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1041172'),
  ('logistics', '페레그린 콜드 로지스틱스, 시나르 프리메라와 인도네시아 냉동 보관 합작', '<p>@@BYLINE@@&nbsp;아시아 통합 냉동 보관 및 물류 플랫폼 페레그린 콜드 로지스틱스(Peregrine Cold Logistics, 이하 페레그린)가 인도네시아 뉴 이코노미 부동산 개발업체 시나르 프리메라(Sinar Primera)와의 합작 투자를 통해 인도네시아 시장에 진입한다고 발표했다. 양사는 합작 투자로 인도네시아 전역에서 1등급 냉동 보관 자산을 인수하고 개발할 계획이다.</p><p>양사의 파트너십은 시나르 프리메라가 소유한 플루이트 소재 기존 시설의 인수와 나로공의 새로운 그린필드 개발을 결합한 것이다. 플루이트 시설은 자카르타 북부 및 서부 전역의 고객에게 서비스를 제공하고 있으며, 반자동화 냉동 및 냉장 용량을 갖춘 신규 나로공 시설은 허브 앤 스포크 모델의 중심 역할을 하게 된다.</p><p>이번 파트너십은 페레그린 확장의 다음 단계로, 필리핀 내 기존 콜드체인 플랫폼과 아세안 및 GCC 전역의 고성장 시장을 연결하는 페레그린의 통합 네트워크에 더해진다. 페레그린은 이번 진출이 소득 증가, 도시화, 점점 더 정교해지는 식품 및 유통 부문으로 인도네시아 전역에서 현대적인 온도 제어 인프라 수요가 가속화되고 있음을 반영한다고 설명했다. 인도네시아는 식품 생산자, 수입업체 및 수출업체, FMCG 기업, QSR 체인 등을 군도 전역의 공급망과 연결하는 페레그린 지역 네트워크에서 중추적인 역할을 맡게 된다.</p><p>합작 투자는 시나르 프리메라의 현지 시장 개발 지식, 토지 접근성, 현장 실행 역량과 페레그린의 글로벌 콜드체인 네트워크 및 운영 역량을 활용해 규모를 확장한다는 구상이다.</p><p>제프 호가스(Jeff Hogarth) 페레그린 콜드 로지스틱스 공동 창립자 겸 CEO는 “인도네시아 진출은 통합된 국제 콜드체인 플랫폼을 구축하려는 페레그린의 전략에 있어 중요한 이정표이다. 시나르 프리메라와의 파트너십을 통해 강력한 현지 시장 지식과 기존 인프라를 페레그린의 국제적 운영 경험 및 고객 관계와 결합하고 있다”며 “우리의 목표는 단순히 인도네시아에 시설을 구축하는 것이 아니라, 이 시장을 우리의 광범위한 아세안 및 GCC 네트워크에 연결하여 고객을 위한 보다 통합된 물류 솔루션과 지역 전역의 장기적 성장을 위한 플랫폼을 만드는 것이다”라고 말했다.</p><p>홍 카 진(Hong Kah Jin) 시나르 프리메라 그룹 대표는 “페레그린이 입증한 콜드체인 전문성과 국제적인 고객 기반을 우리의 강력한 현지 시장 실행력 및 양질의 인프라 공급 능력과 결합함으로써 페레그린과 협력하게 되어 기쁘게 생각한다”며 “우리는 국가의 식량 안보를 강화하는 정부의 정책에 부합하여 인도네시아 내 온도 제어 인프라에 대한 증가하는 수요를 충족시키고자 한다”고 말했다.</p><p>싱가포르에 본사를 둔 페레그린은 인프라 및 실물 자산 전문 대체 투자 회사 스톤피크(Stonepeak)의 지원을 받는 콜드체인 플랫폼으로, 아시아 태평양 및 GCC 전역에서 온도 제어 물류 인프라를 개발하고 운영하고 있다.</p>', '플루이트 기존 시설 인수와 나로공 그린필드 개발을 결합해 인도네시아 시장에 진입하고, 아세안·GCC 콜드체인 네트워크와 연결한다.', null, '2026-09-01T04:35:00.000Z'::timestamptz, array['페레그린 콜드 로지스틱스', '시나르 프리메라', '인도네시아', '콜드체인']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1041582'),
  ('logistics', '주안부평 스마트 물류플랫폼 물류협의회, 3차년도 성과 공유', '<p>@@BYLINE@@&nbsp;주안부평 스마트 물류플랫폼 물류협의회(회장 장동원 이사장)가 지난 4월 23일 한국산업단지공단 주안부평지사에서 열렸다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/04/1794580470_20260424173951_7419290586.jpg" alt="주안부평 스마트 물류플랫폼 물류협의회 참석자들이 단체사진을 촬영하고 있다"><p><em>▲ 주안부평 스마트 물류플랫폼 물류협의회 참석자들이 단체사진을 촬영하고 있다</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/04/1794580470_20260424173957_1635630077.jpg" alt="한국해양수산개발원 이성우 본부장이 ‘호르무즈해협 봉쇄와 물류 공급망 리스크 확대에 따른 중소 제조기업 대응방안’을 주제로 강연하고 있다"><p><em>▲ 한국해양수산개발원 이성우 본부장이 ‘호르무즈해협 봉쇄와 물류 공급망 리스크 확대에 따른 중소 제조기업 대응방안’을 주제로 강연하고 있다</em></p><p>이날 협의회에는 지자체를 비롯해 산·학·연·관의 기업단체 및 유관기관, 수요 기업 대표 등이 참석해 3차년도 사업 추진 경과와 성과를 공유하고 성공모델 확산을 위한 의견을 나눴다. 물류협의회는 고도화 단계에 있는 주안부평 스마트 물류플랫폼의 지속적 운영·확산을 위해 스마트 공동물류센터 입주 기업과 실수요 기업, 지자체 등 유관기관이 중심이 돼 운영될 계획이며, 실질 수요 발굴과 입주 기업이 체감할 수 있는 디지털 물류 환경 구축을 위한 회의를 정기적으로 열 예정이다.</p><p>특별 세션으로 마련된 세미나에서는 한국해양수산개발원 이성우 본부장이 ‘호르무즈해협 봉쇄와 물류 공급망 리스크 확대에 따른 중소 제조기업 대응방안’을 주제로 특강을 진행했다. 이 본부장은 호르무즈해협 봉쇄 사태와 관련해 물류망을 갖고 있는 국가의 물류 안정성을 언급하며 대한민국 물류망의 중요성을 강조하고, 국가와 지자체의 노력, 외교 안보 전략 수정과 함께 많은 기업의 병렬적인 움직임이 필요하다고 제시했다. 또 공급망은 국가의 중요한 무기이며, 좋은 물류 문화를 선도하는 것이 국가 물류 경쟁력을 높이는 중요한 요소라고 강조했다.</p><p>스마트 물류플랫폼은 산업단지 내 물류센터를 첨단화하고 물류 자원 공동 활용 등 디지털 물류 생태계를 조성하기 위해 산업통상부와 한국산업단지공단이 추진하는 사업이다. 주안부평 스마트 물류플랫폼은 현대글로비스 컨소시엄(주관기업 현대글로비스, 참여기업 물류혁명코리아)이 소·부·장 및 패션·뷰티 업종이 집적된 산단 특성에 맞춰 디지털 물류 신기술이 적용된 미래형 그린산단으로의 전환과 지역 성장 동력 확보를 목표로 2024년부터 추진하고 있다.</p><p>물류혁명코리아는 2026년 11월까지 산단 입주기업을 대상으로 물류 진단 및 개선을 지원할 계획이며, 신청기업에 한해 기업별 1:1 맞춤 설명회도 진행하고 있다고 밝혔다.</p><p>물류혁명코리아는 이번 협의회를 기점으로 입주기업의 물류 애로사항이 디지털 물류 환경에서 해결될 수 있도록 스마트 물류플랫폼의 지속적인 개선과 고도화를 추진해 나갈 계획이다.</p>', '4월 23일 한국산업단지공단 주안부평지사에서 열린 협의회에서 사업 추진 경과를 공유하고, 한국해양수산개발원 이성우 본부장이 호르무즈해협 봉쇄에 따른 공급망 리스크 대응을 주제로 특강했다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/04/1794580470_20260424173951_7419290586.jpg', '2026-04-27T00:30:00.000Z'::timestamptz, array['스마트 물류플랫폼', '주안부평 산단', '물류혁명코리아', '한국산업단지공단']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1033139'),
  ('logistics', '비엣비즈코리아, 베트남 콜드체인 시장 진단 보고서 발간', '<p>@@BYLINE@@&nbsp;비엣비즈코리아가 베트남 현지 물류 분야 전문가들의 최신 논의를 정리한 스팟 보고서 ‘베트남 물류·콜드체인 인사이트 리포트 2026 - 콜드체인’을 발간했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/05/3543975132_20260521095720_7724778894.jpg" alt="비엣비즈코리아가 발간한 ‘베트남 물류·콜드체인 인사이트 리포트 2026 - 콜드체인’과 ‘한국 물류 혁신 인사이트 리포트 2026’ 표지. 두 보고서는 베트남 물류·콜드체인 시장의 운영 리스크와 한국 선행 사례를 바탕으로 한 물류 혁신 방향을 다뤘다(제공=VietBiz Korea)"><p><em>▲ 비엣비즈코리아가 발간한 ‘베트남 물류·콜드체인 인사이트 리포트 2026 - 콜드체인’과 ‘한국 물류 혁신 인사이트 리포트 2026’ 표지. 두 보고서는 베트남 물류·콜드체인 시장의 운영 리스크와 한국 선행 사례를 바탕으로 한 물류 혁신 방향을 다뤘다(제공=VietBiz Korea)</em></p><p>보고서는 베트남의 취약한 콜드체인 인프라가 K-푸드 관련 현지 한국 기업에는 위험 요인으로 작용하는 반면 콜드체인 솔루션 제공업체에는 새로운 기회로 부상하는 등 베트남 콜드체인 시장이 전환기에 있다고 진단했다.</p><p>‘아스트라제네카부터 트랜시멕스까지, 현지 운영자와 글로벌 기업이 말하는 실제 리스크와 대응 전략’을 부제로 한 이번 보고서는 △베트남 콜드체인의 다음 단계 △베트남 콜드체인, 설비 중심에서 운영 중심으로 △식품 손실에서 ESG 규제까지: 베트남 콜드체인이 직면한 구조적 과제와 해법 등으로 구성됐다. 비엣비즈코리아는 보고서가 어떤 물류 파트너를 선택해야 하는지, 어떤 서비스 수준을 요구해야 하는지, 비용과 품질 사이에서 무엇을 확인해야 하는지를 판단할 근거를 제시한다고 설명했다.</p><p>보고서는 앞으로 현지 고객이 창고 면적이나 차량 보유 대수보다 온도 관리 능력, 데이터 제공 역량, 식품·제약 규정 이해도, 에너지 효율, 라스트마일 대응력을 더 중요하게 볼 가능성이 크다고 보고, 한국 물류 기업이 기존 운송·창고 중심 서비스에서 콜드체인 솔루션형 사업자로 전환하기 위해 보완해야 할 점을 다뤘다.</p><p>이성주 비엣비즈코리아 대표는 “베트남 현지 물류 전문가들은 콜드체인 시장이 전환기를 맞고 있다고 진단하고 있다”며 “열악한 인프라는 K-푸드와 의약품 분야에는 위험 요소가 되지만, 콜드체인 솔루션 사업자에게는 중요한 시장 기회가 되고 있다”고 말했다.</p><p>비엣비즈코리아는 ‘한국 물류 혁신 인사이트 리포트 2026 - 한국 선행 사례로 점검하는 베트남 물류 운영의 새로운 기준’ 보고서도 발간했다. 이 보고서는 한국 물류 기업과 수요 기업의 최신 운영 사례를 통해 베트남에서 물류 파트너를 선정할 때 다시 봐야 할 점을 점검하는 내용으로, 인공지능(AI), 자동화, 콜드체인, 제약 물류, 냉매 관리, 플랫폼형 운영 등의 사례를 통해 비용 중심 판단에서 운영 안정성·품질 관리·규제 대응 역량 중심 판단으로 이동하는 시장 변화를 소개한다.</p><p>보고서에는 △한국 물류 기업의 AI 적용 현황과 전망 △피지컬 AI(Physical AI) 기반 네트워크 운영과 로봇 자동화 사례 △규제 강화 시대에 품질 유지와 운영 안정성을 동시에 요구받는 국내 콜드체인 시장 △제약 콜드체인 운영 전략 △콜드체인 경쟁력으로 부상한 냉매 전주기 관리 △쿠팡의 물류 스마트화와 AI 활용 현황 등이 담겼다.</p>', '현지 물류 전문가 논의를 정리해 취약한 콜드체인 인프라가 K-푸드 기업에는 위험, 솔루션 사업자에게는 기회가 되고 있다고 진단했다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/05/3543975132_20260521095720_7724778894.jpg', '2026-05-21T04:00:00.000Z'::timestamptz, array['비엣비즈코리아', '베트남', '콜드체인', '물류 보고서']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1034948'),
  ('logistics', '콜트랜스, K-POP 공동구매 운영자 특화 물류 서비스 ‘케이픽’ 론칭', '<p>@@BYLINE@@&nbsp;글로벌 구매대행 전문기업 콜트랜스(대표 문병호)가 해외 K-POP 팬덤의 공동구매 운영을 지원하는 역직구 하이브리드 물류 서비스 ‘케이픽(Kaypick)’을 오는 7월 1일 공식 론칭한다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/06/238285539_20260625003548_5061429389.png" alt="콜트랜스의 역직구 물류 서비스 ‘케이픽(Kaypick)’ 로고"><p><em>▲ 콜트랜스의 역직구 물류 서비스 ‘케이픽(Kaypick)’ 로고</em></p><p>케이픽은 K-POP 앨범, 굿즈, 팬클럽 상품 등 한국에서 구매·수령이 필요한 상품을 해외 팬덤에게 전달하기 위한 해외 K-POP 공동구매 운영자(GOM, Group Order Manager) 특화 물류 서비스다. 상품 확보, 국내 픽업, 검수, 포장, 해외배송, 통관 대응까지 공동구매 운영 과정을 원스톱으로 지원한다.</p><p>콜트랜스에 따르면 해외 팬들은 개별 구매 시 배송비와 통관 부담이 커 GOM을 중심으로 공동구매를 진행해 왔으며, GOM은 여러 팬의 주문을 모아 상품 구매부터 구성품 분류, 포장, 국제배송까지 직접 관리해 왔다. 그러나 수십~수백 건의 주문·결제·분류·포장·통관을 직접 처리해야 하는 데다, 최근 미국의 800달러 소액 면세 폐지와 미국행 소형화물 통관·배송 정책 변화로 국제 배송비와 통관 부담이 커지면서 GOM의 금전적 리스크와 운영 스트레스가 커지고 있다는 설명이다. 관세청 집계로 2025년 K-POP 음반 수출액은 3억170만달러를 기록했다.</p><p>케이픽은 환율이나 배송비 상황에 맞춰 원하는 시점에 물품을 발송할 수 있도록 최대 6개월간 보관 서비스를 제공한다. 여러 주문 건을 하나로 묶어 부피 무게를 줄이는 ‘합배송’과 앨범 등 부피가 큰 상품에서 필요한 구성품만 선별해 발송하는 ‘분리배송’도 지원하며, 언박싱 검수, 반품 대행, 관세 납부 및 통관 이슈 지원, 실시간 배송 추적 서비스도 제공한다.</p><p>콜트랜스는 △예측 가능한 비용 △예측 가능한 배송 △예측 가능한 품질을 케이픽의 3대 서비스 방향으로 제시했다. 비용 산정, 글로벌 배송 네트워크, 검수와 패킹 품질 관리를 통해 GOM이 공동구매 과정에서 마주하는 비용·일정·품질 리스크를 줄이는 데 초점을 맞췄다는 설명이다. 브랜드 슬로건은 ‘Unbox Korea, Without the Stress’다.</p><p>문병호 콜트랜스 대표는 “K-POP의 글로벌 확산 뒤에는 각국 팬덤을 위해 묵묵히 공동구매를 운영해 온 GOM들의 노고가 있었다”며 “케이픽은 이들의 책임과 부담을 덜어주고, 복잡한 운영 과정을 더 쉽고 안전하게 관리할 수 있도록 돕는 K-POP 공동구매 전문 물류 파트너가 될 것”이라고 밝혔다.</p><p>케이픽은 해외 K-POP GOM을 위한 물류 지원 서비스로 출발해 향후 K-Beauty, K-Fashion, K-Food 등 한국 라이프스타일 전반으로 서비스 영역을 확장해 나갈 계획이다.</p>', '7월 1일 공식 출시하는 케이픽은 상품 확보부터 국내 픽업, 검수, 포장, 해외배송, 통관 대응까지 해외 팬덤의 공동구매 운영 과정을 원스톱으로 지원한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/06/238285539_20260625003548_5061429389.png', '2026-06-25T01:00:00.000Z'::timestamptz, array['콜트랜스', '케이픽', '역직구 물류', 'K-POP']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1037305'),
  ('logistics', 'GS샵, 고객이 반품 수거일 지정하는 ‘수거일 선택’ 도입', '<p>@@BYLINE@@&nbsp;GS샵이 4월 20일부터 고객이 반품하는 날을 직접 지정할 수 있는 ‘수거일 선택’ 서비스를 도입했다. GS샵은 이 서비스를 홈쇼핑 업계 최초로 도입했다고 밝혔다. 고객이 원하는 일정에 맞춰 상품 도착일을 선택할 수 있는 ‘도착일 선택’ 서비스도 지난 13일부터 적용 범위를 확대했다.</p><p>GS샵은 그간 △오늘도착(당일 배송) △내일도착(익일 배송) △휴일에도 내일도착(휴일 배송) △도착일 선택 등의 배송 서비스를 운영해 왔다. 올해는 고객 조사와 해외 사례 연구 등을 바탕으로 고객 니즈가 크지만 충분히 지원하지 못했던 영역을 찾아 배송 서비스를 보강했다고 설명했다.</p><p>‘수거일 선택’ 서비스는 TV홈쇼핑 방송 상품 전체를 대상으로, 고객이 반품을 신청할 때 7일 이내에서 원하는 수거일을 지정할 수 있도록 한 것이다. 현재 GS샵은 반품 요청의 약 97%를 익일에 수거하고 있으나, 고객이 외출 등 개인 사정으로 반품하지 못하는 비중이 3%가량 발생하고 있다. GS샵은 수거일 선택 서비스로 고객 불편을 줄이는 동시에 재방문 수거로 발생하는 물류 비효율도 완화할 수 있을 것으로 기대하고 있다.</p><p>2022년부터 운영해 온 ‘도착일 선택’은 TV홈쇼핑 방송 상품 중 GS샵 물류센터에 입고된 상품만을 대상으로 했으나, 이번에 협력사를 방문해 상품을 수령한 뒤 배송하거나 협력사가 직접 배송하는 상품까지 대상이 넓어졌다. 이에 따라 ‘도착일 선택’이 가능한 상품 비중은 기존 55%에서 90% 수준으로 늘었고, 카테고리도 신선식품까지 확대됐다. GS샵이 올해 1월 실시한 배송 서비스 관련 고객 조사에서는 ‘도착일 선택 배송’을 원한다는 응답이 92%에 달했다.</p><p>GS샵은 상품 설명 및 주문 화면의 UI와 UX도 개선해 고객이 주문 및 반품 단계에서 도착일과 수거일 선택 옵션을 확인하고 본인 일정에 맞춰 배송을 설계할 수 있도록 했다.</p><p>이종현 GS샵 물류기획팀장은 “고객이 배송과 수거 일정 때문에 겪는 불확실성을 줄이고, 라이프스타일에 맞춰 스스로 선택할 수 있도록 온디맨드 서비스를 강화했다”며 “도착일 선택 확대와 홈쇼핑 업계 최초 수거일 선택 시행을 시작으로, 고객 경험을 중심에 둔 배송 서비스를 지속적으로 고도화해 나가겠다”고 말했다.</p>', 'TV홈쇼핑 방송 상품 반품 시 7일 이내에서 수거일을 지정할 수 있게 하고, ‘도착일 선택’ 가능 상품 비중은 55%에서 90% 수준으로 늘렸다.', null, '2026-04-21T01:15:18.000Z'::timestamptz, array['GS샵', '온디맨드 배송', '반품', '홈쇼핑']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1032768'),
  ('logistics', '현대무벡스, 미국 ‘MODEX 2026’서 스마트 물류 솔루션 전시', '<p>@@BYLINE@@&nbsp;현대무벡스가 4월 13일부터 16일까지(현지시간) 미국 애틀랜타 ‘조지아 월드 콩그레스 센터’에서 열리는 물류·공급망 전시회 ‘MODEX 2026’에 참가한다고 밝혔다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/04/31017998_20260408115022_5281289464.jpg" alt="현대무벡스가 4월 13일부터 16일까지 미국 애틀란타에서 열리는 ‘MODEX 2026’에 참가해 ‘AI·Robotics Automation Solution Partner’ 슬로건을 내걸고 AI·로봇 물류 솔루션을 선보인다. 현대무벡스 전시 부스 조감도(제공: 현대무벡스)"><p><em>▲ 현대무벡스가 4월 13일부터 16일까지 미국 애틀란타에서 열리는 ‘MODEX 2026’에 참가해 ‘AI·Robotics Automation Solution Partner’ 슬로건을 내걸고 AI·로봇 물류 솔루션을 선보인다. 현대무벡스 전시 부스 조감도(제공: 현대무벡스)</em></p><p>현대무벡스에 따르면 MODEX는 북미 최대 규모의 물류 산업 전시회로, 올해는 1200여 개 기업이 참가하고 약 5만 명이 방문할 것으로 예상된다. 데마틱(Dematic), 다이후쿠(Daifuku), 크납(KNAPP) 등 글로벌 물류 자동화 기업들도 참여할 예정이다.</p><p>현대무벡스는 이번 전시에서 AI·로봇 기술이 융합된 ‘토털 스마트 물류 솔루션’을 선보인다. 부스는 개방형 구조로 꾸미고 상담 공간을 배치해 글로벌 고객과의 소통 거점으로 운영하며, 전시는 △로봇 시연 △실물 배치 △DT(디지털 트윈) △목업(Mock-up·모형) 등 구역으로 나눠 핵심 스마트 물류 제품과 제어시스템을 공개한다.</p><p>현장에서는 지난 3월 ‘AW 2026’(스마트공장·자동화산업전)에서 선보인 ‘AMR(자율주행모바일로봇) 군집퍼레이드’와 전후좌우 자율 이동이 가능한 ‘전방향 AGV’(무인이송로봇) 시연이 진행된다. 이미 양산하고 있는 △고하중 AGV(2톤급 포크형) △미니 AGV(소·경량 이송용)와 공급을 준비하고 있는 △저상형 AGV △챗봇 AMR(안내·서빙용) △딜리버리 로봇(엘리베이터 연동) △차세대 EMS(천정궤도이송) △4Way 셔틀(전 방향 주행 이송 장치) 등도 전시한다.</p><p>산업 현장을 제어하는 ‘3D 디지털 트윈’도 소개된다. 미국 전시 현장과 현대무벡스 청라R&amp;D센터를 실시간으로 연결해 주요 자동화 설비 현황을 영상으로 중계하고, 통합 관제 시스템 ‘VCS’(Vehicle Control System)를 통해 실제 현장 장비의 운용 흐름을 다중 고객이 모니터로 볼 수 있도록 했다.</p><p>현대무벡스는 이번 전시 슬로건으로 ‘AI·Robotics Automation Solution Partner’(AI·로보틱스 자동화 솔루션 파트너)를 제시했다. 그간 축적한 스마트 물류 역량을 바탕으로 글로벌 고객사와 함께 지능화 물류 혁신을 이루고, ‘K-로봇’의 경쟁력을 앞세워 글로벌 시장을 공략하겠다는 의미를 담았다고 회사 측은 설명했다.</p><p>현대무벡스는 MODEX가 글로벌 스마트 물류 기업과 고객이 한자리에 모이는 산업 플랫폼이라며, 이번 전시를 통해 글로벌 탑티어 기업들과의 접점을 넓히고 신규 고객 발굴과 글로벌 확장의 발판을 마련할 것이라고 밝혔다. 현대무벡스는 스마트 물류, 스크린도어, IT서비스 사업 등을 영위하는 현대그룹 계열사다.</p>', '4월 13~16일 미국 애틀랜타에서 열리는 전시회에서 AMR 군집퍼레이드와 전방향 AGV를 시연하고, 청라R&D센터와 연결한 3D 디지털 트윈을 선보인다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/04/31017998_20260408115022_5281289464.jpg', '2026-04-08T02:53:16.000Z'::timestamptz, array['현대무벡스', 'MODEX 2026', '물류 자동화', 'AGV']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1031954'),
  ('logistics', '삼성SDS, 첼로스퀘어 콘퍼런스서 에이전틱 AI 공급망 전략 공유', '<p>@@BYLINE@@&nbsp;삼성SDS가 4월 2일 판교 물류캠퍼스에서 ‘에이전틱 AI 공급망 시대’를 주제로 ‘첼로스퀘어 콘퍼런스 2026(Cello Square Conference)’을 개최했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/04/1028147215_20260402113120_7340174825.jpg" alt="삼성SDS 오구일 물류사업부장(부사장)이 2일 판교 물류캠퍼스에서 진행된 ‘첼로스퀘어 콘퍼런스 2026(Cello Square Conference)’에서 키노트를 발표하고 있다"><p><em>▲ 삼성SDS 오구일 물류사업부장(부사장)이 2일 판교 물류캠퍼스에서 진행된 ‘첼로스퀘어 콘퍼런스 2026(Cello Square Conference)’에서 키노트를 발표하고 있다</em></p><p>이번 행사는 제조, 유통 기업 등 약 120개 화주사를 초청해 글로벌 공급망 리스크 대응 전략과 물류 업계의 핵심 트렌드 및 사례를 공유하는 자리로 마련됐다. 삼성SDS는 생성형 AI를 기반으로 다양한 정형·비정형 데이터를 분석해 10개 트렌드를 도출한 뒤 자사의 물류 전문성을 더해 3대 핵심 인사이트를 정리했다.</p><p>오구일 삼성SDS 물류사업부장(부사장)은 키노트에서 △의사결정이 가능한 자동화된 컨트롤 타워 △복합적인 의사결정을 지원하는 디지털 트윈의 부상 △물류의 직·간접 비용까지 모두 고려한 총비용 기반 의사결정 확대를 제시하며 물류 현장 사례를 소개했다.</p><p>자동화된 컨트롤 타워는 생산·운송·재고 등 공급망 전 과정의 데이터를 실시간으로 통합해 가시성을 확보하고, AI 기반 분석으로 수요 변동이나 운송 지연 등 이상 상황을 사전에 감지하고 대응하는 운영 체계다. 삼성SDS는 이를 통해 기업이 단순 모니터링을 넘어 예측과 선제 대응, 자율 의사결정이 접목된 운영으로 전환하게 될 것이라고 설명했다.</p><p>디지털 트윈과 관련해서는 글로벌 공급망의 복잡도가 높아지고 창고 내 작업자·자동화 설비·AI 간 협업이 확대되면서 디지털 트윈 기반 시뮬레이션의 중요성이 커지고 있으며, 물류 운영 환경의 변수에 대응하는 대안을 검토하고 최적안을 도출하기 위한 활용이 확대될 것으로 전망했다. 총비용 기반 의사결정은 운송비, 관세 등 전통적 비용뿐 아니라 탄소 배출, 공급망 리스크, 운송 중 화물의 기회비용 등 다양한 변수를 반영한 ‘총비용(True Cost)’ 중심으로 의사결정이 확대되고 있다는 내용이다.</p><p>세부 세션에서는 AI를 통한 기업 혁신 트렌드, 데이터 중심 물류 혁신과 글로벌 컨트롤 타워, 디지털 트윈을 통한 공급망 재설계, AI/자동화가 이끄는 물류 운영의 현재와 미래에 대한 발표가 이어졌다. 행사장에는 삼성SDS 물류의 생성형 AI 서비스를 체험할 수 있는 EBC(Executive Briefing Center) 전시관, 글로벌 컨트롤 센터(GCC) 투어, 첼로스퀘어 체험존과 물류 상담존 등이 마련됐다.</p><p>오구일 부사장은 “삼성SDS는 풍부한 현장 데이터와 선진 AI 기술을 결합해 고객이 빠른 의사결정과 탄력적인 공급망을 구축할 수 있도록 지원할 계획”이라고 밝혔다.</p>', '판교 물류캠퍼스에 화주사 약 120곳을 초청해 자동화된 컨트롤 타워, 디지털 트윈, 총비용 기반 의사결정 등 3대 물류 인사이트를 제시했다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/04/1028147215_20260402113120_7340174825.jpg', '2026-04-02T04:30:00.000Z'::timestamptz, array['삼성SDS', '첼로스퀘어', '에이전틱 AI', '공급망']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1031618'),
  ('logistics', 'SF인트라시티, 2025년 매출 약 4조9967억원… 45.4% 증가', '<p>@@BYLINE@@&nbsp;SF 홀딩 그룹 자회사로 중국에서 온디맨드 배송 플랫폼을 운영하는 SF인트라시티산업(이하 SF인트라시티, HKEX: 9699.HK)이 2025년 연간 실적을 발표하고 매출이 약 4조9967억원(228억9860만위안)으로 전년 대비 45.4% 증가했다고 밝혔다. 회사는 이번 실적이 사상 최대라고 설명했다.</p><p>조정 순이익은 약 904억원(4억1470만위안)으로 184.3% 늘었고, 회사 주주 귀속 순이익은 약 605억원(2억7770만위안)으로 109.7% 증가했다. 매출총이익은 약 3150억원(14억4450만위안)으로 34.8% 늘었으며 매출총이익률은 6.3%, 조정 순이익률은 1.8%를 기록했다. 순현금흐름은 약 859억원(3억9480만위안)으로 전년 대비 45% 증가했다.</p><p>사업 부문별로는 배송 서비스 매출이 약 2조9367억원(134억6690만위안)으로 47.6% 늘었고 주문량은 55% 증가했다. 이 가운데 가맹점 대상 배송 매출은 약 2조3350억원(107억80만위안)으로 60%, 소비자 배송 매출은 약 6030억원(27억6600만위안)으로 13.7% 증가했다. 물류기업을 대상으로 한 라스트마일 배송 서비스 매출은 약 2조557억원(94억3180만위안)으로 42.4% 늘었다.</p><p>SF인트라시티는 주요 고객사와의 협력을 강화하고 지방 도시 침투를 확대하면서 연간 활성 가맹점 수가 112만 개로 72% 증가했다고 밝혔다. 신규 협력 매장은 7900개 이상 확보했고 스타벅스, 메트로 등과 파트너십을 구축했다. 다채널 주문 통합, 1시간 배송 등 맞춤형 솔루션을 강화했으며 슈퍼마켓 부문 배송 매출은 80% 이상 증가했다.</p><p>활성 소비자 규모는 2606만 명을 넘어섰다. 연간 활성 라이더 수는 약 146만 명으로 전년 대비 46% 증가했고 라이더 생산성은 30% 향상됐다. 회사는 무인 배송 차량을 전국 116개 도시에서 운영하며 월평균 5만 건 이상의 배송을 수행하고 있고, AI 기술을 주문 배차, 마케팅, 고객 응대 등 전 과정의 자동화와 최적화에 활용하고 있다고 설명했다.</p><p>SF인트라시티는 ‘고품질·지속가능 성장’을 핵심 운영 목표로 나아가고 있다며 향후 AI 기술 고도화, 무인 배송 확대, 서비스 시나리오 확장을 통해 지속가능한 성장을 이어갈 것이라고 밝혔다. 회사는 △온디맨드 리테일 및 로컬 서비스 확대 △브랜드 체인 침투 강화 △AI 및 자동화 기술 투자 확대 △통합 물류 솔루션 고도화 등을 중심으로 성장 전략을 추진할 계획이다.</p>', '조정 순이익은 약 904억원으로 184.3% 늘었고, 활성 가맹점은 112만 개로 72% 증가했다. 무인 배송 차량은 전국 116개 도시에서 운영 중이다.', null, '2026-04-13T02:37:27.000Z'::timestamptz, array['SF인트라시티', '온디맨드 배송', '라스트마일', '실적']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1032211'),
  ('logistics', '개틱, QIA·KDT 주도 시리즈 D서 2억달러 투자 유치', '<p>@@BYLINE@@&nbsp;자율주행 트럭 운송 기업 개틱(Gatik)이 포춘 50대 소매기업, 식료품 유통기업 및 소비재(CPG) 기업의 공급망에서 무인 상업 화물 운송 수요가 빠르게 증가하는 가운데 2억달러 규모의 자금 조달을 발표했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/1028147215_20260826101341_9438427609.jpg" alt="왼쪽부터 아르준 나라앙(Arjun Narang) 공동창업자 겸 CTO, 아펙샤 쿠마밧(Apeksha Kumavat) 공동창업자 겸 최고 엔지니어, 가우탐 나라앙(Gautam Narang) 공동창업자 겸 CEO"><p><em>▲ 왼쪽부터 아르준 나라앙(Arjun Narang) 공동창업자 겸 CTO, 아펙샤 쿠마밧(Apeksha Kumavat) 공동창업자 겸 최고 엔지니어, 가우탐 나라앙(Gautam Narang) 공동창업자 겸 CEO</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/1028147215_20260826101348_5954059102.jpg" alt="고객 물류센터에 있는 개틱(Gatik)의 자율주행 트럭들"><p><em>▲ 고객 물류센터에 있는 개틱(Gatik)의 자율주행 트럭들</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/08/1028147215_20260826101438_4221000795.jpg" alt="미국 시장에서 운행 중인 개틱(Gatik)의 자율주행 트럭"><p><em>▲ 미국 시장에서 운행 중인 개틱(Gatik)의 자율주행 트럭</em></p><p>이번 시리즈 D 투자 라운드는 카타르투자청(Qatar Investment Authority, QIA)과 코크 디스럽티브 테크놀로지스(Koch Disruptive Technologies, KDT)가 주도했으며 밀레니엄 매니지먼트(Millennium Management), 아크 인베스트(ARK Invest), 인택트 프라이빗 캐피털(Intact Private Capital) 등이 참여했다.</p><p>개틱은 6억달러 이상의 계약 매출을 확보했고 완전 무인 운송 주문 8만5000건을 완료했으며, 운영 전반에서 정시 배송률 99%를 달성했다고 밝혔다. 개틱의 트럭은 물류센터와 매장을 연결하는 고빈도 지역 운송 네트워크에서 상품을 운송하며, 텍사스주, 애리조나주, 아칸소주 및 캐나다 전역에서 운행되고 있다.</p><p>고탐 나랑(Gautam Narang) 개틱 공동창립자 겸 최고경영자는 “세계 유수의 금융기관들이 주도한 이번 투자 라운드는 자율 화물 운송 분야에서 개틱이 보유한 상업적 리더십을 분명히 입증한다”며 “이번 투자 라운드는 속도와 규율을 갖춰 사업을 확장하고 세계 최대 기업들에 서비스를 제공하며 자율 화물 운송의 미래를 정의하는 데 필요한 자본을 제공한다”고 말했다.</p><p>압둘라 알쿠와리(Abdulla Al-Kuwari) QIA 산업 부문 총괄은 “QIA는 화물 운송 인프라의 미래를 만들어가는 개틱과 같은 차세대 솔루션 제공업체를 지원하는 데 전념하고 있다”고 말했다. 바이런 나이트(Byron Knight) 코크 디스럽티브 테크놀로지스 사장은 “오늘날 우리가 목격하는 것은 자율주행 기술이 유망한 기술 단계에서 벗어나 실제 상업 운영 단계로 진입하는 모습이다”라고 말했다. 코크 디스럽티브 테크놀로지스는 2021년 개틱에 처음 투자했다.</p><p>저스틴 스미스-로렌제티(Justin Smith-Lorenzetti) 인택트 프라이빗 캐피털 매니징 디렉터는 “우리는 이번 최신 투자 라운드에서 투자 규모를 3배로 확대했다. 이는 개틱이 북미 자율 화물 운송 분야의 선도기업이 될 수 있는 실행 실적, 고객 확보 성과 및 기술 성숙도를 갖추고 있다는 확신에 따른 것”이라고 설명했다.</p><p>현재 북미 전역에서 수십 대의 무인 트럭을 운행하고 있는 개틱은 향후 수년간 이를 수천 대 규모로 확대할 계획이다.</p>', '자율주행 트럭 운송 기업 개틱이 2억달러 규모 시리즈 D 투자를 유치했다. 북미에서 운행 중인 무인 트럭 수십 대를 향후 수년간 수천 대 규모로 늘릴 계획이다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/08/1028147215_20260826101341_9438427609.jpg', '2026-08-26T02:00:00.000Z'::timestamptz, array['개틱', '자율주행 트럭', '투자 유치', '시리즈 D']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1041145'),
  ('logistics', '보건복지부 등 4개 기관, 약 500억 원 규모 화장품 수출 물류 지원', '<p>@@BYLINE@@&nbsp;보건복지부가 화장품 수출기업의 물류 부담 완화와 글로벌 공급망 대응력 강화를 위한 중소기업 지원사업을 추진한다. 보건복지부는 지난 3월 30일 서울 커뮤니티하우스 마실에서 ‘2026 해외 화장품 물류(수출)지원사업 합동 설명회’를 개최했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/03/238702493_20260330163008_8341759607.jpg" alt="‘2026 해외 화장품 물류(수출)지원사업 합동 설명회’ 행사장"><p><em>▲ ‘2026 해외 화장품 물류(수출)지원사업 합동 설명회’ 행사장</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/03/238702493_20260330163104_3920893336.jpg" alt="‘2026 해외 화장품 물류(수출)지원사업 합동 설명회’ 유관기관 단체사진"><p><em>▲ ‘2026 해외 화장품 물류(수출)지원사업 합동 설명회’ 유관기관 단체사진</em></p><p>설명회에는 대한화장품산업연구원, 대한무역투자진흥공사, 중소벤처기업진흥공단, 한국보건산업진흥원 등 4개 공공기관이 참여해 2026년 추진 사업을 안내했다. 이날 소개된 사업은 총 20개, 약 500억 원 규모로, 400개 이상의 화장품 기업을 대상으로 수출 물류 전반을 지원한다. 보건복지부는 산하 및 유관 공공기관과 함께 물류·유통·금융을 연계한 수출 지원사업을 통합 운영하고 있다.</p><p>최근 글로벌 공급망 불확실성과 물류비 상승이 이어지면서 중소·중견 화장품 기업의 해외 진출 과정에서 물류 비용과 운영 리스크가 주요 부담으로 작용하고 있으며, 정부는 물류 지원을 수출 경쟁력 확보를 위한 핵심 수단으로 보고 지원을 확대하고 있다.</p><p>주요 사업으로는 대한화장품산업연구원의 ‘2026년 해외(미국) 화장품 공동 물류지원사업’, 대한무역투자진흥공사의 ‘2026년 화장품 특화 해외 공동물류센터 사업’, 중소벤처기업진흥공단의 ‘2026년 중소기업 K-뷰티론 정책자금 지원’, 한국보건산업진흥원의 ‘2026년 K뷰티 팝업·플래그십 스토어 사업’ 등이 있다.</p><p>이 가운데 ‘해외(미국) 화장품 공동 물류지원사업’은 미국 현지 물류거점을 활용한 풀필먼트 서비스를 제공해 기업이 별도 물류 인프라를 구축하지 않고도 현지 물류를 운영할 수 있도록 지원한다. 3월 20일부터 4월 13일까지 2차 참여기업을 모집하며, 국내 화장품 제조업자 및 책임판매업자 등 미국 수출 예정 중소·중견기업 약 65개사가 대상이다. 선정 기업에는 미국 로스앤젤레스(LA) 물류거점을 활용한 보관, 풀필먼트, 배송 서비스가 제공된다.</p><p>설명회에서는 기관별 사업 안내와 현장 상담이 함께 진행됐다. 참석 기업의 한 관계자는 각 지원사업의 내용과 적용 가능성을 구체적으로 파악할 수 있었고 실제 사업 적용 방향을 설정하는 데 도움이 됐다고 말했다. 보건복지부는 이번 설명회를 계기로 사업 간 연계성과 접근성을 지속적으로 개선해 나갈 계획이라고 밝혔다.</p>', '‘2026 해외 화장품 물류(수출)지원사업 합동 설명회’에서 20개 사업을 안내했다. 400개 이상 화장품 기업의 수출 물류 전반을 지원한다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/03/238702493_20260330163008_8341759607.jpg', '2026-03-31T00:30:00.000Z'::timestamptz, array['보건복지부', '화장품 수출', '수출 물류', 'K-뷰티']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1031341'),
  ('people', '동원그룹, 동원글로벌터미널부산 대표이사에 윤상건 선임', '<p>@@BYLINE@@&nbsp;동원그룹은 동원글로벌터미널부산(DGT) 대표이사에 윤상건 대표를 5월 15일부로 선임한다고 15일 밝혔다. 글로벌 무역 환경 변화에 대응하고 항만-해운 물류의 연계를 강화하기 위한 인사다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2025/05/31017998_20250515102215_4074421962.jpg" alt="동원글로벌터미널부산 CI"><p><em>▲ 동원글로벌터미널부산 CI</em></p><p>윤 신임대표는 약 40년 동안 전 세계 주요 물류 거점에서 활동한 해운 물류 전문가다. 1987년 한진해운에 입사해 중국 본부 물류팀장, 미주 서비스 센터장 등을 역임했다.</p><p>이후 2017년부터 다국적 물류 기업 DHL에서 3자 물류 담당 임원을, 국적선사 HMM에서 글로벌 물류 운영 담당 임원을 지내며 신규 화주를 유치하고 싱가포르에 전용 터미널을 설립했다. 2022년부터 3년간은 HMM/PSA 신항만 대표이사로 터미널 생산성 개선, 물동량 확장 등의 경영 성과를 냈다.</p><p>동원그룹은 글로벌 무역 환경의 불확실성이 커지는 가운데 글로벌 해운 물류 전문가를 통해 전문성을 강화하고 미래 경쟁력을 확보하기 위해 이번 인사를 실시했다며, 신임 대표와 함께 동북아 최고의 물류 거점 항만으로 거듭날 계획이라고 밝혔다.</p><p>DGT는 지난해 개장한 완전 자동화 항만으로, 동원그룹은 이를 국내 최초라고 소개했다. 컨테이너 하역부터 장치장 이송, 적치에 이르는 전 과정을 자동으로 작업하며 모든 하역장비가 전기로 구동된다. 부산신항 서컨테이너부두 2~5단계를 운영하는 DGT는 2026년과 2027년 피더부두와 2~6단계를 각각 추가로 개장할 계획이다.</p>', '동원그룹이 완전 자동화 항만을 운영하는 DGT 대표이사에 윤상건 대표를 5월 15일부로 선임했다. 윤 대표는 한진해운·DHL·HMM을 거친 해운물류 전문가다.', 'https://file.newswire.co.kr/data/datafile2/data/2025/05/31017998_20250515102215_4074421962.jpg', '2025-05-15T01:23:24.000Z'::timestamptz, array['동원그룹', '동원글로벌터미널부산', '윤상건', '부산신항']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1011173'),
  ('people', 'HMM, 정기주주총회·이사회서 최원혁 대표이사 선임', '<p>@@BYLINE@@&nbsp;HMM은 26일 여의도 파크원 본사에서 열린 제49기 정기주주총회와 이사회에서 최원혁 사장을 대표이사로 선임했다.</p><p>최원혁 대표이사는 CJ대한통운, LX판토스 등 글로벌 물류업계에서 40년 이상 근무한 물류전문가로, LX판토스에서 8년 동안 CEO를 역임했다. HMM은 최 대표가 이 기간 글로벌 물류에 대한 전문성과 경영역량, 조직관리능력 등을 인정받았다고 설명했다.</p><p>이날 주주총회에서는 최원혁 사장과 이정엽 컨테이너사업부문 전무가 사내이사로 신규선임됐고, 서근우 사외이사가 재선임됐다.</p>', 'HMM이 제49기 정기주주총회와 이사회에서 CJ대한통운·LX판토스를 거친 최원혁 사장을 대표이사로 선임했다.', null, '2025-03-26T02:56:06.000Z'::timestamptz, array['HMM', '최원혁', '대표이사', '주주총회']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1008157'),
  ('people', '대한항공, 2026년 정기 임원인사 단행… 총 20명 승진', '<p>@@BYLINE@@&nbsp;대한항공이 2026년 정기 임원 인사를 12월 8일(월)부로 단행한다.</p><p>승진 인사는 총 20명 규모로, 김해룡 상무 외 1명이 전무로 승진하고 구은경 수석 외 17명이 신임 상무로 선임됐다.</p><p>대한항공은 이번 인사가 통합 항공사 출범 준비 및 안정적 운영을 위해 변동 폭은 최소화하는 한편, 경영환경 변화에 능동적으로 대응하기 위해 전문성과 리더십을 갖춘 인재를 승진시켜 조직에 활력을 불어넣고 미래 경쟁력을 강화하는 데 중점을 뒀다고 설명했다.</p><p>대한항공은 절대 안전과 고객 중심 서비스를 핵심 기반으로 통합 항공사 출범 준비를 진행할 계획이라고 밝혔다.</p>', '김해룡 상무 외 1명이 전무로 승진하고 구은경 수석 외 17명이 신임 상무로 선임됐다. 인사는 12월 8일부로 시행된다.', null, '2025-12-04T05:03:50.000Z'::timestamptz, array['대한항공', '임원인사', '통합 항공사']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1024608'),
  ('people', '키넥시스, 최고재무책임자 겸 최고전략책임자에 허브 예 임명', '<p>@@BYLINE@@&nbsp;공급망 계획 및 조정 기업 키넥시스(Kinaxis Inc., TSX:KXS)가 허브 예(Herb Yeh)를 최고재무책임자 겸 최고전략책임자로 임명한다고 발표했다. 임명은 2026년 7월 27일 발효된다.</p><p>예는 키넥시스의 글로벌 재무 조직과 기업 전략 운영 전반을 감독하며 재무, 회계, 투자자 관계, 기업 전략 및 기업 개발 부문을 총괄한다. 경영진 및 이사회와 협력해 규율 있는 실행, 장기적 성장 및 주주 가치 창출을 지원할 예정이다.</p><p>라자트 가우라브(Razat Gaurav) 키넥시스 최고경영자는 “허브는 엔터프라이즈 소프트웨어 분야에서 가장 중요한 변곡점에서 이사회 및 경영진과 함께 일하며 경력을 쌓아왔으며, 허브가 키넥시스에 합류하게 되어 매우 기쁘다”고 말했다. 가우라브 최고경영자는 예가 10년 넘게 키넥시스와 공급망 기술 부문을 추적해 왔다며 그의 자본 배분, 전략적 재무, 인수합병 및 글로벌 성장 관련 자문 전문성을 언급했다.</p><p>예는 “공급망 계획 시장은 AI에 의해 변혁을 겪고 있으며, 키넥시스는 이러한 변화를 주도할 수 있는 탁월하게 훌륭한 입지에 있다. 라자트 및 팀과 협력하여 이러한 기반 위에 더욱 발전시켜 나가고 고객과 주주 모두를 위해 지속적인 가치를 제공하기를 기대한다”고 말했다.</p><p>예는 25년 이상의 기업 재무 및 투자은행 경력을 보유하고 있다. 가장 최근까지 에버코어(Evercore)에서 선임 전무이사로 재직하며 소프트웨어 분야 중심의 기술 전략 자문 업무를 이끄는 데 참여했다. 이전에는 시티(Citi)에서 기술 투자은행 부문 글로벌 공동대표 겸 은행, 자본시장 및 자문 부문 부회장을 역임했으며, 뱅크오브아메리카 메릴린치(Bank of America Merrill Lynch)에서 고위 직책을 맡았다. 경력은 클리어리 고틀립 스틴 &amp; 해밀턴(Cleary Gottlieb Steen &amp; Hamilton LLP)에서 기업 및 증권 변호사로 시작했다.</p><p>키넥시스는 2026년 8월 5일 장 마감 후 2026년 2분기 재무 실적을 발표하고, 8월 6일 오전 8시 30분(미 동부 시간) 실적 콘퍼런스 콜을 개최한다.</p>', '에버코어·시티 등에서 25년 이상 기업 재무·투자은행 경력을 쌓은 허브 예가 2026년 7월 27일부로 키넥시스의 재무와 기업 전략을 총괄한다.', null, '2026-07-21T01:00:00.000Z'::timestamptz, array['키넥시스', '허브 예', '최고재무책임자', '공급망']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1038963'),
  ('people', 'AIT 월드와이드 로지스틱스, 최고디지털기술책임자에 저스틴 코슬린 영입', '<p>@@BYLINE@@&nbsp;공급망 솔루션 기업 AIT 월드와이드 로지스틱스(AIT Worldwide Logistics)는 소프트웨어 개발 임원 출신 저스틴 코슬린(Justin Kosslyn)을 최고디지털기술책임자(Chief Digital and Technology Officer)로 영입했다고 발표했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/07/1028147215_20260714112733_9815778047.jpg" alt="AIT 월드와이드 로지스틱스(AIT Worldwide Logistics) 최고디지털기술책임자(Chief Digital and Technology Officer) 저스틴 코슬린(Justin Kosslyn)"><p><em>▲ AIT 월드와이드 로지스틱스(AIT Worldwide Logistics) 최고디지털기술책임자(Chief Digital and Technology Officer) 저스틴 코슬린(Justin Kosslyn)</em></p><p>새로 신설된 이 직책에서 코슬린은 키스 톨런(Keith Tholan) 사장 겸 최고운영책임자(COO)에게 직접 보고하며, 회사 전반의 통합 디지털, 데이터, AI 및 고객 대면 시스템 발전을 위한 글로벌 기술 전략을 총괄한다. 글로벌 운송관리시스템(Transportation Management System, TMS)의 지속적인 고도화, 디지털 전환 추진, 전사적 AI 도입 등 기술 역량 강화 전략을 이끄는 데 주력할 예정이다.</p><p>코슬린은 디지털 제품 개발과 확장을 이끄는 기술 조직을 15년 이상 이끌어 왔다. 최근에는 구글(Google)에서 고위 리더십 직책을 맡아 Google Trends와 Search Console 등의 플랫폼을 총괄하며 뉴스 생태계 제품 관리를 이끌었다. 경력 초기에는 구글 직소(Google Jigsaw)에서 10년간 근무하며 사이버 공격 위협 완화 이니셔티브 등 디지털 및 정보 보안 강화 도구를 개발했다. 예일대학교(Yale University)에서 컴퓨터과학 학사 학위를 취득했으며, 미국 뉴욕시에 거주하고 있다.</p><p>톨런 사장은 “디지털 제품 개발과 기술 조직을 이끌어 온 그의 경험은 보다 긴밀하게 연결되고, 확장 가능하며, 고객 중심적인 기술 솔루션을 구축하는 과정에서 AIT가 이미 보유한 물류, 인프라, 사이버보안, 데이터 및 AI 분야의 깊은 전문성을 더욱 강화해 줄 것”이라고 말했다. 톨런 사장은 이어 “앞으로 기술은 AIT의 전략적 차별화 요소로 진화해 물류 서비스 제공 방식을 새롭게 정의하게 될 것”이라고 말했다.</p><p>본 무어(Vaughn Moore) AIT 회장 겸 최고경영자(CEO)는 “저스틴의 AIT 합류는 미래를 내다보는 전략을 추구해 온 우리 조직의 방향성을 잘 보여준다”고 말했다.</p><p>코슬린은 “AIT는 기술을 활용해 글로벌 물류 운영 방식을 개선하는 데 그치지 않고, 업계 전반의 새로운 기준을 제시할 수 있는 중요한 기회를 맞이하고 있다”며 “회사 전반의 팀들과 협력해 임직원과 고객이 최대의 효과를 얻을 수 있는 실용적이고 유연한 디지털 솔루션을 제공할 수 있기를 기대한다”라고 말했다.</p><p>AIT 월드와이드 로지스틱스는 시카고에 본사를 둔 국제물류 기업으로, 아시아, 유럽, 중동 및 북미 지역의 전 세계 170여 개 거점에서 해상, 항공, 육상 및 철도 물류 서비스와 통관, 창고 관리 등을 제공한다.</p>', '구글에서 Google Trends·Search Console 등을 총괄한 저스틴 코슬린이 신설 직책을 맡아 AIT의 글로벌 기술 전략을 이끈다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/07/1028147215_20260714112733_9815778047.jpg', '2026-07-14T03:00:00.000Z'::timestamptz, array['AIT 월드와이드 로지스틱스', '저스틴 코슬린', '포워딩', '디지털 전환']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1038553'),
  ('people', '브링, EMEA 수석 부사장 겸 총괄 매니저에 크리스 콘웨이 임명', '<p>@@BYLINE@@&nbsp;라스트마일 배송 기술 기업 브링(Bringg)이 크리스 콘웨이(Chris Conway)를 EMEA 지역 수석 부사장 겸 총괄 매니저로 임명했다고 발표했다. 콘웨이는 브링의 EMEA 지역 상업 전략, 고객 관계 및 시장 진출 운영을 이끈다.</p><p>콘웨이는 영국의 세 대형 식료품 소매업체에서 20년 이상의 전자상거래, 디지털 상거래 및 운영 혁신 경험을 보유하고 있다. 가장 최근에는 Co-op에서 퀵 커머스(Quick Commerce) 및 식품 운영 위원회 회원으로 재직하며 약 2000개 매장에서 배송하는 5억파운드 이상의 q-커머스 사업을 구축하고 확장했다. 독립 소매업체들이 q-커머스 기술을 이용할 수 있도록 하는 빠른 배송 앱 페키시(Peckish)를 설립하기도 했다.</p><p>아스다(Asda)에서는 온라인 식료품 사업을 10억파운드 이상의 매출과 20% 시장 점유율로 이끌었고, 모리슨스(Morrisons)에서는 온라인 상업 팀을 이끌었다. 옥스퍼드 세이드 비즈니스 스쿨(Oxford Saïd Business School)에서 AI 인증서를 취득했다.</p><p>가이 블로흐(Guy Bloch) 브링 CEO는 “EMEA 소매업체들은 점점 더 복잡한 배송 결정을 내리고 있으며, 브링은 이러한 결정을 올바르게 내릴 수 있도록 AI 역량을 구축하고 있다”고 말했다.</p><p>새 역할에서 콘웨이는 유럽 소매업체 및 물류 리더와의 경영진 참여를 주도하고, 관계를 체계적인 시범 사업으로 전환하는 업무를 맡는다. 콘웨이는 “저는 직접 겪어봤기 때문에 무엇이 필요한지 안다. 또한 브링이 고객의 문제를 깊이 이해하고 자동화와 AI를 활용해 라스트마일 역량을 향상시키는 방식을 직접 보았다”고 말했다.</p>', '영국 Co-op·아스다·모리슨스에서 20년 이상 전자상거래와 운영 혁신을 맡아온 크리스 콘웨이가 브링의 EMEA 상업 전략과 고객 관계를 이끈다.', null, '2026-04-22T04:35:00.000Z'::timestamptz, array['브링', '크리스 콘웨이', '라스트마일', '인사']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1032891'),
  ('people', '원양어선 김현무 선장, 선상 생활 담은 에세이 출간', '<p>@@BYLINE@@&nbsp;tvN ‘유 퀴즈 온 더 블록’ 140회에 원양어선 항해사로 출연했던 김현무 선장이 선상 생활을 기록한 에세이 ‘어서 와, 원양어선은 처음이지?’(비전비엔피 애플북스)를 출간했다.</p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/01/2944120219_20260121173214_4287027079.jpg" alt="‘어서 와, 원양어선은 처음이지?’ 표지"><p><em>▲ ‘어서 와, 원양어선은 처음이지?’ 표지</em></p><img src="https://file.newswire.co.kr/data/datafile2/data/2026/01/2944120219_20260121174609_9246359863.jpg" alt="저자 김현무 선장"><p><em>▲ 저자 김현무 선장</em></p><p>김 선장은 방송에서 참치 떼를 쫓으며 투망일지를 써나가는 원양어선 항해사의 삶을 소개하고, 코로나로 인한 장기 승선, 20대에 받았던 억대 연봉과 고된 노동 강도 등을 이야기했다. 앞으로의 꿈을 묻는 질문에 “열심히 노력해서 선장이 되는 것”이라고 답했던 그는 2025년 서른 살에 선장이 되어 원양어선을 지휘하고 있다.</p><p>김 선장은 구독자 20만 명을 넘어선 유튜브 채널 ‘RAMP’를 운영하며 원양어선 선상 생활을 소개해 왔다. 2018년부터 유튜브를 시작했다는 그는 “영상에 호응해주는 사람들과 소통하면서 비로소 외딴 바다 한가운데 있다는 고립감에서 벗어날 수 있었다”고 말했다.</p><p>책에는 해양 전문학교로 진로를 정한 배경부터 삼등항해사와 이등항해사 시절을 거쳐 일등항해사가 되기까지의 과정이 연대순으로 담겼다. 바다수영, 만선주, 태평양에서의 참치 조업 등 원양어선 생활의 여러 장면도 소개된다.</p><p>김 선장은 “의외로 원양어선 생활에 대한 궁금증을 댓글로 남기는 분들이 많았는데, 바쁜 승선 생활에 일일이 다 답할 수가 없었다. 이 책이 그분들에게 보내는 길고 상세한 댓글이 됐으면 좋겠다”며 책을 쓰게 된 배경을 설명했다. 책은 1월 정식 출간됐다.</p>', 'tvN ‘유 퀴즈 온 더 블록’에 항해사로 출연했던 김현무 선장이 원양어선 생활을 기록한 에세이 ‘어서 와, 원양어선은 처음이지?’를 펴냈다.', 'https://file.newswire.co.kr/data/datafile2/data/2026/01/2944120219_20260121173214_4287027079.jpg', '2026-01-22T03:00:00.000Z'::timestamptz, array['김현무', '원양어선', '선장', '에세이']::text[], 'https://www.newswire.co.kr/newsRead.php?no=1027333'),
  ('opinion', '장기계약과 지선망, HMM이 그리는 두 개의 축', '<p>@@BYLINE@@&nbsp;해운 시황은 늘 출렁인다. 운임이 오를 때 배를 늘리고 내릴 때 버티는 방식만으로는 국적선사가 체력을 꾸준히 유지하기 어렵다. 결국 질문은 무엇으로 변동성을 견딜 것인가로 모인다. 최근 HMM이 잇따라 내놓은 발표는 이 질문에 대한 하나의 답안을 보여준다. 벌크 부문에서는 장기운송계약으로 수익의 바닥을 다지고, 컨테이너 부문에서는 지선망을 촘촘히 엮어 네트워크의 폭을 넓히는 두 갈래 전략이다.</p><p>HMM은 이달 8일 브라질 최대 광산업체 발레(Vale)와 총 4.7조원 규모의 장기운송계약을 체결했다고 밝혔다. 지난해 5월과 9월 두 차례에 걸쳐 맺은 10년 장기운송계약(총액 약 1조 665억원 규모)에 이은 세 번째 대규모 수주이며, 계약 기간은 2030년부터 척당 25년간이다. 이 계약에 투입될 뉴캐슬막스급 벌크선 8척은 메탄올·에탄올·중유를 모두 사용할 수 있는 3중 연료 추진 엔진을 달고, 향후 LNG나 암모니아 추진선으로 개조할 수 있는 ‘LNG·암모니아 레디(Ready)형’으로 제작된다.</p><p>25년이라는 계약 기간은 단기 운임 흐름과 일정한 거리를 두겠다는 의미로 읽힌다. 동시에 선박이 운항하는 긴 기간 동안 연료 규제가 어떻게 바뀔지 알 수 없다는 숙제도 함께 떠안는다. 3중 연료 엔진과 개조 가능 설계, 풍력보조추진장치 ‘로터 세일’ 탑재는 그 불확실성에 미리 대비하려는 선택으로 볼 수 있다. 장기계약의 안정성은 선박이 수명 내내 규제와 화주의 요구를 충족할 수 있을 때 비로소 완성되기 때문이다.</p><p>컨테이너 부문의 변화는 더 눈에 띈다. HMM은 7월 7일 스페인 알헤시라스와 서아프리카를 잇는 ‘MA2’ 서비스의 첫 항차를 시작했다. 최원혁 사장 부임 이후 수립한 ‘허브 앤 스포크’ 전략의 첫 노선으로, 피더선 5척이 탕헤르·다카르·테마·레키·아비장을 왕복 35일 일정으로 오간다. 이어 9월부터는 인도 나바셰바·문드라와 탄자니아 다르에스살람, 케냐 몸바사를 연결하는 ‘GIA’ 서비스를 개설해 2800TEU급 5척을 투입하고, COSCO SHIPPING과 PIL, 인터아시아라인 등과 함께 4개사가 공동 운항하기로 했다.</p><p>이 지선망을 받치는 것은 거점과 선대다. 알헤시라스에는 HMM이 2017년 지분 100%를 인수한 TTIA 터미널이 있고, 1단계 확장 개발을 통해 2028년까지 연간 처리량을 210만 TEU로 늘릴 계획이다. 피더선은 신조 발주와 리세일, 중고선 매입을 합쳐 총 27척을 확보했고, 최근 공시를 통해 컨테이너 선대를 2030년까지 147만TEU, 166척으로 확대하겠다는 계획도 내놨다. 2007년부터 특수화물 전담 조직을 운영하며 고부가가치 화물을 공략해 온 이력도 같은 흐름 위에 있다.</p><p>주목할 대목은 선대의 크기보다 연결의 방식이다. HMM은 MA2가 혼잡도가 높은 서아프리카 항만 구간을 분리 운영함으로써 초대형선의 운항 정시성을 높일 수 있다고 설명한다. 화주들이 안정적인 스케줄과 다양한 목적지 연결성을 중시하는 흐름 속에서, 원양 간선과 지역 지선을 엮는 방식은 규모 경쟁과는 결이 다른 서비스 경쟁을 예고한다.</p><p>과제도 분명하다. 지선망의 성과는 기항지의 항만 인프라와 내륙 물류 여건, 공동 운항 파트너와의 협업 수준에 크게 좌우된다. 장기운송계약 역시 오랜 기간에 걸쳐 이행 능력을 꾸준히 증명해야 하는 약속이다. 업계와 정책 당국은 국적선사의 해외 터미널 투자와 친환경 선박 확보가 일회성 성과에 그치지 않도록 선박 금융과 친환경 연료 공급 인프라 등 뒷받침 체계를 함께 점검할 필요가 있다.</p><p>해운 경쟁력의 기준은 얼마나 많은 배를 가졌느냐에서 화물을 얼마나 안정적으로 연결하느냐로 옮겨가고 있다. 장기계약과 지선망이라는 두 축이 실제 화주의 신뢰로 이어질지, 국적선사 전략의 시험대는 이제부터다.</p>', '벌크 장기운송계약과 허브 앤 스포크 지선망 확대는 국적선사가 시황 변동성에 대응하는 방식에 대한 하나의 답안을 보여준다.', null, '2026-09-21T07:00:00+09:00'::timestamptz, array['HMM', '장기운송계약', '허브 앤 스포크', '컨테이너 지선망', '국적선사']::text[], null),
  ('opinion', '선박 연료 전환, 기술 경쟁 너머의 과제', '<p>@@BYLINE@@&nbsp;선박 탈탄소 논의에서 가장 자주 나오는 질문은 ‘어떤 연료가 이길 것인가’다. 그러나 최근 국내외에서 보도된 사례들을 나란히 놓고 보면 질문을 바꿔야 할 때가 된 듯하다. 암모니아, 배터리, LNG 이중연료, 메탄올까지 후보는 이미 여럿이고, 각각이 서로 다른 선종과 항로에서 실제 시험대에 오르고 있다. 문제는 연료의 선택보다 그것을 현장에서 안전하고 예측 가능하게 운용할 체계를 누가 먼저 갖추느냐다.</p><p>H2SITE는 노르웨이 정부 기관 에노바로부터 340만유로를 확보해 선상에서 암모니아를 고순도 수소로 변환하는 ‘하이드라노르드 파워’ 프로젝트를 추진한다. 하루 최대 1톤의 수소를 생산해 해양 연료전지에 공급하고 700kW의 순전력을 내는 시스템으로, 개발·통합은 2027년, 시운전은 2028년 초로 예정돼 있다. 안드레스 갈나레스 H2SITE 최고경영자는 “하이드라노르드 파워는 암모니아 발전을 성공적인 소규모 배치에서 상업적으로 관련 있는 전력 범위로 끌어올린다”고 말했다.</p><p>배터리 쪽에서는 남호주에서 세계 최초의 배터리 구동 자가하역식 벌크선 ‘MV Yampu’가 운항을 시작했다. 정박 중 충전한 배터리로 전체 운항 시간의 약 40%를 운항하며, 기존 선박 대비 연간 디젤 사용량을 50만 리터 이상 줄일 것으로 예상된다. 채석장과 시멘트 공장을 오가는 반복적인 연안 항로라는 조건이 배터리 추진의 장점을 살린 사례로 볼 수 있다.</p><p>대형 컨테이너선 시장에서는 이중연료가 현실적인 해법으로 쓰이고 있다. STX엔진은 머스크의 1만9000TEU급 컨테이너선 14척(확정 8척, 옵션 6척)에 탑재될 엔진 계약을 맺으면서, 선박 1척당 이중연료 엔진 2대와 디젤 엔진 2대를 교차 공급하는 방식을 택했다. HMM이 발레와의 장기운송계약에 투입할 벌크선 8척에 메탄올·에탄올·중유를 모두 쓸 수 있는 3중 연료 엔진을 달고 LNG·암모니아 레디형으로 짓기로 한 것도 같은 맥락에서 읽힌다. 하나의 연료에 모든 것을 걸기보다 전환의 여지를 남겨두는 선택이다.</p><p>기술만큼 중요한 것은 운영 규칙이다. KRISO는 국내 최초로 STS 방식의 LNG 벙커링 동시작업 절차서 2종을 개발해 한국LNG벙커링산업협회 표준으로 채택시켰다. 동시작업을 하면 별도 벙커링 때보다 약 1~3일 일정을 줄일 수 있지만, 국내에는 이를 뒷받침할 표준 지침이나 기준이 없어 산업 활성화가 더뎠다는 것이 KRISO의 설명이다. 새 연료가 들어와도 항만에서 공급하고 다루는 절차가 정비되지 않으면 선박은 그 항만을 찾기 어렵다.</p><p>장기 과제로 거론되는 SMR 선박도 마찬가지다. 서울대 에너지 이니셔티브 연구단이 마련한 세미나는 SMR 선박의 상용화를 위해 기술 개발뿐 아니라 안전성 확보, 제도 정비, 국제 규제 대응 등 다양한 과제의 해결이 필요하다는 문제의식에서 출발했다. 연료가 새로울수록 기술보다 제도와 사회적 수용성이 더 긴 시간을 요구한다는 점을 보여준다.</p><p>이 흐름에서 업계와 정책이 함께 고민해야 할 지점은 분명하다. 첫째, 연료별 실증을 실제 운항 조건에 가깝게 진행할 수 있는 시험 기반이 필요하다. 둘째, 벙커링과 하역, 안전관리 절차를 연료별로 표준화해 항만 현장의 예측 가능성을 높여야 한다. 셋째, 새 연료를 다룰 선원과 항만 인력의 교육 체계도 연료 전환 속도에 맞춰 준비돼야 한다.</p><p>친환경 연료 전환은 한 번의 결정으로 끝나는 일이 아니라 긴 시간에 걸친 단계적 이행이다. 어느 연료가 최종 승자가 될지 단정하기보다, 어떤 연료가 오더라도 받아들일 수 있는 항만과 제도, 인력을 갖추는 것이 지금 한국 해운·조선 생태계가 준비해야 할 일이다.</p>', '암모니아·배터리·이중연료 등 해법은 다양해졌지만, 상용화를 가르는 것은 실증과 표준, 그리고 공급 인프라다.', null, '2026-09-25T07:00:00+09:00'::timestamptz, array['친환경 연료', '암모니아', '배터리 선박', 'LNG 벙커링', '탈탄소']::text[], null),
  ('opinion', '통합 대한항공, 화물 경쟁력도 함께 점검할 때', '<p>@@BYLINE@@&nbsp;오는 12월 17일 ‘통합 대한항공’이 출범한다. 2020년 11월 17일 신주인수계약 체결 이후 5년 6개월여 만인 지난 5월 양사 이사회가 합병 계약을 승인했고, 이제 고객이 체감하는 절차가 본격화되고 있다. 다만 통합을 둘러싼 관심은 주로 마일리지와 편명, 라운지 같은 여객 서비스에 쏠려 있다. 항공물류를 다루는 입장에서 묻고 싶은 것은 통합 이후 화물 경쟁력을 떠받칠 기반이 충분히 준비되고 있느냐는 것이다.</p><p>대한항공은 11월 2일부터 12월 3일까지 아시아나항공 편명을 대한항공 편명으로 바꾸는 항공편명 변경(REAC)을 실시하고, 예약과 항공권 정보를 순차적으로 이관한다고 밝혔다. 합병 계약 이후에는 기존 운항증명을 유지하면서 아시아나항공의 항공기와 안전 운항 시스템을 통합하기 위한 운영기준 변경 인가 등 제반 절차를 진행한다는 계획도 밝힌 바 있다. 통합의 첫 관문이 안전과 고객 혼선 최소화라는 점에서 순서는 타당해 보인다.</p><p>기단 측면에서는 큰 결정이 이미 내려졌다. 대한항공은 이달 15일 보잉 항공기 103대 도입과 예비 엔진 구매 계약의 최종 체결을 기념하는 행사를 열었다. 362억달러 상당의 항공기에는 777-9 20대, 787-10 25대, 737-10 50대와 함께 777-8F 화물기 8대가 포함됐다. GE에어로스페이스·CFM과는 86억달러 가량의 예비 엔진 21대 구매 및 15년간 항공기 28대에 대한 엔진 정비서비스 계약도 맺었다. 회사는 통합에 따른 중장기 성장과 팬데믹 이후 이어지는 글로벌 항공기 공급 지연에 선제적으로 대응하기 위한 투자라고 설명했다.</p><p>정비 인프라도 화물 경쟁력과 무관하지 않다. 대한항공은 인천국제공항공사와 1760억원을 들여 첨단복합항공단지에 신규 정비격납고를 짓기로 했다. 통합 대형 항공사와 저비용 항공사 출범 이후 300여 대 항공기의 정비를 뒷받침하기 위한 시설로, 2027년 착공해 2029년 말 가동이 목표다. 엔진 테스트 셀과 신 엔진 정비 공장 등도 확장하거나 새로 짓는 중이다. 화물기는 정시성이 곧 신뢰인 만큼 정비 역량은 화주가 체감하는 서비스 품질과 직결된다.</p><p>화물칸 안쪽의 공급망도 눈여겨볼 대목이다. 국내 항공부품 기업 GTA Aerospace는 화물실에서 화물 컨테이너(ULD)를 이동시키는 핵심 부품인 PDU Roller의 성능시험을 마쳤다고 밝혔다. 회사는 국내 항공사에서 쓰이는 다수의 화물 시스템 부품이 해외 제조사에 의존하고 있어 조달 비용 증가와 공급망 불안정 문제를 안고 있다고 짚었다. 기단 확대가 화물 시스템 부품의 안정적 조달과 함께 가야 한다는 점을 일깨우는 사례다.</p><p>허브 경쟁력은 결국 연결성에서 판가름 난다. OAG의 ‘Megahubs 2026’에서 아시아태평양 지역은 글로벌 상위 20개 공항 가운데 8곳을 차지했고, 인천국제공항은 LCC 순위 2위에 오르며 198개 목적지와 연결된 것으로 나타났다. 대한항공이 통합 효과로 내세운 인천국제공항 허브 기능 강화가 여객을 넘어 화물 환적 경쟁력으로 이어지려면, 중복 노선 재배치 과정에서 화물 수요를 함께 고려하는 설계가 필요하다.</p><p>조원태 한진그룹 회장은 최종 계약 기념 행사에서 “보잉이 대한항공의 날개라면 GE에어로스페이스는 우리 항공기 기단의 심장과 같은 역할을 해왔다”고 말했다. 비유를 빌리자면 화물 사업에는 날개와 심장 외에 혈관이 필요하다. 화주와 포워더, 지상조업, 세관으로 이어지는 물류 흐름이다. 통합 과정에서 화물 운송 체계나 처리 절차에 변화가 생긴다면 그 내용을 화주와 물류업계에 충분히 앞서 안내하는 노력이 여객 못지않게 중요하다.</p><p>통합 항공사의 성패는 출범일 하루로 결정되지 않는다. 항공물류 업계와 정책 당국도 인천 허브의 화물 처리 역량, 정비와 부품 공급망, 국산 부품 인증 체계를 함께 살피며 통합 이후의 경쟁력을 점검해 나가야 할 것이다.</p>', '여객 통합 절차가 속도를 내는 지금, 화물기단과 정비, 부품 공급망 등 항공물류의 기반도 같은 무게로 살펴야 한다.', null, '2026-09-23T07:00:00+09:00'::timestamptz, array['대한항공', '아시아나항공', '통합 항공사', '항공화물', '인천공항']::text[], null),
  ('opinion', '물류 자동화, 설비 경쟁에서 운영 경쟁으로', '<p>@@BYLINE@@&nbsp;물류 자동화를 이야기할 때 우리는 흔히 로봇의 모습부터 떠올린다. 빠르게 움직이는 AMR, 사람처럼 물건을 집는 휴머노이드가 전시장의 주인공이 된다. 그러나 최근 국내 물류 자동화 현장의 소식을 들여다보면, 경쟁의 무게중심은 장비 그 자체보다 여러 설비를 하나의 흐름으로 묶어 운영하는 역량으로 옮겨가고 있다.</p><p>현대무벡스는 지난달 30일 금호타이어와 720억원 규모의 물류 자동화 시스템 공급 계약을 맺었다. 전남 함평 빛그린국가산업단지에 들어서는 신공장은 약 50만㎡ 부지에 연간 530만 본의 생산능력을 갖출 예정이며, 현대무벡스는 2028년 10월까지 원자재부터 반제품·완제품까지 제조공정 전반의 물류를 연계·제어하는 통합 자동화 시스템을 구현한다. 자동입출고시스템과 AGV·AMR·RGV, 컨베이어 같은 설비에 WMS·WCS 등 운영·제어 소프트웨어를 연계하고, AI 기반 물동량 예측과 최적 경로 제어를 접목한다는 계획이다.</p><p>눈여겨볼 부분은 설계부터 제작·설치, 유지보수까지 전 과정을 ‘원스톱’으로 수행한다는 점이다. 현대무벡스는 30여 년간 축적한 타이어 특화 엔지니어링 역량을 내세웠고, 한국타이어앤테크놀로지 미국 테네시 공장 증설 프로젝트에서도 약 1000억원 규모의 스마트 물류 구축 사업을 수행하고 있다. 앞서 4월 북미 최대 물류 전시회 ‘MODEX 2026’에서는 미국 전시 현장과 청라R&amp;D센터를 실시간 연결한 3D 디지털 트윈을 선보였다. 특정 산업의 공정을 깊이 이해하는 엔지니어링과 이를 가상 공간에서 미리 검증하는 기술이 결합하는 모습이다.</p><p>휴머노이드 로봇도 실증 단계에 들어섰다. LG CNS는 LX판토스와 업무협약을 맺고 메가와이즈 청라 물류센터에 휴머노이드 로봇과 셔틀 로봇을 연계한 자동화 시스템을 구축하기로 했다. 셔틀 로봇이 출고 예정 물품을 반출하면 휴머노이드가 이를 받아 자동 분류 설비나 로봇에 적재하는 방식으로, 로봇 학습은 LX판토스의 물류 현장 데이터를 기반으로 한다. 박상균 LG CNS 통신/유통/서비스사업부장은 “이번 업무협약은 다양한 로봇과 학습·운영 플랫폼을 활용한 물류 현장 적용 가능성 실증 프로젝트”라고 설명했다.</p><p>항만도 예외가 아니다. 부산신항의 동원글로벌터미널부산(DGT)은 컨테이너 하역부터 이송, 적치까지 전 과정을 100% 무인 자동화로 운영하며 유인 항만 대비 생산성을 20% 이상 높였다고 밝혔다. 지난달 킨텍스에서 열린 ‘SCM FAIR 2026’에도 AGV·AMR 기반 물류 자동화 로봇과 AI 물류 솔루션이 대거 등장했고, 같은 기간 열린 특화망 기술 산업전과 합쳐 3일간 3881명의 참관객이 전시장을 찾았다.</p><p>이 사례들이 공통으로 가리키는 것은 자동화의 성패가 데이터와 통합 운영에 달려 있다는 점이다. 로봇은 현장 데이터로 학습해야 하고, 설비는 창고제어 소프트웨어와 연결돼야 하며, 운영 효율은 디지털 트윈으로 미리 검증된다. 설비를 들여놓는 것만으로는 충분하지 않고, 현장의 작업 흐름과 예외 상황을 이해하는 운영 역량이 뒤따라야 자동화가 제 성과를 낸다.</p><p>그렇다면 업계와 정책은 무엇을 준비해야 할까. 우선 대형 프로젝트를 중심으로 쌓이는 자동화 경험이 중소 물류센터와 산업단지로 확산될 수 있도록 설비 간 연동 표준과 실증 공간을 공유하는 방안을 고민할 필요가 있다. 또 반복 업무를 로봇이 맡게 되는 만큼 현장 인력이 설비 운영과 예외 처리, 유지보수를 담당할 수 있도록 직무 전환 교육을 함께 설계해야 한다. 사람과 로봇이 함께 일하는 공간의 안전 기준을 정비하는 일도 서둘러야 할 과제다.</p><p>물류 자동화는 이제 ‘도입할 것인가’가 아니라 ‘어떻게 운영할 것인가’의 문제가 됐다. 로봇의 성능 경쟁을 넘어 현장을 아는 데이터와 사람이 함께 움직이는 체계를 만드는 쪽이 다음 단계의 경쟁력을 쥐게 될 것이다.</p>', '타이어 공장 스마트 물류 수주와 휴머노이드 실증은 자동화의 승부처가 장비 자체보다 데이터와 통합 운영에 있음을 보여준다.', null, '2026-10-02T07:00:00+09:00'::timestamptz, array['물류 자동화', '스마트 물류', '휴머노이드', '물류 로봇', '디지털 트윈']::text[], null),
  ('opinion', '소액 면세 폐지 이후, K-이커머스 물류의 숙제', '<p>@@BYLINE@@&nbsp;해외 소비자가 한국 상품을 클릭 한 번으로 사는 시대지만, 그 상품이 국경을 넘는 과정은 오히려 복잡해지고 있다. 주요 시장이 소액 수입품에 대한 면세 제도를 손보면서, 그간 저렴한 배송비와 간편한 통관에 기대어 성장해 온 크로스보더 이커머스는 물류 방식 전반을 다시 점검해야 하는 국면을 맞았다.</p><p>유럽연합(EU)은 2026년 7월 1일부로 150유로 미만 소액 수입품에 대한 면세 혜택을 폐지하고, 기존 부가가치세 납부 의무와 더불어 HS 코드당 3유로의 고정 수수료를 새로 도입했다. 미국의 800달러 소액 면세 폐지와 미국행 소형화물 통관·배송 정책 변화도 해외 K-POP 공동구매 운영자들의 국제 배송비와 통관 부담을 키운 요인으로 꼽힌다. 판매자 입장에서는 가격표에 드러나지 않던 비용과 절차가 새로 생긴 셈이다.</p><p>물류업계의 대응도 빨라지고 있다. Asendia는 인천국제공항 인근 물류센터와 글로벌 네트워크를 바탕으로 한국발 소포를 월 최대 300만 건까지 처리할 수 있는 역량을 갖췄다며, 판매 시점에 관세와 세금을 미리 처리하는 DDP 배송 모델을 내세웠다. 유럽 고객이 상품을 받을 때 예상치 못한 추가 비용을 내거나 통관 지연을 겪지 않도록 하겠다는 것이다. 신희정 Asendia 한국 비즈니스 개발 매니저는 “해외 진출을 모색하는 기업들에게 수요 확보는 더 이상 주요 장벽이 아니다”라고 말했다.</p><p>국내 기업들의 시도도 다양하다. 콜트랜스는 해외 K-POP 공동구매 운영자를 위한 ‘케이픽’을 내놓고 최대 6개월 무료 보관과 합배송·분리배송을 지원하기로 했다. 관세청 집계로 2025년 K-POP 음반 수출액이 3억170만달러로 역대 최고치를 기록한 만큼, 팬덤 물량을 안정적으로 처리하려는 수요가 뒤따른 것이다. 비브로는 김포에 B2B 중심의 제2물류센터를 열어 K-뷰티 브랜드의 해외 유통 채널별 검수·라벨링·출고 준비를 맡기로 했다.</p><p>정부 지원도 이어진다. 콜로세움코퍼레이션이 수행기관으로 선정된 ‘2026 온라인수출 중소기업 물류 지원사업’은 해외 물류비의 최대 70%, 최대 3000만원을 지원한다. 보건복지부는 관계 공공기관과 함께 총 20개, 약 500억 원 규모의 사업으로 400개 이상의 화장품 기업의 수출 물류를 지원하기로 했다. 중소 판매자의 비용 부담을 덜어준다는 점에서 의미 있는 조치들이다.</p><p>다만 제도 변화의 핵심은 비용만이 아니다. HS 코드 분류와 세금 사전 정산, 국가별 배송·반품 기준 대응처럼 정보와 절차의 문제가 함께 커지고 있다. Asendia가 강조한 것도 결국 복잡성을 관리하는 역량이고, 콜트랜스가 내세운 것도 ‘예측 가능한 비용’과 ‘예측 가능한 배송’이다. 해외 소비자가 상품을 받는 순간의 경험이 브랜드 신뢰를 좌우하는 이상, 컴플라이언스는 뒷단의 행정이 아니라 판매 경쟁력의 일부가 됐다.</p><p>지원 정책도 이 변화를 반영할 필요가 있다. 물류비 보조에 더해 주요 시장의 통관 규정 변화를 신속히 알리고, 품목 분류와 세금 처리 실무를 익힐 수 있는 교육과 상담 창구를 넓히는 방안을 검토할 만하다. 여러 부처와 기관에 흩어진 수출 물류 지원사업을 판매자가 한눈에 비교하고 선택할 수 있도록 접근성을 높이는 일도 필요하다. 업계 역시 운임 경쟁을 넘어 통관과 반품까지 책임지는 서비스 품질로 경쟁해야 한다.</p><p>한류가 만든 해외 수요는 분명하다. 그 수요를 놓치지 않으려면 국경 앞에서 멈추지 않는 물류, 규정이 바뀌어도 흔들리지 않는 물류가 필요하다. 소액 면세 폐지는 부담이기도 하지만, 한국 이커머스 물류가 한 단계 성숙해지는 계기가 될 수도 있다.</p>', 'EU와 미국의 소액 수입품 제도 변화는 크로스보더 이커머스 물류의 경쟁력이 운임보다 컴플라이언스와 예측 가능성에 있음을 일깨운다.', null, '2026-09-30T07:00:00+09:00'::timestamptz, array['크로스보더 이커머스', '역직구', '소액 면세', 'EU 관세', 'K-뷰티 물류']::text[], null),
  ('opinion', '초크포인트 리스크, ‘통항 재개’만 봐선 안 된다', '<p>@@BYLINE@@&nbsp;해협 하나가 막히면 세계 공급망이 흔들린다는 사실은 이제 새삼스럽지 않다. 그러나 막혔던 해협이 다시 열렸다는 소식이 곧 정상화를 뜻하는지는 다른 문제다. 최근 호르무즈 해협을 둘러싼 상황은 해운·물류 업계에 사건 자체보다 그 영향의 크기와 지속 기간을 어떻게 판단할 것인가라는 질문을 던지고 있다.</p><p>해양 물류 데이터 기업 씨벤티지는 지난달 전 세계 9개 주요 초크포인트의 위험도와 통항 변화를 한 화면에서 비교하는 ‘초크포인트 모니터’를 내놨다. 선박 통항량과 지정학적 상황, 유가, 금융 스트레스 등을 종합한 위험 지수와 함께 최근 24시간 통항량, 평시 대비 증감률, 30일·60일·90일 기준 통항 추이를 제공한다. 씨벤티지에 따르면 호르무즈 해협은 9개 초크포인트 가운데 가장 높은 위험 수준을 보였고, 8월 24일 기준 통항량도 평시보다 80% 이상 낮았다.</p><p>씨벤티지는 이란의 선박별 통항 통제가 이어지면서 통항 자체가 일부 재개됐더라도 항로 정상화를 판단하기 어렵다고 짚었다. 씨벤티지가 인용한 Reuters 보도에 따르면 중국 국영 선사 COSCO Shipping Energy Transportation과 China Merchants Energy Shipping은 7월 말 이후 푸자이라와 오만 인근에서 STS 방식으로 원유를 인수하는 등 페르시아만 외부를 활용하는 운송 전략을 확대하고 있다. 위험이 길어지면 시장 참여자들은 운송 방식 자체를 바꾼다는 뜻이다.</p><p>비용 측면의 신호도 분명하다. 프로스트 앤드 설리번은 중동 지역 분쟁과 주요 해상 무역로 혼란으로 일부 주요 항로의 운임이 기존 대비 2~5배까지 올랐고, 전쟁 위험 보험료도 선박 가치의 0.15% 수준에서 최대 10%까지 높아졌다고 분석했다. 그러면서 조달 전략 최적화, 분산형 생산 네트워크 구축, 공급업체 생태계와 지역 파트너십 강화, 디지털 기반 공급망 가시성 확보를 핵심 전략으로 제시했다.</p><p>문제는 이런 정보와 대응 수단이 기업 규모에 따라 고르게 닿지 않는다는 점이다. 지난 4월 주안부평 스마트 물류플랫폼 물류협의회에서 한국해양수산개발원 이성우 본부장은 ‘호르무즈해협 봉쇄와 물류 공급망 리스크 확대에 따른 중소 제조기업 대응방안’을 주제로 특강을 하며, 국가와 지자체의 노력과 함께 많은 기업의 병렬적인 움직임이 필요하다고 제시했다. 전담 조직과 다양한 계약 수단을 갖춘 대형 화주와 달리, 중소 제조기업은 상대적으로 정보와 협상력이 부족할 수밖에 없다.</p><p>삼성SDS가 올해 첼로스퀘어 콘퍼런스에서 제시한 ‘총비용(True Cost)’ 개념은 이 지점에서 참고할 만하다. 운송비와 관세 같은 전통적 비용뿐 아니라 탄소 배출, 공급망 리스크, 운송 중 화물의 기회비용까지 반영해 의사결정을 내려야 한다는 것이다. 초크포인트 리스크는 운임표에 바로 드러나지 않는 비용의 대표적인 사례다.</p><p>업계와 정책 당국이 함께 고민할 과제는 세 가지로 정리할 수 있다. 첫째, 해협 통항 여부라는 이분법을 넘어 위험도와 통항량 변화를 꾸준히 추적하는 모니터링을 일상화해야 한다. 둘째, 대체 항로와 운송 방식, 재고 운영을 미리 시나리오로 준비해 두어야 한다. 셋째, 중소 화주가 리스크 정보에 쉽게 접근하고 운임·보험 조건 변화에 대응할 수 있도록 공공 차원의 정보 공유와 상담 지원을 강화할 필요가 있다.</p><p>초크포인트 리스크는 언제든 다른 해협에서 다른 모습으로 되풀이될 수 있다. 위기 때마다 뉴스 한 줄에 일희일비하기보다, 데이터로 변화를 읽고 미리 대안을 준비하는 습관이 공급망의 체력을 결정할 것이다.</p>', '호르무즈 해협을 둘러싼 불확실성은 통항 여부보다 위험의 변화를 지속적으로 읽어내는 공급망 관리 역량을 요구한다.', null, '2026-09-20T07:00:00+09:00'::timestamptz, array['초크포인트', '호르무즈 해협', '공급망 리스크', '해상 운임', '중소 화주']::text[], null),
  ('opinion', 'K-함정 수출, 완제품 인도에서 현지 협력으로', '<p>@@BYLINE@@&nbsp;한국 조선업의 경쟁력을 이야기할 때 상선 수주 실적이 먼저 거론되곤 한다. 하지만 최근 들려온 소식들은 함정과 방산, 해외 산업 협력이라는 또 다른 축이 빠르게 커지고 있음을 보여준다. 동시에 그 협력의 방식이 ‘국내에서 만들어 넘겨주는’ 형태에서 ‘현지와 함께 만드는’ 형태로 바뀌고 있다는 점에서 짚어볼 대목이 많다.</p><p>지난달 30일 HD현대중공업 울산조선소에서는 8200톤급 차세대 이지스구축함 3번함 ‘대호김종서함’이 진수됐다. 내년 12월 전력화가 이뤄지면 해군은 총 6척의 이지스구축함을 보유하게 되며, HD현대중공업은 이 가운데 5척을 건조하게 된다. 국내 함정 건조 역량이 해외 협력의 출발점이라는 사실을 다시 확인시킨 장면이다.</p><p>해외로 눈을 돌리면 변화가 더 뚜렷하다. HD현대중공업은 페루 시마(SIMA)조선소에서 신형 상륙지원함 1번함 ‘침보테함’을 진수했다. 2024년 4월 페루 해군으로부터 수주한 4척 가운데 상륙지원함 2척을 현지에서 공동 건조하는 사업으로, HD현대중공업이 설계와 기술지원을 맡고 시마조선소가 블록 생산과 조립, 의장, 시험·시운전에 참여했다. 이 사업은 함정 수출의 개념을 ‘국내 건조 후 완제품 인도’에서 ‘기술협력을 통한 현지 공동생산’으로 바꾼 사례로 평가받는다. 케이코 후지모리 페루 대통령은 “우리는 단순히 함정 한 척을 건조하는 것이 아니라 미래를 위한 역량을 구축하고 있다”고 말했다.</p><p>필리핀과의 협력도 현지 산업으로 범위를 넓히고 있다. 정기선 HD현대 회장은 지난달 7일 길베르토 테오도로 주니어 필리핀 국방장관과 만나 필리핀 해군 현대화와 현지 조선산업 경쟁력 강화까지 협력 범위를 확대하는 방안을 논의했다. HD현대는 2016년 필리핀 해군의 첫 호위함 계약 이후 지금까지 12척의 함정을 수주해 6척을 인도했고, 지난해 가동한 수빅의 HD현대필리핀에서 건조한 첫 선박을 최근 진수했다.</p><p>한·미 조선 협력도 기술 개발 단계로 구체화되고 있다. 울산의 쓰리디팩토리는 산업통상부와 한국산업기술기획평가원이 지원하는 한·미 국제공동 R&amp;D 과제 ‘금속 적층제조 특화설계 기술 기반 5m급 선박 핵심 기자재 제작 기술개발 및 검증’의 킥오프 회의를 열었다. 대형 선박용 프로펠러를 와이어 아크 금속 적층제조로 만드는 기술을 개발해 ‘마스가(MASGA)’ 공급망과 MRO 시장에 대응하겠다는 구상이다. KRISO와 해군, 국방과학연구소의 해양 무인체계 업무협약, 서울대 공과대학과 삼성중공업의 ‘미래선박기술 글로벌협력 연구센터’ 설립 협약도 같은 시기에 이어졌다.</p><p>이 흐름은 한국 조선업에 기회이자 숙제다. 발주국이 현지 건조를 요구하는 사례가 늘어날수록 설계·엔지니어링 역량과 기술지원 체계가 수출 경쟁력의 핵심이 된다. 동시에 핵심 기술을 어디까지 공유하고 어떻게 관리할지, 국내 기자재 업체가 현지 공급망에 함께 진입할 수 있을지, 현지 공동생산이 국내 생산 기반과 어떻게 공존할지에 대한 고민도 깊어질 수밖에 없다.</p><p>페루 사업에서 국방부와 방위사업청, 주페루 한국대사관과 코트라가 측면 지원에 나섰듯, 함정 수출은 기업 혼자 감당하기 어려운 영역이다. 정부와 업계는 수출 협상 단계부터 기술 협력 범위와 보호 장치를 체계적으로 설계하고, 중소 기자재 기업의 동반 진출과 해외 현장을 이끌 엔지니어 양성에도 힘을 모아야 한다. 무인체계와 적층제조 같은 신기술 협력이 실제 함정과 MRO 시장으로 이어지도록 실증 기회를 넓히는 일도 중요하다.</p><p>K-조선의 다음 경쟁력은 배를 얼마나 잘 만드느냐를 넘어, 상대국의 산업과 함께 성장하는 협력 모델을 얼마나 설득력 있게 제시하느냐에 달려 있다. 신뢰를 기반으로 한 장기 협력의 경험이 쌓일수록 그 모델은 더 단단해질 것이다.</p>', '필리핀·페루 사례와 한·미 조선 협력 과제는 함정 수출의 경쟁력이 기술 협력과 현지 생태계 구축으로 옮겨가고 있음을 보여준다.', null, '2026-10-01T07:00:00+09:00'::timestamptz, array['K-조선', '함정 수출', '방산', 'HD현대', '한미 조선 협력']::text[], null),
  ('opinion', '콜드체인 경쟁력은 사람과 데이터에서 나온다', '<p>@@BYLINE@@&nbsp;콜드체인을 이야기할 때 우리는 흔히 창고의 규모나 냉동 설비의 성능부터 따진다. 물론 인프라는 출발점이다. 하지만 식품과 의약품이 온도를 지키며 국경과 운송 수단을 넘나드는 과정은 설비만으로 완성되지 않는다. 온도를 기록하고, 이탈을 감지하고, 규정에 맞게 대응하는 사람과 데이터가 함께 움직여야 비로소 콜드체인이 작동한다.</p><p>한국콜드체인협회는 이달 ‘제12기 콜드체인 전문가 양성과정’을 개강했다. 9월 5일부터 12월 5일까지 13회에 걸쳐 식품·의약품 콜드체인, 운송, 물류시설, 설비, 패키징, 관련 법규 등을 다루고, 교육 기간 중 싱가포르 콜드체인 연수도 진행한다. 협회가 국내 유일의 콜드체인 교육 프로그램이라고 소개한 이번 과정에는 KCTC, LX판토스, 농협물류 등 여러 기업 임직원이 참여했다.</p><p>해외 사례는 운영 역량이 어떻게 경쟁력이 되는지 보여준다. 캐세이 카고는 홍콩을 거점으로 신선화물 솔루션 ‘캐세이 프레시’와 의약품 솔루션 ‘캐세이 파마’를 통합 콜드체인 체계로 운영한다. 단일 항공화물 운송장으로 해외에서 홍콩국제공항을 거쳐 광둥·홍콩·마카오 대만구까지 신선화물을 운송하고, 의약품은 네 가지 온도 구간을 지원하는 전용 처리센터와 실시간에 가까운 데이터 로깅 시스템 ‘울트라 트랙’으로 관리한다. 설비와 절차, 데이터가 하나로 묶여 있다는 점이 핵심이다.</p><p>동남아시아 시장에는 기회와 위험이 공존한다. 비엣비즈코리아가 발간한 베트남 콜드체인 보고서는 현지 고객이 앞으로 창고 면적이나 차량 보유 대수보다 온도 관리 능력, 데이터 제공 역량, 식품·제약 규정 이해도, 에너지 효율, 라스트마일 대응력을 더 중요하게 볼 가능성이 크다고 진단했다. 이성주 비엣비즈코리아 대표는 “열악한 인프라는 K-푸드와 의약품 분야에는 위험 요소가 되지만, 콜드체인 솔루션 사업자에게는 중요한 시장 기회가 되고 있다”고 말했다. 인도네시아에서도 페레그린 콜드 로지스틱스가 현지 부동산 개발업체 시나르 프리메라와 합작해 냉동 보관 자산을 인수·개발하기로 하는 등 투자가 이어지고 있다.</p><p>데이터의 공백이 만드는 손실도 크다. 축산물 무역 테크 스타트업 핑크패커는 콜드체인 운송 중 온도가 이탈해도 도착 전까지 알 수 없는 구조를 지적하며, FAO 기준으로 전 세계에서 생산되는 육류의 20%가 이런 구조적 비효율 속에서 손실된다고 밝혔다. 회사는 IoT 기반 실시간 품질 추적 등을 묶은 육류 무역 운영체제 개발에 나섰다. 온도 데이터가 거래 당사자 사이의 신뢰 근거가 될 수 있다는 문제의식이다.</p><p>이 사례들이 가리키는 방향은 분명하다. 콜드체인의 경쟁력은 냉동고의 크기가 아니라, 온도라는 보이지 않는 품질을 얼마나 정확히 관리하고 증명할 수 있느냐에서 나온다. 그리고 그 일을 하는 것은 결국 숙련된 사람이다. 설비 투자가 늘어나도 이를 운영할 인력이 뒷받침되지 않으면 투자 효과는 반감될 수밖에 없다.</p><p>업계와 정책 당국이 함께 고민할 과제도 여기서 나온다. 전문 인력 양성 과정을 확대하고 현장 실무와 연계된 교육 기회를 늘려야 한다. 운송 구간마다 흩어진 온도 기록을 주고받을 수 있도록 데이터 형식과 기록 기준을 표준화하는 논의도 필요하다. 해외 콜드체인 시장에 진출하려는 국내 물류기업은 설비 확보에 앞서 현지 식품·의약품 규정과 운영 역량을 갖추는 데 공을 들여야 한다.</p><p>K-푸드와 의약품의 해외 진출이 늘어날수록 콜드체인은 수출 경쟁력의 일부가 된다. 온도를 지키는 일은 곧 신뢰를 지키는 일이다. 그 신뢰를 만드는 사람과 데이터에 대한 투자가 지금보다 더 중요해질 것이다.</p>', '냉장·냉동 인프라 확충이 이어지는 가운데, 온도 관리를 운영할 전문 인력과 데이터 체계가 콜드체인의 품질을 가른다.', null, '2026-09-24T07:00:00+09:00'::timestamptz, array['콜드체인', '전문인력 양성', '항공 콜드체인', '베트남 물류', '온도 관리']::text[], null),
  ('opinion', '화물운전자의 현장 지식, 데이터로 쌓을 때', '<p>@@BYLINE@@&nbsp;물류센터 앞에서 진입로를 찾지 못해 헤매거나 상하차 순서를 기다리며 대기하는 일은 화물운전자들에게 낯설지 않다. 이런 비효율은 통계에 잘 잡히지 않지만 운송 시간과 비용, 운전자의 피로로 고스란히 쌓인다. 최근 공개된 한 화물차 내비게이션의 데이터 분석은 이 보이지 않던 문제가 어디에 있는지를 숫자로 보여준다.</p><p>맵퍼스가 화물차 전용 내비게이션 ‘아틀란트럭’에 축적된 상하차지팁을 분석한 결과, 활성 팁은 9만8000여 건으로 전국 5만5000여 곳의 물류센터와 공장, 창고, 유통시설 정보를 담고 있었다. 특히 2026년 들어 9월 초까지 등록된 팁이 5만3149건으로, 2023년부터 2025년까지 3년간 등록된 4만4930건을 이미 넘어섰다. 운전자들이 스스로 현장 정보를 기록하고 나누려는 움직임이 빠르게 커지고 있다는 뜻이다.</p><p>어떤 정보가 공유되는지도 눈여겨볼 만하다. 가장 많이 등록된 정보는 ‘진입로·진입동선’으로 전체의 41.3%를 차지했고, 대기·소요시간, 상하차 위치·방식, 주차·대기공간 관련 정보가 뒤를 이었다. 열람은 오전 7시부터 10시 사이에 하루의 29%가 몰렸고, 2025년 추석 직전 1주간 평일 하루 평균 등록량은 평시 평일보다 16% 많았다. 김명준 맵퍼스 대표는 “약 10만 건의 데이터를 통해 화물운전자들에게 진입로와 대기시간처럼 지도만으로 알기 어려운 현장 정보가 중요하다는 점을 확인할 수 있었다”고 말했다.</p><p>이 데이터가 던지는 메시지는 분명하다. 화물운송의 효율을 좌우하는 것은 도로 위 주행만이 아니라 목적지 도착 전후의 마지막 구간이라는 점이다. 그리고 그 정보는 지금까지 상당 부분 운전자 개인의 경험과 기억에 의존해 왔다. 앱 속에 쌓이는 팁은 그 경험이 비로소 공유 가능한 자산으로 바뀌고 있음을 보여준다.</p><p>자동화 기술도 바로 이런 구간을 겨냥하고 있다. 미국 자율주행 트럭 기업 개틱은 2억달러 규모의 시리즈 D 투자를 유치했다고 밝히면서, 완전 무인 운송 주문 8만5000건을 완료하고 운영 전반에서 정시 배송률 99%를 달성했다고 소개했다. 개틱의 트럭은 물류센터와 매장을 잇는 고빈도 지역 운송 네트워크를 달린다. 국내 어빌리티시스템즈는 이달 초 방콕에서 열린 ‘CTAC Asia 2026’에서 기존 야드트랙터에 자율주행 시스템을 적용하는 개조 방식의 항만 솔루션을 소개했다. 반복적이고 구조화된 구간부터 자동화가 진행되고 있는 것이다.</p><p>그렇다고 자동화가 운전자의 현장 지식을 대신할 수 있는 것은 아니다. 오히려 자율주행 트럭이 제대로 움직이려면 진입 동선과 대기 공간, 상하차 위치 같은 정보가 정밀한 데이터로 정리돼 있어야 한다. 운전자들이 쌓아온 현장 지식은 사람이 운전하든 기계가 운전하든 화물운송 디지털화의 기초 자산이 될 수 있다.</p><p>여기서 업계가 함께 생각해 볼 과제가 있다. 진입로와 대기시간 정보는 본래 물류센터와 화주가 먼저 제공해야 할 정보이기도 하다. 상하차지의 출입 동선과 입고 시간, 필요 서류 같은 기본 정보를 표준화된 형태로 공개하는 업계 관행과 이를 뒷받침할 제도적 유도가 필요하다. 대기시간을 줄이는 상하차 예약 문화가 자리 잡도록 화주와 운송사가 함께 노력해야 하며, 디지털 도구가 낯선 운전자도 쉽게 활용할 수 있도록 교육과 지원이 뒤따라야 한다.</p><p>화물운송의 디지털 전환은 거창한 기술에서만 시작되지 않는다. 운전자 한 사람 한 사람이 남긴 현장 기록이 모여 시행착오를 줄이는 지도가 되듯, 현장의 목소리를 데이터로 존중하는 데서 더 나은 운송 환경이 만들어질 것이다.</p>', '상하차지 현장 정보 공유가 빠르게 늘어난 것은 지도 밖 정보가 운송 효율을 좌우한다는 방증이며, 자동화 논의도 이 지점에서 출발해야 한다.', null, '2026-09-28T07:00:00+09:00'::timestamptz, array['화물운전자', '화물차 내비게이션', '상하차', '자율주행 트럭', '운송 디지털화']::text[], null),
  ('opinion', '해운 AI 전환, 모델보다 데이터 표준이 먼저다', '<p>@@BYLINE@@&nbsp;해운·물류 업계에서 AI는 이제 피할 수 없는 화두가 됐다. 대화형 AI가 항차 정보를 찾아주고, AI 에이전트가 무역 서류의 오류를 잡아내는 실증도 이뤄졌다. 그러나 개념 검증(PoC)을 실제 운영 환경으로 넓히는 문턱은 여전히 높다. 그 이유를 기술의 한계에서만 찾기보다, AI가 읽어야 할 데이터가 제각각이라는 현실에서 찾아볼 필요가 있다.</p><p>씨벤티지는 지난 7월 22일 한국해양진흥공사가 개최한 ‘2026년 제2차 해양산업 AI 전환 실무협의회’에서 이 문제를 구체적으로 짚었다. 선박의 입항·접안·출항 시간은 출처에 따라 이벤트 판별 기준이나 기록 시점이 달라질 수 있고, 운항 스케줄도 선사별 제공 형식과 업데이트 주기, 항만·터미널 코드가 일치하지 않을 수 있다는 것이다. 파트너 선사의 스케줄을 이메일이나 엑셀, PDF로 받아 수기로 반영하는 과정에서 업데이트 지연과 데이터 불일치가 생기기도 한다.</p><p>씨벤티지는 전산화와 업무 프로세스 자동화 다음 단계로 데이터를 통합·표준화하는 ‘데이터화’를 제시했다. 선사별로 다른 스케줄 형식과 코드를 단일 스키마로 표준화해 API와 웹훅으로 공유하는 ‘Schedule Data Hub’를 국내 선사와 초기 검증 중이며, 약 94개 항구와 256개 터미널, 1000척 규모의 선박을 대상으로 실제 입항·접안·출항 정보를 표준화해 국내 선사의 기존 시스템에 연계한 사례도 소개했다. 정영배 씨벤티지 상무는 “AI를 실제 운영에 적용하려면 모델뿐 아니라 입력 데이터가 같은 기준으로 정리돼 있는지도 함께 살펴볼 필요가 있다”고 말했다.</p><p>글로벌 해운 소프트웨어 기업도 같은 방향을 가리킨다. Veson Nautical은 IMOS와 대화형 AI ‘CoCaptain’ 등을 하나로 묶은 ‘Veson Platform’을 출시하면서, 6만5000척 이상의 선박에 대해 300개 이상의 데이터 필드를 제공하는 Vessel Insights와 1300개 이상 항구의 일별 벙커 가격 예측을 제공하는 Bunker Insights를 함께 선보였다. 핵심 운영 시스템과 신뢰할 수 있는 데이터를 AI와 결합하겠다는 전략이다. 공동 창립자인 John Veson CEO는 “기술은 사람의 판단을 대체하는 것이 아니라, 더 나은 판단을 내릴 수 있도록 도와야 한다”고 말했다.</p><p>무역 현장에서도 비슷한 시도가 이어진다. 포스코인터내셔널은 LG CNS와 함께 블록체인 공동원장 기반 거래 상태 공유와 AI Agent 기반 신용장·무역서류 검토 등을 실증하는 기술 검증을 마쳤다. 신용장 오타나 조항 누락 같은 단순 오류도 대금 지급 지연이나 거절로 이어질 수 있는 만큼, 거래 참여자가 동일한 거래 상태를 실시간으로 확인하는 기반이 중요하다는 문제의식이다. 공급망 소프트웨어 기업 키넥시스는 AI 역량이 광범위하게 배포됐음에도 공급망 리더의 12%만이 스스로를 AI 선도기업으로 평가한다고 밝혔다.</p><p>이 사례들의 공통분모는 AI의 성과가 모델의 성능만큼이나 데이터의 정합성에 달려 있다는 점이다. 같은 ‘입항 시간’을 두고 시스템마다 다른 값을 내놓는다면 아무리 뛰어난 모델도 신뢰받기 어렵다. 데이터 표준화는 화려하지 않지만, AI 전환의 성패를 가르는 기초 공사다.</p><p>그렇다면 무엇이 필요할까. 우선 항만·터미널 코드와 운항 이벤트 정의처럼 업계가 공통으로 쓰는 데이터의 기준을 맞추는 논의가 공공과 민간 협의체를 중심으로 꾸준히 이어져야 한다. 개별 기업이 기존 시스템을 통째로 바꾸지 않고도 표준 데이터를 단계적으로 연결할 수 있는 방식이 확산되도록 지원하는 것도 방법이다. 데이터를 공유하는 기업이 실질적인 혜택을 얻는 구조를 설계하고, 데이터 보안과 활용 범위에 대한 원칙도 함께 마련해야 한다.</p><p>AI 전환은 결국 사람의 판단을 더 나은 방향으로 돕기 위한 과정이다. 그 출발점은 모두가 같은 기준으로 데이터를 주고받는 환경을 만드는 데 있다. 해운 업계가 기초 공사에 충분한 시간을 들일수록 AI가 현장에 뿌리내리는 속도도 빨라질 것이다.</p>', 'AI 도입 경쟁이 뜨겁지만 선박·항만·스케줄 데이터의 기준이 맞지 않으면 개념 검증은 실제 운영으로 이어지기 어렵다.', null, '2026-09-27T07:00:00+09:00'::timestamptz, array['해운 데이터', '데이터 표준화', 'AI 전환', '해운 플랫폼', '디지털 전환']::text[], null)
) as v(slug, title, body, excerpt, thumb, published_at, tags, guid)
join categories c on c.outlet_id = ctx.outlet_id and c.slug = v.slug
where not exists (select 1 from articles a where a.outlet_id = ctx.outlet_id and a.title = v.title);

-- 3) 기자명 '관리자', 기자 이메일 비우기
--    (기자 이메일은 DB 규칙이 대표 이메일로 채우므로, 잠깐 그 규칙을 끄고 비운 뒤 다시 켠다)
do $fix$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'byline') then
    update articles a set byline = '관리자'
    from outlets o where a.outlet_id = o.id and o.name = 'Shipping Times' and a.body like '<p>[%=관리자 기자]%';
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'byline_email') then
    if exists (select 1 from pg_trigger where tgname = 'articles_byline_email') then
      alter table articles disable trigger articles_byline_email;
    end if;
    update articles a set byline_email = null
    from outlets o where a.outlet_id = o.id and o.name = 'Shipping Times' and a.body like '<p>[%=관리자 기자]%';
    if exists (select 1 from pg_trigger where tgname = 'articles_byline_email') then
      alter table articles enable trigger articles_byline_email;
    end if;
  end if;
end
$fix$;

-- 확인: select status, count(*) from articles a join outlets o on o.id = a.outlet_id where o.name = 'Shipping Times' group by status;
